# =============================================================================
# ToggleSwitch - pill toggle (same as company defaults)
# =============================================================================

class _TogglePill(QWidget):
    def __init__(self, size=20, parent=None):
        super().__init__(parent)
        self._size     = size
        self._checked  = False
        self._knob_pos = 0.0
        self.setFixedSize(int(2.2 * size), size)
        self.setCursor(Qt.PointingHandCursor)
        self._anim = QPropertyAnimation(self, b"knob_pos", self)
        self._anim.setDuration(220)
        self._anim.setEasingCurve(QEasingCurve.InOutCubic)

    def _get_knob_pos(self): return self._knob_pos
    def _set_knob_pos(self, v):
        self._knob_pos = v; self.update()
    knob_pos = _Prop(float, _get_knob_pos, _set_knob_pos)

    def isChecked(self): return self._checked
    def setChecked(self, value: bool, animated=False):
        self._checked = bool(value)
        target = 1.0 if self._checked else 0.0
        if animated:
            self._anim.stop()
            self._anim.setStartValue(self._knob_pos)
            self._anim.setEndValue(target)
            self._anim.start()
        else:
            self._knob_pos = target; self.update()
    def mousePressEvent(self, _ev):
        self.setChecked(not self._checked, animated=True)

    def paintEvent(self, _ev):
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        s = self._size; w = self.width(); h = self.height(); r = h / 2
        t = self._knob_pos
        if t < 0.01:
            p.setBrush(QColor("#d7d7d7")); p.setPen(Qt.NoPen)
            p.drawRoundedRect(0, 0, w, h, r, r)
        else:
            grad = QLinearGradient(0, 0, w, 0)
            grad.setColorAt(0, QColor("#f19af3")); grad.setColorAt(1, QColor("#f099b5"))
            p.setBrush(QColor("#d7d7d7")); p.setPen(Qt.NoPen)
            p.drawRoundedRect(0, 0, w, h, r, r)
            if t > 0.99:
                p.setBrush(grad); p.drawRoundedRect(0, 0, w, h, r, r)
            else:
                p.setOpacity(t); p.setBrush(grad)
                p.drawRoundedRect(0, 0, w, h, r, r); p.setOpacity(1.0)
        knob_d = 0.8*s; knob_r = knob_d/2
        off_x = 0.1*s; on_x = 1.3*s
        knob_x = off_x + self._knob_pos*(on_x - off_x); knob_y = 0.1*s
        cx = knob_x+knob_r; cy = knob_y+knob_r
        shadow = QRadialGradient(cx, cy+4, knob_r*1.1)
        shadow.setColorAt(0, QColor(0,0,0,55)); shadow.setColorAt(0.6, QColor(0,0,0,30))
        shadow.setColorAt(1, QColor(0,0,0,0))
        p.setBrush(shadow); p.setPen(Qt.NoPen)
        p.drawEllipse(int(knob_x-knob_r*0.15), int(knob_y+knob_r*0.5),
                      int(knob_d*1.3), int(knob_d*0.9))
        kg = QLinearGradient(cx, knob_y, cx, knob_y+knob_d)
        kg.setColorAt(0, QColor("#dedede")); kg.setColorAt(1, QColor("#ffffff"))
        p.setBrush(kg); p.setPen(Qt.NoPen)
        p.drawEllipse(int(knob_x), int(knob_y), int(knob_d), int(knob_d))
        p.end()

# =============================================================================
# UOM Picker Dialog - shown when a product has multiple selling UOMs
# =============================================================================
class UomPickerDialog(QDialog):
    """Touch-friendly UOM picker - shows each unit and price as a large tappable button."""

    def __init__(self, product_name: str, uom_prices: list[dict], parent=None):
        super().__init__(parent)
        self.setWindowTitle("Select Unit / Pack Size")
        n = len(uom_prices)
        self.setFixedSize(460, min(110 + n * 82 + 60, 580))
        self.setModal(True)
        self.setFocusPolicy(Qt.StrongFocus)
        self.setStyleSheet(f"""
            QDialog {{
                background: {WHITE};
                font-family: 'Segoe UI', sans-serif;
            }}
        """)
        self.selected_uom   = None
        self.selected_price = None
        self._uom_buttons: list[tuple[QPushButton, str, float]] = []
        self._active_idx = 0
        self._build(product_name, uom_prices)
        self._refresh_active_highlight()
        self.setFocus()

    def _get_currency_symbol(self) -> str:
        try:
            from models.company_defaults import get_currency_symbol
            return get_currency_symbol()
        except Exception:
            return "$"

    def _build(self, product_name: str, uom_prices: list[dict]):
        root = QVBoxLayout(self)
        root.setContentsMargins(24, 20, 24, 20)
        root.setSpacing(0)

        hdr = QWidget()
        hdr.setStyleSheet(f"background:{NAVY}; border-radius:10px;")
        hdr_layout = QVBoxLayout(hdr)
        hdr_layout.setContentsMargins(16, 12, 16, 12)
        hdr_layout.setSpacing(2)

        lbl_prompt = QLabel("Select unit / pack size")
        lbl_prompt.setStyleSheet("color:rgba(255,255,255,0.7); font-size:11px; font-weight:500; background:transparent;")
        lbl_name = QLabel(product_name)
        lbl_name.setStyleSheet("color:#ffffff; font-size:15px; font-weight:bold; background:transparent;")
        lbl_name.setWordWrap(True)
        hdr_layout.addWidget(lbl_prompt)
        hdr_layout.addWidget(lbl_name)
        root.addWidget(hdr)
        root.addSpacing(14)

        for i, up in enumerate(uom_prices):
            uom   = str(up.get("uom",   "Nos")).strip()
            price = float(up.get("price", 0))

            btn = QPushButton()
            btn.setFixedHeight(70)
            btn.setCursor(Qt.PointingHandCursor)
            btn.setFocusPolicy(Qt.NoFocus)

            btn_layout = QHBoxLayout(btn)
            btn_layout.setContentsMargins(18, 0, 18, 0)

            uom_lbl = QLabel(uom)
            uom_lbl.setObjectName("uom_lbl")
            uom_lbl.setStyleSheet("font-size:16px; font-weight:600; background:transparent;")

            sym = self._get_currency_symbol()
            price_lbl = QLabel(f"{sym}{price:.2f}")
            price_lbl.setObjectName("price_lbl")
            price_lbl.setStyleSheet("font-size:18px; font-weight:bold; background:transparent;")
            price_lbl.setAlignment(Qt.AlignRight | Qt.AlignVCenter)

            btn_layout.addWidget(uom_lbl, 1)
            btn_layout.addWidget(price_lbl)

            btn.clicked.connect(lambda _, u=uom, pr=price: self._pick(u, pr))
            self._uom_buttons.append((btn, uom, price))
            root.addWidget(btn)
            if i < len(uom_prices) - 1:
                root.addSpacing(8)

        root.addSpacing(14)

        cancel = QPushButton("Cancel")
        cancel.setIcon(qta.icon("fa5s.times"))
        cancel.setFixedHeight(46)
        cancel.setCursor(Qt.PointingHandCursor)
        cancel.setFocusPolicy(Qt.NoFocus)
        cancel.setStyleSheet(f"""
            QPushButton {{
                background: {WHITE}; color: {MUTED};
                border: 1px solid {BORDER}; border-radius: 8px;
                font-size: 13px; font-weight: 600;
            }}
            QPushButton:hover {{ background: {LIGHT}; color: {DARK_TEXT}; }}
        """)
        cancel.clicked.connect(self.reject)
        root.addWidget(cancel)

    def _pick(self, uom: str, price: float):
        self.selected_uom   = uom
        self.selected_price = price
        self.accept()

    def _refresh_active_highlight(self):
        for i, (btn, _u, _p) in enumerate(self._uom_buttons):
            if i == self._active_idx:
                btn.setStyleSheet("""
                    QPushButton {
                        background: #e0f2fe;
                        border: 2px solid #0284c7;
                        border-radius: 10px;
                    }
                    QLabel#uom_lbl { color: #0369a1; font-size: 16px; font-weight: 700; background: transparent; }
                    QLabel#price_lbl { color: #0284c7; font-size: 18px; font-weight: 800; background: transparent; }
                """)
            else:
                btn.setStyleSheet("""
                    QPushButton {
                        background: #ffffff;
                        border: 1.5px solid #cbd5e1;
                        border-radius: 10px;
                    }
                    QLabel#uom_lbl { color: #1e293b; font-size: 16px; font-weight: 600; background: transparent; }
                    QLabel#price_lbl { color: #0284c7; font-size: 18px; font-weight: 700; background: transparent; }
                    QPushButton:hover {
                        background: #f0f9ff;
                        border-color: #0284c7;
                    }
                """)

    def showEvent(self, event):
        super().showEvent(event)
        def _force_focus():
            self.activateWindow()
            self.raise_()
            self.setFocus(Qt.PopupFocusReason)
            self.grabKeyboard()
        from PySide6.QtCore import QTimer
        QTimer.singleShot(50, _force_focus)

    def hideEvent(self, event):
        self.releaseKeyboard()
        super().hideEvent(event)

    def keyPressEvent(self, event):
        k = event.key()
        n = len(self._uom_buttons)
        if n == 0:
            return super().keyPressEvent(event)
        if k == Qt.Key_Up:
            self._active_idx = (self._active_idx - 1) % n
            self._refresh_active_highlight()
            event.accept()
            return
        if k == Qt.Key_Down:
            self._active_idx = (self._active_idx + 1) % n
            self._refresh_active_highlight()
            event.accept()
            return
        if k in (Qt.Key_Return, Qt.Key_Enter):
            _btn, uom, price = self._uom_buttons[self._active_idx]
            self._pick(uom, price)
            event.accept()
            return
        if k == Qt.Key_Escape:
            self.reject()
            event.accept()
            return
        super().keyPressEvent(event)

class _ToggleSwitch(QWidget):
    """Pill toggle + label. API: isChecked() / setChecked(bool)."""
    def __init__(self, label: str, size: int = 18, parent=None):
        super().__init__(parent)
        layout = QHBoxLayout(self)
        layout.setContentsMargins(5, 5, 5, 5)
        layout.setSpacing(12)
        self._pill = _TogglePill(size=size, parent=self)
        layout.addWidget(self._pill)
        self._lbl = QLabel(label)
        self._lbl.setStyleSheet(f"font-size:13px; font-weight:600; color:{DARK_TEXT}; background:transparent;")
        layout.addWidget(self._lbl)
        layout.addStretch()

    def isChecked(self) -> bool: return self._pill.isChecked()
    def setChecked(self, value: bool): self._pill.setChecked(value, animated=False)

def load_category_settings() -> dict:
    try:
        if _CAT_SETTINGS_FILE.exists():
            return _json_mod.loads(_CAT_SETTINGS_FILE.read_text(encoding="utf-8"))
    except Exception:
        pass
    return {}

def load_disabled_categories() -> list:
    """Return list of category names that are switched OFF for this branch."""
    return load_category_settings().get("disabled_categories", [])

def load_negative_stock_categories() -> list:
    """Return list of category names that can be sold without stock."""
    return load_category_settings().get("negative_stock_categories", [])

def save_category_settings(disabled: list, negative_stock: list) -> None:
    """Persist the lists to disk."""
    try:
        _CAT_SETTINGS_FILE.parent.mkdir(parents=True, exist_ok=True)
        data = load_category_settings()
        data["disabled_categories"] = disabled
        data["negative_stock_categories"] = negative_stock
        _CAT_SETTINGS_FILE.write_text(
            _json_mod.dumps(data, indent=2),
            encoding="utf-8",
        )
    except Exception as _e:
        import logging as _log
        _log.getLogger("main_window").warning("Could not save category settings: %s", _e)


