        from PySide6.QtCharts import QChart, QChartView
        self._stock_chart = QChart()
        self._stock_chart.setTitle("Top Stock by Quantity")
        self._stock_chart.setAnimationOptions(QChart.SeriesAnimations)
        
        cv = QChartView(self._stock_chart)
        cv.setStyleSheet(f"background:{WHITE}; border:none; border-radius:8px;")
        lay.addWidget(cv, 1)

