    def _filter_stock(self, query: str):
        if not hasattr(self, "_all_stock"):
            return
        ql = query.lower()
        if not ql:
            self._render_stock(self._all_stock)
        else:
            self._render_stock([
                p for p in self._all_stock
                if ql in (p.get("name", "") or "").lower()
                or ql in (p.get("part_no", "") or "").lower()
                or ql in (p.get("category", "") or "").lower()
            ])

    def _render_stock(self, products: list):
        if not hasattr(self, "stock_report") or not hasattr(self.stock_report, "table"):
            return
        self.stock_report.table.setRowCount(0)
        tot_cost = tot_sell = 0.0
        for p in products:
            qty = float(p.get("stock", 0) or 0)
            cost = float(p.get("cost_price", 0) or 0)
            sell = float(p.get("price", 0) or 0)
            val_cost = qty * cost
            val_sell = qty * sell
            tot_cost += val_cost
            tot_sell += val_sell

            r = self.stock_report.table.rowCount()
            self.stock_report.table.insertRow(r)
            vals = [
                str(p.get("part_no") or ""),
                str(p.get("name") or ""),
                str(p.get("category") or ""),
                f"{qty:.2f}",
                f"${cost:.2f}",
                f"${sell:.2f}",
                f"${val_cost:.2f}",
                f"${val_sell:.2f}",
                f"${(val_sell - val_cost):.2f}",
                str(p.get("reorder_level") or "0"),
                "Yes" if p.get("track_stock") else "No",
                "Yes" if p.get("is_pharmacy_product") else "No",
                "Yes" if p.get("is_butchery_product") else "No",
                "Yes" if p.get("is_product_bundle") else "No"
            ]
            alignments = [
                Qt.AlignLeft | Qt.AlignVCenter,
                Qt.AlignLeft | Qt.AlignVCenter,
                Qt.AlignCenter,
                Qt.AlignCenter,
                Qt.AlignRight | Qt.AlignVCenter,
                Qt.AlignRight | Qt.AlignVCenter,
                Qt.AlignRight | Qt.AlignVCenter,
                Qt.AlignRight | Qt.AlignVCenter,
                Qt.AlignRight | Qt.AlignVCenter,
                Qt.AlignCenter, Qt.AlignCenter, Qt.AlignCenter, Qt.AlignCenter, Qt.AlignCenter
            ]
            for ci, (val, aln) in enumerate(zip(vals, alignments)):
                it = QTableWidgetItem(val)
                it.setTextAlignment(aln)
                if ci >= 10:
                    val_str = str(val).strip()
                    it.setText(val_str if val_str else "N/A")
                if ci == 0:
                    it.setData(Qt.UserRole, p)
                if ci == 3 and qty <= 5:
                    it.setForeground(QColor(DANGER))
                if ci == 6:
                    it.setForeground(QColor(NAVY))
                if ci == 7:
                    it.setForeground(QColor(ACCENT))
                self.stock_report.table.setItem(r, ci, it)
            self.stock_report.table.setRowHeight(r, 32)

        if hasattr(self, "_lbl_tot_cost"):
            self._lbl_tot_cost.setText(f"Total @ Cost: ${tot_cost:,.2f}")
        if hasattr(self, "_lbl_tot_sell"):
            self._lbl_tot_sell.setText(f"Total @ Sale: ${tot_sell:,.2f}")
        if hasattr(self, "_lbl_tot_prof"):
            self._lbl_tot_prof.setText(f"Potential Profit: ${(tot_sell - tot_cost):,.2f}")
        if hasattr(self, "_stock_count_lbl"):
            n = self.stock_report.table.rowCount()
            self._stock_count_lbl.setText(f"{n} product{'s' if n != 1 else ''}")

        if hasattr(self, "_stock_chart"):
            try:
                self._stock_chart.removeAllSeries()
                for ax in self._stock_chart.axes():
                    self._stock_chart.removeAxis(ax)
                    
                from PySide6.QtCharts import QSplineSeries, QBarCategoryAxis, QValueAxis
                from database.db import get_connection, fetchall_dicts
                
                conn = get_connection(); cur = conn.cursor()
                try:
                    cur.execute("""
                        SELECT TOP 14 CAST(se.date AS DATE) as dt, SUM(sei.qty * ISNULL(p.cost_price, 0)) as val_change
                        FROM stock_entries se
                        JOIN stock_entry_items sei ON se.id = sei.parent_id
                        JOIN products p ON sei.product_id = p.id
                        GROUP BY CAST(se.date AS DATE)
                        ORDER BY CAST(se.date AS DATE) ASC
                    """)
                    history = fetchall_dicts(cur)
                except:
                    history = []
                finally:
                    conn.close()

                series = QSplineSeries()
                series.setName("Net Valuation Change ($)")
                
                pen = series.pen()
                pen.setWidth(3)
                pen.setColor(QColor(ACCENT))
                series.setPen(pen)
                
                categories = []
                max_val = 0
                min_val = 0

                if history:
                    self._stock_chart.setTitle("Daily Valuation Changes (Last 14 Days)")
                    for i, row in enumerate(history):
                        val = float(row.get("val_change", 0) or 0)
                        if val > max_val: max_val = val
                        if val < min_val: min_val = val
                        series.append(i, val)
                        d_str = str(row["dt"])
                        categories.append(d_str[-5:])
                else:
                    self._stock_chart.setTitle("Top Stock Valuation")
                    top_products = sorted(products, key=lambda x: float(x.get("stock", 0) or 0) * float(x.get("cost_price", 0) or 0), reverse=True)[:10]
                    for i, p in enumerate(top_products):
                        val = float(p.get("stock", 0) or 0) * float(p.get("cost_price", 0) or 0)
                        if val > max_val: max_val = val
                        if val < min_val: min_val = val
                        series.append(i, val)
                        name = p.get("name", "Unknown")
                        categories.append(name[:15] + ".." if len(name) > 15 else name)

                if categories:
                    self._stock_chart.addSeries(series)

                    axisX = QBarCategoryAxis()
                    axisX.append(categories)
                    self._stock_chart.addAxis(axisX, Qt.AlignBottom)
                    series.attachAxis(axisX)
                    
                    axisY = QValueAxis()
                    margin = (max_val - min_val) * 0.1 if max_val != min_val else 10
                    axisY.setRange(min_val - margin, max_val + margin)
                    self._stock_chart.addAxis(axisY, Qt.AlignLeft)
                    series.attachAxis(axisY)
            except Exception as e:
                print(f"Error rendering stock chart: {e}")

    def _export_stock_csv(self):
        if not hasattr(self, "stock_report") or not hasattr(self.stock_report, "table"):
            return
        try:
            from PySide6.QtWidgets import QFileDialog
            path, _ = QFileDialog.getSaveFileName(
                self, "Export Excel", "Inventory_Stock.csv",
                "CSV Files (*.csv)"
            )
            if not path:
                return
            import csv
            with open(path, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                headers = []
                for ci in range(self.stock_report.table.columnCount()):
                    headers.append(
                        self.stock_report.table.horizontalHeaderItem(ci).text()
                        if self.stock_report.table.horizontalHeaderItem(ci) else ""
                    )
                writer.writerow(headers)
                for r in range(self.stock_report.table.rowCount()):
                    row = []
                    for ci in range(self.stock_report.table.columnCount()):
                        it = self.stock_report.table.item(r, ci)
                        row.append(it.text() if it else "")
                    writer.writerow(row)
            QMessageBox.information(self, "Exported", f"Stock exported to:\n{path}")
        except Exception as e:
            QMessageBox.warning(self, "Export Error", str(e))

    def _generate_stock_html(self):
        if not hasattr(self, "stock_report") or not hasattr(self.stock_report, "table"):
            return ""
        company_name = "Havano POS"
        try:
            from database.db import get_connection
            conn = get_connection()
            if conn:
                cur = conn.cursor()
                cur.execute("SELECT company_name FROM company_settings LIMIT 1")
                row = cur.fetchone()
                if row and row[0]:
                    company_name = str(row[0])
                conn.close()
        except Exception:
            pass

        html = "<html><body style='font-family: sans-serif; margin: 0px 20px 20px 20px;'>"
        html += "<table width='100%' cellpadding='0' cellspacing='0'><tr><td align='center'>"
        html += f"<div style='font-size: 26px; color: #333; margin: 0 0 5px 0; font-weight: bold;'>{company_name}</div>"
        html += "<div style='font-size: 22px; color: #1e3a8a; margin: 0 0 10px 0; font-weight: bold;'>Inventory Stock List</div>"
        html += "</td></tr></table>"
        
        html += "<table width='100%' cellpadding='0' cellspacing='0' style='border-collapse:collapse; font-size:12px;'>"
        html += "<thead>"
        html += "<tr style='background-color:#f3f4f6; color:#333;'>"
        
        col_widths = ['10%', '25%', '15%', '10%', '10%', '10%', '10%', '10%']
        
        for c in range(self.stock_report.table.columnCount()):
            align = 'right' if c >= 3 else 'left'
            w = col_widths[c] if c < len(col_widths) else 'auto'
            html += f"<th width='{w}' style='padding:8px; font-weight:bold; border-bottom:2px solid #aaa; text-align:{align};'>{self.stock_report.table.horizontalHeaderItem(c).text()}</th>"
        html += "</tr>"
        html += "</thead><tbody>"
        
        for r in range(self.stock_report.table.rowCount()):
            bg = "#ffffff" if r % 2 == 0 else "#fcfcfc"
            html += f"<tr style='background-color:{bg};'>"
            for c in range(self.stock_report.table.columnCount()):
                item = self.stock_report.table.item(r, c)
                text = item.text() if item else ""
                align = 'right' if c >= 3 else 'left'
                html += f"<td style='padding:6px; border-bottom:1px solid #eee; text-align:{align};'>{text}</td>"
            html += "</tr>"
            
        html += "</tbody></table></body></html>"
        return html

    def _preview_stock_pdf(self):
        if not hasattr(self, "stock_report") or not hasattr(self.stock_report, "table"):
            return
        try:
            from services.browser_print_service import BrowserPrintService
            html = self._generate_stock_html()
            BrowserPrintService.print_html(html, "Inventory_Stock_Report.pdf")
        except Exception as e:
            from PySide6.QtWidgets import QMessageBox
            QMessageBox.critical(self, "Preview Error", str(e))
            
    def _print_stock_pdf(self):
        self._preview_stock_pdf()

