    def _open_company_defaults_nav(self):
        """Open company defaults from nav-bar hover menu - full screen."""
        try:
            from views.pages.company_defaults_page import CompanyDefaultsPage
            parent_win = self.parent_window or self
            dlg = QDialog(parent_win)
            dlg.setWindowTitle("Company Defaults")
            dlg.setWindowFlag(Qt.Tool, False)
            # Override closeEvent so the OS window X just closes this dialog,
            # not the entire application.
            dlg.closeEvent = lambda event: (dlg.accept(), event.accept())
            dlg.setStyleSheet(f"QDialog {{ background: {OFF_WHITE}; }}")
            lay = QVBoxLayout(dlg)
            lay.setContentsMargins(0, 0, 0, 0)
            lay.addWidget(CompanyDefaultsPage(parent=dlg))
            dlg.setWindowState(Qt.WindowMaximized)
            dlg.exec()
            
            # Refresh visibility of Orders button after settings close
            if hasattr(self, '_pos_view') and hasattr(self._pos_view, 'orders_btn'):
                try:
                    from models.restaurant_order import is_restaurant_enabled
                    self._pos_view.orders_btn.setVisible(is_restaurant_enabled())
                except Exception: pass
        except Exception as e:
            QMessageBox.warning(self, "Error", f"Could not open Company Defaults:\n{e}")

    def _open_adv_printing_nav(self):
        """Open Advanced Printing from settings_dialog."""
        try:
            from views.dialogs.settings_dialog import SettingsDialog as _SD
            # AdvanceSettingsDialog may live in settings_dialog or advance_settings_dialog
            try:
                from views.dialogs.advance_settings_dialog import AdvanceSettingsDialog as _ASD
                _ASD(self.parent_window or self).exec()
            except ImportError:
                _SD(self.parent_window or self).exec()
        except Exception as e:
            QMessageBox.warning(self, "Error", f"Could not open Advanced Printing:\n{e}")

    # =========================================================================
    # LEFT PANEL
    # =========================================================================
    def _build_left_panel(self):
        panel = QWidget(); panel.setStyleSheet(f"background-color: {OFF_WHITE};")
        panel.setMinimumHeight(290)
        layout = QVBoxLayout(panel)
        layout.setSpacing(0); layout.setContentsMargins(0, 0, 0, 0)
        layout.addWidget(self._build_customer_search_strip())
        layout.addWidget(self._build_invoice_table(), 1)
        layout.addWidget(self._build_invoice_footer())
        return panel

    def _open_item_note_popup(self, row: int):
        """Open a sleek single-line popup with autocomplete for item notes."""
        name_item = self.invoice_table.item(row, self.COL_NAME)
        if not name_item or not name_item.text().strip():
            return

        notes_item = self.invoice_table.item(row, self.COL_NOTES)
        raw        = notes_item.text().strip() if notes_item else ""
        existing   = raw.lstrip("*").strip() if raw.startswith("*") else raw
        is_danger  = bool(existing)  # red clear btn when there's already a note

        # ── Load predefined notes ─────────────────────────────────────────
        predefined = []
        try:
            from models.restaurant_order import get_predefined_notes
            predefined = get_predefined_notes()
        except Exception:
            pass

        # ── Build compact dialog ──────────────────────────────────────────
        dlg = QDialog(self)
        dlg.setWindowTitle("Item Note")
        dlg.setFixedWidth(1100)
        dlg.setStyleSheet(f"""
            QDialog {{ background: {WHITE}; border: 1px solid {NAVY}; border-radius: 12px; }}
        """)
        dlg.setWindowFlags(Qt.Dialog | Qt.FramelessWindowHint)

        v = QVBoxLayout(dlg)
        v.setContentsMargins(15, 12, 15, 12)
        v.setSpacing(10)

        header = QLabel(f"*  {name_item.text().strip()}")
        header.setStyleSheet(f"font-size: 13px; color: {NAVY}; font-weight: bold; padding-left: 2px;")
        v.addWidget(header)

        lay = QHBoxLayout()
        lay.setSpacing(10)

        edit = QLineEdit(existing)
        edit.setPlaceholderText("Instruction (e.g. No onions)...")
        edit.setFixedHeight(44)
        edit.setStyleSheet(f"""
            QLineEdit {{
                border: 1px solid {BORDER}; border-radius: 8px;
                padding: 0 15px; font-size: 15px; color: {DARK_TEXT};
                background: {OFF_WHITE};
            }}
            QLineEdit:focus {{ border-color: {ACCENT}; background: {WHITE}; }}
        """)

        # Autocomplete
        if predefined:
            completer = QCompleter(predefined, edit)
            completer.setCaseSensitivity(Qt.CaseInsensitive)
            completer.setFilterMode(Qt.MatchContains)
            completer.setCompletionMode(QCompleter.PopupCompletion)
            completer.popup().setStyleSheet(f"""
                QListView {{
                    background: {WHITE}; border: 1px solid {BORDER};
                    border-radius: 6px; font-size: 14px; color: {DARK_TEXT};
                    padding: 4px;
                }}
                QListView::item {{ padding: 8px 12px; }}
                QListView::item:selected {{ background: {ACCENT}; color: {WHITE}; }}
            """)
            edit.setCompleter(completer)

        lay.addWidget(edit, 1)

        ok_btn = QPushButton("OK")
        ok_btn.setFixedSize(140, 44)
        ok_btn.setCursor(Qt.PointingHandCursor)
        ok_btn.setStyleSheet(f"""
            QPushButton {{
                background: {SUCCESS}; color: {WHITE}; border: none;
                border-radius: 8px; font-size: 20px; font-weight: bold;
            }}
            QPushButton:hover {{ background: {SUCCESS_H}; }}
        """)
        ok_btn.clicked.connect(dlg.accept)
        lay.addWidget(ok_btn)

        # Keyboard button
        osk_btn = QPushButton("KB")
        osk_btn.setFixedSize(44, 44)
        osk_btn.setCursor(Qt.PointingHandCursor)
        osk_btn.setStyleSheet(f"""
            QPushButton {{
                background: {OFF_WHITE}; color: {NAVY}; border: 1px solid {BORDER};
                border-radius: 8px; font-size: 20px;
            }}
            QPushButton:hover {{ background: {WHITE}; border-color: {ACCENT}; }}
        """)
        def _open_item_osk():
            try:
                import os
                os.startfile('osk.exe')
            except Exception:
                pass
        osk_btn.clicked.connect(_open_item_osk)
        lay.addWidget(osk_btn)

        clr_btn = QPushButton("Clear")
        clr_btn.setFixedSize(140, 44)
        clr_btn.setCursor(Qt.PointingHandCursor)
        clr_btn.setStyleSheet(f"""
            QPushButton {{
                background: {DANGER}; color: {WHITE}; border: none;
                border-radius: 8px; font-size: 18px; font-weight: bold;
            }}
            QPushButton:hover {{ background: {DANGER_H}; }}
        """)
        def _clear_and_accept():
            edit.clear()
            dlg.accept()
        clr_btn.clicked.connect(_clear_and_accept)
        lay.addWidget(clr_btn)

        v.addLayout(lay)

        edit.returnPressed.connect(dlg.accept)
        edit.setFocus()
        edit.selectAll()

        if dlg.exec() == QDialog.Accepted:
            new_note = edit.text().strip()
            self._block_signals = True
            if notes_item is None:
                notes_item = QTableWidgetItem("")
                self.invoice_table.setItem(row, self.COL_NOTES, notes_item)
            notes_item.setText("*" if not new_note else f"*  {new_note}")
            notes_item.setForeground(QColor("#888888"))
            notes_item.setToolTip(new_note)
            self._block_signals = False

    # =========================================================================
    # INLINE CUSTOMER SEARCH STRIP (pharmacy phase - GLOBAL, not pharmacy-only)
    # =========================================================================
    def _build_customer_search_strip(self) -> QWidget:
        """Inline customer search row above the cart - attach/replace active customer."""
        wrap = QWidget()
        wrap.setFixedHeight(46)
        wrap.setStyleSheet(f"background: {OFF_WHITE}; border-bottom: 1px solid {BORDER};")
        lay = QHBoxLayout(wrap)
        lay.setContentsMargins(8, 6, 8, 6)
        lay.setSpacing(6)

        # Leading icon
        icon_lbl = QLabel()
        try:
            icon_lbl.setPixmap(qta.icon("fa5s.user", color=NAVY).pixmap(14, 14))
        except Exception:
            icon_lbl.setText("[User]")
        icon_lbl.setStyleSheet("background: transparent;")
        lay.addWidget(icon_lbl)

        # Search input
        self._cust_search_edit = QLineEdit()
        self._cust_search_edit.setPlaceholderText("Search customer by name or phone...")
        self._cust_search_edit.setClearButtonEnabled(True)
        try:
            self._cust_search_edit.addAction(
                qta.icon("fa5s.search", color=MUTED),
                QLineEdit.LeadingPosition,
            )
        except Exception:
            pass
        self._cust_search_edit.setStyleSheet(f"""
            QLineEdit {{
                background: {WHITE}; color: {DARK_TEXT};
                border: 1px solid {BORDER}; border-radius: 4px;
                padding: 4px 8px; font-size: 12px;
            }}
            QLineEdit:focus {{ border: 1.5px solid {ACCENT}; }}
        """)
        self._cust_search_edit.textEdited.connect(self._on_cust_search_edited)
        self._cust_search_edit.returnPressed.connect(self._on_cust_search_enter)
        lay.addWidget(self._cust_search_edit, 1)

        # Completer (dropdown suggestions) - updated on textEdited
        self._cust_completer = QCompleter([], self._cust_search_edit)
        self._cust_completer.setCaseSensitivity(Qt.CaseInsensitive)
        self._cust_completer.setFilterMode(Qt.MatchContains)
        self._cust_completer.activated.connect(self._on_cust_completer_activated)
        self._cust_search_edit.setCompleter(self._cust_completer)
        self._cust_completer_cache: dict[str, dict] = {}

        # "+" Add-new button
        add_btn = QPushButton()
        try:
            add_btn.setIcon(qta.icon("fa5s.plus", color="white"))
        except Exception:
            add_btn.setText("+")
        add_btn.setFixedSize(32, 30)
        add_btn.setCursor(Qt.PointingHandCursor)
        add_btn.setToolTip("Add new customer")
        add_btn.setStyleSheet(f"""
            QPushButton {{
                background: {ACCENT}; color: {WHITE}; border: none;
                border-radius: 4px;
            }}
            QPushButton:hover {{ background: {ACCENT_H}; }}
        """)
        add_btn.clicked.connect(self._inline_add_new_customer)
        lay.addWidget(add_btn)

        # Selected customer label
        self._cust_inline_label = QLabel("No customer")
        self._cust_inline_label.setStyleSheet(
            f"color: {MUTED}; font-size: 11px; background: transparent; padding: 0 6px;"
        )
        self._cust_inline_label.setMinimumWidth(160)
        self._cust_inline_label.setMaximumWidth(260)
        # lay.addWidget(self._cust_inline_label)

        return wrap

    def _on_cust_search_edited(self, text: str):
        """Update completer suggestions as user types (name or phone) with 80ms debounce."""
        if not hasattr(self, "_cust_search_timer") or self._cust_search_timer is None:
            from PySide6.QtCore import QTimer
            self._cust_search_timer = QTimer(self)
            self._cust_search_timer.setSingleShot(True)
            self._cust_search_timer.timeout.connect(lambda: self._do_cust_search_edited(getattr(self, "_cust_last_query", "")))
        
        self._cust_last_query = text
        self._cust_search_timer.start(300)

    def _do_cust_search_edited(self, text: str):
        query = (text or "").strip()
        if len(query) < 2:
            return
        try:
            from models.customer import search_customers
            results = search_customers(query) or []
        except Exception as e:
            print(f"[CustSearch] search error: {e}")
            results = []
        labels = []
        cache: dict[str, dict] = {}
        for c in results[:25]:
            nm = c.get("customer_name", "") or ""
            ph = c.get("custom_telephone_number", "") or ""
            label = f"{nm}  -  {ph}" if ph else nm
            labels.append(label)
            cache[label] = c
        self._cust_completer_cache = cache
        from PySide6.QtCore import QStringListModel
        self._cust_completer.setModel(QStringListModel(labels))

    def _on_cust_completer_activated(self, label: str):
        """Pick a suggested customer - attach as active customer."""
        cust = self._cust_completer_cache.get(label)
        if not cust:
            return
        self._attach_inline_customer(cust)

    def _on_cust_search_enter(self):
        """Enter with no selection - pick the top match if available."""
        text = (self._cust_search_edit.text() or "").strip()
        if not text:
            return
        # Prefer an exact match in cache, else the first entry
        exact = next((v for k, v in self._cust_completer_cache.items() if k.lower() == text.lower()), None)
        if exact:
            self._attach_inline_customer(exact)
            return
        if self._cust_completer_cache:
            first = next(iter(self._cust_completer_cache.values()))
            self._attach_inline_customer(first)

    def _attach_inline_customer(self, cust: dict):
        """
        Called when the cashier picks a customer via the inline search
        completer. Delegates to `_apply_selected_customer` so the
        nav-bar button, inline label, cart-clear prompt, status bar, AND
        the product-grid re-price all happen in one place. Keeping this
        alias so legacy callers (QuickAddCustomerDialog signal etc.)
        don't have to change.
        """
        self._apply_selected_customer(cust)

    def _inline_add_new_customer(self):
        """Open the existing QuickAddCustomerDialog and auto-attach on success."""
        try:
            from views.dialogs.customer_dialog import QuickAddCustomerDialog
        except Exception as e:
            QMessageBox.warning(self, "Error",
                                f"Customer dialog not available:\n{e}")
            return
        dlg = QuickAddCustomerDialog(self)
        try:
            dlg.customer_created.connect(self._attach_inline_customer)
        except Exception:
            pass
        dlg.exec()

    # ── Invoice table ─────────────────────────────────────────────────────────
    # Column indices - change here only, every lookup uses these constants.
    # UOM sits next to Qty, between Qty and Disc.
    COL_LN       = 0
    COL_PART_NO  = 1
    COL_NAME     = 2
    COL_PRICE    = 3
    COL_QTY      = 4
    COL_UOM      = 5
    COL_DISC     = 6
    COL_TAX      = 7
    COL_TOTAL    = 8
    COL_NOTES    = 9
    INVOICE_COL_COUNT = 10

    # ── Invoice column labels - edit here to rename ──────────────────────────
    def _get_currency_symbol(self) -> str:
        """Returns active currency symbol directly from company_defaults without hardcoded mapping."""
        try:
            from models.company_defaults import get_defaults
            defs = get_defaults() or {}
            return str(defs.get("server_company_currency_symbol") or defs.get("server_company_currency") or defs.get("currency") or "").strip()
        except Exception:
            return ""

    def _build_invoice_table(self):
        self.invoice_table = QTableWidget()
        self.invoice_table.setColumnCount(self.INVOICE_COL_COUNT)
        sym = self._get_currency_symbol()
        headers = ["LN", "Item No.", "Item Details", f"Amount ({sym})", "Qty", "UOM", "Disc", "TAX", f"Total ({sym})", "Notes (Edit)"]
        self.invoice_table.setHorizontalHeaderLabels(headers)
        hh = self.invoice_table.horizontalHeader()
        hh.setSectionResizeMode(self.COL_LN,      QHeaderView.Fixed);  self.invoice_table.setColumnWidth(self.COL_LN, 35)
        hh.setSectionResizeMode(self.COL_PART_NO, QHeaderView.Fixed);  self.invoice_table.setColumnWidth(self.COL_PART_NO, 95)
        hh.setSectionResizeMode(self.COL_NAME,    QHeaderView.Stretch)
        hh.setSectionResizeMode(self.COL_PRICE,   QHeaderView.Fixed);  self.invoice_table.setColumnWidth(self.COL_PRICE, 90)
        hh.setSectionResizeMode(self.COL_QTY,     QHeaderView.Fixed);  self.invoice_table.setColumnWidth(self.COL_QTY, 90)
        hh.setSectionResizeMode(self.COL_UOM,     QHeaderView.Fixed);  self.invoice_table.setColumnWidth(self.COL_UOM, 60)
        hh.setSectionResizeMode(self.COL_DISC,    QHeaderView.Fixed);  self.invoice_table.setColumnWidth(self.COL_DISC, 65)
        hh.setSectionResizeMode(self.COL_TAX,     QHeaderView.Fixed);  self.invoice_table.setColumnWidth(self.COL_TAX, 45)
        hh.setSectionResizeMode(self.COL_TOTAL,   QHeaderView.Fixed);  self.invoice_table.setColumnWidth(self.COL_TOTAL, 90)
        hh.setSectionResizeMode(self.COL_NOTES,   QHeaderView.Stretch)
        # Global note trigger on header click
        hh.sectionClicked.connect(self._on_header_clicked)
        # Notes column only visible in restaurant/KOT mode
        self.invoice_table.setColumnHidden(self.COL_NOTES, True)

        self.invoice_table.verticalHeader().setVisible(False)
        self.invoice_table.setAlternatingRowColors(False)
        self.invoice_table.setShowGrid(True)
        self.invoice_table.setRowCount(20)
        self.invoice_table.verticalHeader().setDefaultSectionSize(20)
        self.invoice_table.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOn)
        self.invoice_table.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        # ── No native cell editor - all input goes through numpad / inline search
        self.invoice_table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        self.invoice_table.setStyleSheet(f"""
            QTableWidget {{
                background-color: {WHITE}; color: {NAVY};
                border: 1px solid {BORDER}; gridline-color: {LIGHT};
                font-size: 12px; outline: none;
                selection-background-color: transparent;
            }}
            QTableWidget::item {{
                padding: 0 4px; color: {NAVY}; border-bottom: 1px solid {LIGHT};
            }}
            QTableWidget::item:selected {{
                background-color: #fff8e1; color: {NAVY}; border: 1px solid #f9a825;
            }}
            QTableWidget::item:focus {{
                background-color: #fff8e1; color: {NAVY};
                border: 2px solid #f57f17; font-weight: bold;
            }}
            QHeaderView::section {{
                background-color: #f0e8d0; color: {NAVY};
                padding: 4px 6px; border: none; border-right: 1px solid {BORDER};
                font-size: 10px; font-weight: bold; letter-spacing: 0.3px;
            }}
        """)
        for r in range(self.invoice_table.rowCount()):
            self.invoice_table.setRowHeight(r, 20)
            self._init_row(r)

        self.invoice_table.cellClicked.connect(self._on_cell_clicked)
        self.invoice_table.cellDoubleClicked.connect(self._on_cell_double_clicked)
        self.invoice_table.itemChanged.connect(self._on_item_changed)
        self.invoice_table.installEventFilter(self)
        return self.invoice_table

    def _on_header_clicked(self, index):
        """Handle clicks on invoice table header."""
        if index == self.COL_NOTES:
            # Global order note
            self._on_bill_notes()

    def _init_row(self, r, part_no="", details="", qty="",
                  amount="", uom="", disc="", tax="", total="", notes=""):
        # Strip newlines from details to prevent rendering glitches (like Windows line ending boxes)
        if isinstance(details, str):
            details = details.replace('\r\n', ' ').replace('\n', ' ').replace('\r', ' ').strip()
            
        # vals order must match COL_* constants
        # Insert a blank for LN (index 0) so the enumerate indices align perfectly with COL_* constants!
        vals = ["", part_no, details, amount, qty, uom, disc, tax, total, notes]
        for c, val in enumerate(vals):
            item = QTableWidgetItem(str(val))
            item.setTextAlignment(Qt.AlignLeft | Qt.AlignVCenter if c == self.COL_NAME else Qt.AlignCenter)
            if c in (self.COL_PRICE, self.COL_TOTAL, self.COL_NOTES):
                item.setFlags(item.flags() & ~Qt.ItemIsEditable)
                if c == self.COL_TOTAL:
                    item.setForeground(QColor(ACCENT))
                elif c == self.COL_PRICE:
                    item.setForeground(QColor(NAVY))
                else:
                    # Notes: only show edit icon when this row has a product
                    note_val  = str(val).strip()
                    name_val  = str(vals[self.COL_NAME]).strip() if self.COL_NAME < len(vals) else ""
                    if name_val:
                        item.setText("*" if not note_val else f"*  {note_val}")
                        item.setForeground(QColor("#888888"))
                        item.setToolTip(note_val)
                    else:
                        item.setText("")
                        item.setToolTip("")
            else:
                item.setForeground(QColor(NAVY))
            self.invoice_table.setItem(r, c, item)
        self.invoice_table.setRowHeight(r, 20)

    def _find_next_empty_row(self) -> int:
        current = self.invoice_table.rowCount()
        last_filled = -1
        for r in range(current):
            name = self.invoice_table.item(r, 1)
            if name and name.text().strip():
                last_filled = r
        next_row = last_filled + 1
        if next_row >= current:
            self._ensure_rows(next_row + 1)
        return min(next_row, self.MAX_ROWS - 1)

    def _highlight_active_row(self, row: int):
        ACTIVE_BG  = QColor("#e3f2fd")
        ACTIVE_FG  = QColor(DARK_TEXT)
        FILLED_BG  = QColor(WHITE)
        FILLED_FG  = QColor(NAVY)
        ALT_BG     = QColor("#f5f8fc")

        for r in range(self.invoice_table.rowCount()):
            is_active = (r == row)
            for c in range(self.INVOICE_COL_COUNT):
                item = self.invoice_table.item(r, c)
                if not item:
                    continue
                if is_active:
                    item.setBackground(ACTIVE_BG)
                    item.setForeground(ACTIVE_FG if c != self.COL_TOTAL else QColor(ACCENT))
                else:
                    bg = FILLED_BG if r % 2 == 0 else ALT_BG
                    item.setBackground(bg)
                    item.setForeground(FILLED_FG if c != self.COL_TOTAL else QColor(ACCENT))

        # (notes popup is opened on tap - no bar to sync)

    def _open_qty_keypad(self):
        if not hasattr(self, 'invoice_table'): return
        r = self.invoice_table.currentRow()
        part_no_item = self.invoice_table.item(r, self.COL_PART_NO) if r >= 0 else None
        
        if r < 0 or not part_no_item or not part_no_item.text().strip():
            r = -1
            for i in range(self.invoice_table.rowCount() - 1, -1, -1):
                it = self.invoice_table.item(i, self.COL_PART_NO)
                if it and it.text().strip():
                    r = i
                    break
                    
        if r < 0:
            return
            
        try:
            qty_item = self.invoice_table.item(r, self.COL_QTY)
            if not qty_item: return
            try:
                current_qty = float(qty_item.text())
            except ValueError:
                current_qty = 1.0
                
            from PySide6.QtWidgets import QDialog, QVBoxLayout, QHBoxLayout, QLabel, QDoubleSpinBox, QPushButton
            from PySide6.QtCore import Qt
            
            dlg = QDialog(self)
            dlg.setWindowTitle("Update Quantity")
            dlg.setModal(True)
            dlg.setFixedSize(400, 450)
            dlg.setWindowFlags(Qt.Dialog | Qt.FramelessWindowHint)
            dlg.setStyleSheet(f"QDialog {{ background: {WHITE}; border: 2px solid {ACCENT}; border-radius: 8px; }}")
            
            lay = QVBoxLayout(dlg)
            lay.setContentsMargins(20, 20, 20, 20)
            lay.setSpacing(15)
            
            item_name = self.invoice_table.item(r, self.COL_NAME)
            lbl = QLabel(f"New quantity for: {item_name.text().strip() if item_name else ''}")
            lbl.setStyleSheet(f"color: {NAVY}; font-size: 14px; font-weight: bold;")
            lay.addWidget(lbl)
            
            spin = QDoubleSpinBox()
            spin.setRange(0.01, 10000.0)
            spin.setDecimals(2)
            spin.setValue(current_qty)
            spin.setAlignment(Qt.AlignCenter)
            spin.setStyleSheet(f"QDoubleSpinBox {{ background: {WHITE}; color: {NAVY}; border: 1px solid {BORDER}; border-radius: 4px; padding: 8px; font-size: 18px; font-weight: bold; }}")
            spin.setButtonSymbols(QDoubleSpinBox.NoButtons)
            lay.addWidget(spin)
            
            from PySide6.QtWidgets import QGridLayout
            keypad_lay = QGridLayout()
            keypad_lay.setSpacing(5)
            keys = [
                ('7',0,0), ('8',0,1), ('9',0,2),
                ('4',1,0), ('5',1,1), ('6',1,2),
                ('1',2,0), ('2',2,1), ('3',2,2),
                ('.',3,0), ('0',3,1), ('<-',3,2)
            ]
            
            def on_key_pressed(k, le=spin.lineEdit()):
                if k == '.':
                    txt = le.text()
                    if '.' in txt: return
                    if not txt: le.insert("0.")
                    else: le.insert(".")
                elif k == '<-': le.backspace()
                else: le.insert(k)
                
            for k, r_idx, c_idx in keys:
                btn = QPushButton(k)
                btn.setFixedHeight(45)
                btn.setCursor(Qt.PointingHandCursor)
                btn.setStyleSheet(f"QPushButton {{ background: #f0f0f0; border: 1px solid #ccc; border-radius: 4px; font-size: 18px; font-weight: bold; color: {NAVY}; }} QPushButton:pressed {{ background: #d0d0d0; }}")
                btn.clicked.connect(lambda checked=False, val=k: on_key_pressed(val))
                keypad_lay.addWidget(btn, r_idx, c_idx)
                
            lay.addLayout(keypad_lay)
            
            btn_lay = QHBoxLayout()
            btn_lay.setSpacing(10)
            
            btn_cancel = QPushButton("Cancel")
            btn_cancel.setCursor(Qt.PointingHandCursor)
            btn_cancel.setStyleSheet(f"QPushButton {{ background: {MUTED}; color: {WHITE}; font-weight: bold; padding: 8px 16px; border-radius: 4px; border: none; font-size: 13px; }}")
            btn_cancel.clicked.connect(dlg.reject)
            
            btn_ok = QPushButton("Enter")
            btn_ok.setCursor(Qt.PointingHandCursor)
            btn_ok.setDefault(True)
            btn_ok.setStyleSheet(f"QPushButton {{ background: {SUCCESS}; color: {WHITE}; font-weight: bold; padding: 8px 16px; border-radius: 4px; border: none; font-size: 13px; }}")
            btn_ok.clicked.connect(dlg.accept)
            
            btn_lay.addWidget(btn_cancel)
            btn_lay.addWidget(btn_ok)
            lay.addLayout(btn_lay)
            
            def _setup_cursor():
                spin.setFocus()
                spin.clear()
            
            from PySide6.QtCore import QTimer
            QTimer.singleShot(0, _setup_cursor)
            
            if dlg.exec() == QDialog.Accepted:
                new_qty = spin.value()
                
                block_rule = not getattr(self, "_get_pos_rule", lambda k, default: default)("allow_negative_stock", default=True)
                part_no_item = self.invoice_table.item(r, self.COL_PART_NO)
                product_id = part_no_item.data(Qt.UserRole) if part_no_item else None
                part_no = part_no_item.text().strip() if part_no_item else ""
                name_item = self.invoice_table.item(r, self.COL_NAME)
                p_name = name_item.text().strip() if name_item else "Item"
                
                if block_rule and p_name and p_name != "Item":
                    try:
                        from services.stock_cache import get_cached_product_info
                        info = get_cached_product_info(product_id=product_id, part_no=part_no, name=p_name)
                        if not info:
                            wh_id = getattr(self, "_get_active_warehouse_id", lambda: None)()
                            if product_id:
                                from models.product import get_product_by_id
                                p = get_product_by_id(product_id, warehouse_id=wh_id)
                            else:
                                from database.db import get_connection, fetchone_dict
                                conn = get_connection(); cur = conn.cursor()
                                cur.execute("SELECT TOP 1 id, stock, COALESCE(track_stock, 1) AS track_stock, COALESCE(is_product_bundle, 0) AS is_product_bundle, category FROM products WHERE part_no = ? OR name = ?", (part_no, p_name))
                                p = fetchone_dict(cur)
                                conn.close()
                            if p:
                                info = {
                                    "stock": float(p.get("stock") if p.get("stock") is not None else 0),
                                    "track_stock": bool(p.get("track_stock", True)),
                                    "is_bundle": bool(p.get("is_product_bundle", False)),
                                    "category": p.get("category") or ""
                                }
                        if info:
                            item_stock = float(info.get("stock", 0))
                            p_track_stock = info.get("track_stock", True)
                            p_is_bundle = info.get("is_bundle", False)
                            if p_is_bundle:
                                try:
                                    from database.db import get_connection
                                    _conn = get_connection(); _c = _conn.cursor()
                                    _c.execute("SELECT id FROM product_bundles WHERE name=?", (info.get("name"),))
                                    _b = _c.fetchone()
                                    if _b:
                                        _c.execute("SELECT item_code, quantity FROM bundle_items WHERE bundle_id=?", (_b[0],))
                                        _items = _c.fetchall()
                                        _bundle_stock = 999999.0
                                        for _icode, _qty in _items:
                                            _c.execute("SELECT stock FROM products WHERE part_no=?", (_icode,))
                                            _prow = _c.fetchone()
                                            if _prow:
                                                _cstock = float(_prow[0] if _prow[0] is not None else 0)
                                                _req = float(_qty)
                                                if _req > 0:
                                                    _possible = _cstock / _req
                                                    if _possible < _bundle_stock: _bundle_stock = _possible
                                        item_stock = _bundle_stock if _items else item_stock
                                    _conn.close()
                                except Exception:
                                    pass
                            p_cat = info.get("category") or ""
                            
                            allow_zero = False
                            if not p_track_stock:
                                allow_zero = True
                            elif p_cat:
                                try:
                                    from views.main_window import load_negative_stock_categories
                                    if p_cat in load_negative_stock_categories():
                                        allow_zero = True
                                except: pass
                            
                            if not allow_zero and new_qty > item_stock:
                                getattr(self, "_warn_popup", lambda t, m, icon=None: print(m))(
                                    "Exceeding Stock Limit",
                                    f"<b>{p_name}</b> has only {item_stock:g} unit(s) available in stock.<br>"
                                    f"Cannot increase quantity to {new_qty:g}.",
                                    icon=None
                                )
                                return
                    except Exception as e:
                        print(f"[_open_qty_popup] Stock check error: {e}")
                
                qty_item.setText(f"{new_qty:g}")
                self._recalc_row(r)
                self._recalc_totals()
                
                # Check for sync to secondary screen
                try:
                    from services.kds_service import kds_service
                    if kds_service and getattr(self, '_active_tab_type', None) == "inv":
                        row_data = self._get_cart_data()
                        if row_data:
                            from database.db import get_connection
                            conn = get_connection(); cur = conn.cursor()
                            cur.execute("SELECT setting_value FROM pos_settings WHERE setting_key='enable_kds_websocket'")
                            s = cur.fetchone(); conn.close()
                            if s and s[0] == "1":
                                kds_service.broadcast_cart({"items": row_data, "total": self._get_total_usd()})
                except Exception as e:
                    print(f"Sync error after qty update: {e}")
        except Exception as e:
            print("Error opening qty input:", e)

    # ── Calculation engine ────────────────────────────────────────────────────
    def _recalc_row(self, r):
        if self._block_signals:
            return
        try:
            amount      = float(self.invoice_table.item(r, self.COL_PRICE).text() or "0")
            qty         = float(self.invoice_table.item(r, self.COL_QTY).text() or "0")
            disc_amount = float((self.invoice_table.item(r, self.COL_DISC).text() or "0").replace('%', '').strip())
            
            # ── CENTRAL STOCK ENFORCEMENT ──────────────────────────────────────────
            part_no_item = self.invoice_table.item(r, self.COL_PART_NO)
            product_id = part_no_item.data(Qt.UserRole) if part_no_item else None
            part_no = part_no_item.text().strip() if part_no_item else ""
            name_item = self.invoice_table.item(r, self.COL_NAME)
            product_name = name_item.text().strip() if name_item else "Item"
            
            if qty > 0 and product_name and product_name != "Item":
                try:
                    q_item = self.invoice_table.item(r, self.COL_QTY)
                    stk_data = q_item.data(Qt.UserRole + 2) if q_item else None
                    
                    from services.stock_cache import get_cached_product_info
                    info = get_cached_product_info(product_id=product_id, part_no=part_no, name=product_name)
                    
                    item_stock = None
                    p_track_stock = True
                    p_is_bundle = False
                    p_cat = ""
                    
                    if info:
                        item_stock = float(info.get("stock", 0))
                        p_track_stock = info.get("track_stock", True)
                        p_is_bundle = info.get("is_bundle", False)
                        if p_is_bundle:
                            try:
                                from database.db import get_connection
                                _conn = get_connection(); _c = _conn.cursor()
                                _c.execute("SELECT id FROM product_bundles WHERE name=?", (info.get("name"),))
                                _b = _c.fetchone()
                                if _b:
                                    _c.execute("SELECT item_code, quantity FROM bundle_items WHERE bundle_id=?", (_b[0],))
                                    _items = _c.fetchall()
                                    _bundle_stock = 999999.0
                                    for _icode, _qty in _items:
                                        _c.execute("SELECT stock FROM products WHERE part_no=?", (_icode,))
                                        _prow = _c.fetchone()
                                        if _prow:
                                            _cstock = float(_prow[0] if _prow[0] is not None else 0)
                                            _req = float(_qty)
                                            if _req > 0:
                                                _possible = _cstock / _req
                                                if _possible < _bundle_stock: _bundle_stock = _possible
                                    item_stock = _bundle_stock if _items else item_stock
                                _conn.close()
                            except Exception:
                                pass
                        p_cat = info.get("category") or ""
                    elif stk_data is not None:
                        item_stock = float(stk_data)
                    else:
                        wh_id = getattr(self, "_get_active_warehouse_id", lambda: None)()
                        p = None
                        if product_id:
                            from models.product import get_product_by_id
                            p = get_product_by_id(product_id, warehouse_id=wh_id)
                        if not p and (part_no or product_name):
                            from database.db import get_connection, fetchone_dict
                            conn = get_connection(); cur = conn.cursor()
                            cur.execute("SELECT TOP 1 id, stock, COALESCE(track_stock, 1) AS track_stock, COALESCE(is_product_bundle, 0) AS is_product_bundle, category FROM products WHERE part_no = ? OR name = ?", (part_no, product_name))
                            p = fetchone_dict(cur)
                            conn.close()
                        if p:
                            item_stock = float(p.get("stock") if p.get("stock") is not None else 0)
                            p_track_stock = bool(p.get("track_stock", True))
                            p_is_bundle = bool(p.get("is_product_bundle", False))
                            if p_is_bundle:
                                try:
                                    from database.db import get_connection
                                    _conn = get_connection(); _c = _conn.cursor()
                                    _c.execute("SELECT id FROM product_bundles WHERE name=?", (p.get("name"),))
                                    _b = _c.fetchone()
                                    if _b:
                                        _c.execute("SELECT item_code, quantity FROM bundle_items WHERE bundle_id=?", (_b[0],))
                                        _items = _c.fetchall()
                                        _bundle_stock = 999999.0
                                        for _icode, _qty in _items:
                                            _c.execute("SELECT stock FROM products WHERE part_no=?", (_icode,))
                                            _prow = _c.fetchone()
                                            if _prow:
                                                _cstock = float(_prow[0] if _prow[0] is not None else 0)
                                                _req = float(_qty)
                                                if _req > 0:
                                                    _possible = _cstock / _req
                                                    if _possible < _bundle_stock: _bundle_stock = _possible
                                        item_stock = _bundle_stock if _items else item_stock
                                    _conn.close()
                                except Exception:
                                    pass
                            p_cat = p.get("category") or ""
                        else:
                            # Product not found in DB or cache -> fallback stock = 0.0
                            item_stock = 0.0
                    
                    block_rule = not self._get_pos_rule("allow_negative_stock", default=True)
                    
                    allow_zero = False
                    if not p_track_stock or not block_rule:
                        allow_zero = True
                    elif p_cat:
                        try:
                            from views.main_window import load_negative_stock_categories
                            if p_cat in load_negative_stock_categories():
                                allow_zero = True
                        except Exception: pass
                    
                    if not allow_zero and item_stock is not None and qty > item_stock:
                        max_qty = max(item_stock, 0.0)
                        self._block_signals = True
                        if q_item:
                            q_item.setText(f"{max_qty:g}")
                        self._numpad_buffer = ""
                        self._block_signals = False
                        qty = max_qty
                        
                        from PySide6.QtCore import QTimer
                        QTimer.singleShot(0, lambda: self._warn_popup(
                            "Exceeding Stock Limit",
                            f"<b>{product_name}</b> has only {item_stock:g} unit(s) available in stock.<br>"
                            f"Quantity has been capped at {max_qty:g}.",
                            icon=QMessageBox.Warning,
                        ))
                except Exception as e:
                    print(f"[_recalc_row] Stock check error: {e}")

            total       = max(qty * amount - disc_amount, 0.0)
        except (ValueError, AttributeError):
            total = 0.0
        self._block_signals = True
        item = self.invoice_table.item(r, self.COL_TOTAL)
        if item:
            # Only show a value when the row has an actual product entry
            details = self.invoice_table.item(r, self.COL_NAME)
            has_product = bool(details and details.text().strip())
            item.setText(f"{total:.2f}" if has_product else "")
            item.setForeground(QColor(ACCENT))
        self._block_signals = False
        self._recalc_totals()

    def _recalc_totals(self):
        subtotal  = 0.0
        qty_total = 0.0
        line_num = 1
        for r in range(self.invoice_table.rowCount()):
            try:
                part_no_item = self.invoice_table.item(r, self.COL_PART_NO)
                if part_no_item and part_no_item.text().strip():
                    ln_item = self.invoice_table.item(r, self.COL_LN)
                    if ln_item: ln_item.setText(str(line_num))
                    line_num += 1
                else:
                    ln_item = self.invoice_table.item(r, self.COL_LN)
                    if ln_item: ln_item.setText("")
            except Exception: pass
            try:
                subtotal  += float(self.invoice_table.item(r, self.COL_TOTAL).text() or "0")
                qty_total += float(self.invoice_table.item(r, self.COL_QTY).text() or "0")
            except (ValueError, AttributeError):
                pass

        # COL_TOTAL is already (price × qty - disc_amount) so the subtotal here
        # is post-discount.  Do NOT apply current_discount_percent again - that
        # would double-count.  Use the pre-computed discount_amount directly.
        discount_amount = getattr(self, "current_discount_amount", 0.0)
        discount_pct    = getattr(self, "current_discount_percent", 0.0)
        grand_total     = subtotal  # already discounted

        self._lbl_total.setText(f"{grand_total:.2f}" if grand_total else "")
        self._bin_qty.setText(f"Items: {int(qty_total)}")

        # Show discount badge on the label when active
        if discount_amount > 0:
            self._lbl_total.setToolTip(
                f"Discount {discount_pct:.2f}%: -${discount_amount:.2f}  |  Total: ${grand_total:.2f}"
            )
        else:
            self._lbl_total.setToolTip("")

        # Update row count bar
        if hasattr(self, "_lbl_row_count"):
            filled = sum(
                1 for r in range(self.invoice_table.rowCount())
                if self.invoice_table.item(r, 1) and self.invoice_table.item(r, 1).text().strip()
            )
            self._lbl_row_count.setText(f"Rows: {filled}")

        # Update status bar
        if self.parent_window:
            status = f"  Items: {int(qty_total)}   |   Total: ${grand_total:.2f}"
            if discount_amount > 0:
                status += f"   |   Discount: {discount_pct:.2f}% (-${discount_amount:.2f})"
            self.parent_window._set_status(status)

    def _on_item_changed(self, item):
        if self._block_signals:
            return
        if item.column() in (2, 3, 4):
            self._recalc_row(item.row())

    # =========================================================================
    # INLINE CELL SEARCH
    # =========================================================================
    def _open_inline_search(self, row, col):
        # Pharmacy lock: cashiers cannot replace/edit the product on a pharmacy row
        if self._is_pharmacy_row_locked(row):
            self._notify_pharmacy_locked(row)
            return

        self._close_inline_search()

        self._inline_row = row
        self._inline_col = col

        existing = self.invoice_table.item(row, 0)
        seed = existing.text().strip() if existing else ""

        # ── What text is already in this row? show it as placeholder ─────────
        details_item = self.invoice_table.item(row, 1)
        existing_details = details_item.text().strip() if details_item else ""

        edit = QLineEdit()
        edit.setText(seed)
        edit.selectAll()
        # If there is already a product on this row, show its name as a ghost
        # so the cashier can see what they are editing / replacing.
        if existing_details:
            edit.setPlaceholderText(existing_details)
        edit.setStyleSheet(f"""
            QLineEdit {{
                background: rgba(255,255,255,160); color: {DARK_TEXT};
                border: 2px solid {ACCENT}; border-radius: 0px;
                font-size: 13px; font-weight: bold; padding: 0 6px;
            }}
        """)
        edit.setParent(self.invoice_table.viewport())

        vp_w     = self.invoice_table.viewport().width()
        row_rect = self.invoice_table.visualRect(
                       self.invoice_table.model().index(row, 0))
        edit.setFixedHeight(row_rect.height())
        edit.setGeometry(0, row_rect.y(), vp_w, row_rect.height())
        edit.show()
        edit.setFocus()
        self._inline_edit = edit

        popup = QListWidget(self.invoice_table.viewport())
        popup.setStyleSheet(f"""
            QListWidget {{
                background: {WHITE}; border: 2px solid {ACCENT};
                border-radius: 0px; font-size: 13px; color: {DARK_TEXT}; outline: none;
            }}
            QListWidget::item           {{ padding: 6px 10px; min-height: 28px; color: {DARK_TEXT}; }}
            QListWidget::item:selected  {{ background-color: {ACCENT}; color: {WHITE}; }}
            QListWidget::item:selected:!active {{ background-color: {ACCENT}; color: {WHITE}; }}
            QListWidget::item:hover     {{ background-color: {LIGHT}; color: {NAVY}; }}
        """)
        popup.setFocusPolicy(Qt.NoFocus)
        popup.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        popup.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        popup.setMaximumHeight(16777215)
        popup.hide()
        self._inline_popup = popup

        edit.textChanged.connect(self._inline_on_text_changed)
        edit.returnPressed.connect(self._inline_on_enter)
        edit.installEventFilter(self)
        popup.itemClicked.connect(self._inline_on_item_clicked)

        if seed:
            self._inline_refresh_popup(seed)

    def _inline_refresh_popup(self, query: str):
        popup = self._inline_popup
        if popup is None:
            return
        popup.clear()
        q_clean = query.strip()
        if len(q_clean) < 3:
            popup.hide()
            return
            
        # Show Searching... loader in popup list
        it = QListWidgetItem(f"Searching for '{q_clean}'...")
        it.setFlags(Qt.NoItemFlags)
        popup.addItem(it)
        
        # Calculate and set temporary popup geometry
        if self._inline_edit:
            geo    = self._inline_edit.geometry()
            vp_h   = self.invoice_table.viewport().height()
            vp_w   = self.invoice_table.viewport().width()
            item_h = 40
            popup_top    = geo.y() + geo.height()
            space_below  = vp_h - popup_top
            actual_h = min(item_h + 4, space_below) if space_below >= item_h else max(item_h + 4, space_below)
            popup.setGeometry(0, popup_top, vp_w, actual_h)
            popup.show()
            popup.raise_()
        
        from PySide6.QtWidgets import QApplication
        QApplication.processEvents()
        
        popup.clear()

        try:
            from models.product import search_products
            wh_id = getattr(self, "_get_active_warehouse_id", lambda: None)()
            active_pl = getattr(self, "_get_active_price_list", lambda: None)()
            products = search_products(query, warehouse_id=wh_id, price_list_name=active_pl)
        except Exception:
            demo = [
                {"id": 1, "part_no": "S",     "name": "SERVICE CHARGE",   "price": 50.00},
                {"id": 2, "part_no": "1",     "name": "Swiss Army Knife", "price": 10.00},
                {"id": 3, "part_no": "GR001", "name": "Cooking Oil",      "price": 3.50},
                {"id": 4, "part_no": "DK001", "name": "Coke 500ml",       "price": 1.20},
            ]
            ql = query.lower()
            products = [p for p in demo if ql in p["part_no"].lower() or ql in p["name"].lower()]

        if not products:
            popup.hide(); return

        for p in products[:12]:
            label = f"{p['part_no']}   {p['name']}   ${p['price']:.2f}"
            it    = QListWidgetItem(label)
            it.setData(Qt.UserRole, p)
            popup.addItem(it)

        popup.setCurrentRow(0)

        if not self._inline_edit:
            return

        geo    = self._inline_edit.geometry()
        vp_h   = self.invoice_table.viewport().height()
        vp_w   = self.invoice_table.viewport().width()
        item_h = 40
        popup_h = min(item_h * popup.count() + 4, 260)

        # ── ALWAYS place popup BELOW the current row ──────────────────────────
        # This ensures it never covers already-filled rows above.
        popup_top    = geo.y() + geo.height()
        space_below  = vp_h - popup_top
        if space_below >= item_h:
            # Enough room below - show as many items as fit
            actual_h = min(popup_h, space_below)
            popup.setGeometry(0, popup_top, vp_w, actual_h)
        else:
            # Not much room below - still go below but clip to whatever is left
            # (minimum 1 item visible).  Never go above the current row.
            actual_h = max(item_h + 4, space_below)
            popup.setGeometry(0, popup_top, vp_w, actual_h)

        popup.show()
        popup.raise_()

    def _inline_on_text_changed(self, text):
        if not hasattr(self, "_inline_search_timer") or self._inline_search_timer is None:
            from PySide6.QtCore import QTimer
            self._inline_search_timer = QTimer(self)
            self._inline_search_timer.setSingleShot(True)
            self._inline_search_timer.timeout.connect(lambda: self._inline_refresh_popup(getattr(self, "_inline_last_query", "")))
        
        self._inline_last_query = text
        self._inline_search_timer.start(300)

    def _inline_on_enter(self):
        popup = self._inline_popup
        if popup and popup.isVisible() and popup.currentItem():
            self._inline_on_item_clicked(popup.currentItem())
        else:
            query = self._inline_edit.text().strip() if self._inline_edit else ""
            self._inline_commit_query(query)

    def _inline_on_item_clicked(self, list_item):
        product = list_item.data(Qt.UserRole)
        self._inline_commit_product(product)

    def _inline_commit_query(self, query):
        row = self._inline_row
        self._close_inline_search()
        if not query or row < 0:
            return
        product = None
        scale_qty = None  # Set when weight-based barcode decoding succeeds
        barcode_uom = None  # Set when alternative barcode lookup succeeds

        # ── Alternative barcode lookup (fetches specific UOM) ────────────────
        try:
            from database.db import get_connection
            conn = get_connection()
            cur = conn.cursor()
            cur.execute("SELECT part_no, uom FROM product_barcodes WHERE barcode = ?", (query.strip(),))
            row_data = cur.fetchone()
            conn.close()
            if row_data:
                alt_part_no, alt_uom = row_data
                from models.product import get_product_by_part_no
                wh_id = self._get_active_warehouse_id()
                product = get_product_by_part_no(alt_part_no, warehouse_id=wh_id)
                if product:
                    barcode_uom = alt_uom
        except Exception as e:
            print(f"[Barcode Lookup] error checking product_barcodes: {e}")

        if not product:
            try:
                from models.product import search_products
                wh_id = self._get_active_warehouse_id()
                results = search_products(query, warehouse_id=wh_id)
                if results: product = results[0]
            except Exception:
                demo = [
                    {"id": 1, "part_no": "S",     "name": "SERVICE CHARGE",   "price": 50.00},
                    {"id": 2, "part_no": "1",     "name": "Swiss Army Knife", "price": 10.00},
                    {"id": 3, "part_no": "GR001", "name": "Cooking Oil",      "price": 3.50},
                    {"id": 4, "part_no": "DK001", "name": "Coke 500ml",       "price": 1.20},
                ]
                ql = query.lower()
                matches = [p for p in demo if ql in p["part_no"].lower() or ql in p["name"].lower()]
                if matches: product = matches[0]

        # ── Weight-based scale barcode fallback ──────────────────────────────
        if product is None:
            prefix, parsed_qty = decode_weight_barcode(query)
            if prefix is not None:
                try:
                    from models.product import get_product_by_part_no
                    wh_id = self._get_active_warehouse_id()
                    _sp = get_product_by_part_no(prefix, warehouse_id=wh_id)
                    if _sp:
                        product = _sp
                        scale_qty = parsed_qty
                except Exception as _se:
                    print(f"[Scale Barcode] fallback error: {_se}")

        if product:
            picked = self._pick_product_uom_and_price(product, barcode_uom=barcode_uom)
            if picked is None:
                return   # cancelled / blocked
            product, uom, price = picked

            # ── Weight-based scale: accumulate on existing row ────────────
            if scale_qty is not None:
                existing_row = -1
                for r in range(self.invoice_table.rowCount()):
                    try:
                        row_pid = self.invoice_table.item(r, self.COL_PART_NO).data(Qt.UserRole) if self.invoice_table.item(r, self.COL_PART_NO) else None
                        row_name = self.invoice_table.item(r, self.COL_NAME).text().strip() if self.invoice_table.item(r, self.COL_NAME) else ""
                        if not row_name:
                            continue
                        if (row_pid and row_pid == product.get("id")) or \
                           (not row_pid and row_name == product["name"]):
                            existing_row = r
                            break
                    except Exception:
                        continue

                if existing_row >= 0:
                    # Accumulate weight on existing row
                    qty_col = getattr(self, "COL_QTY", 3)
                    qty_item = self.invoice_table.item(existing_row, qty_col)
                    if qty_item:
                        try:
                            old_qty = float(qty_item.text() or "0")
                        except ValueError:
                            old_qty = 0.0
                        new_qty = old_qty + scale_qty
                        self._block_signals = True
                        qty_item.setText(f"{new_qty:.3f}")
                        qty_item.setFlags(qty_item.flags() & ~Qt.ItemIsEditable)
                        qty_item.setForeground(QColor(ACCENT))
                        qty_item.setToolTip(f"Qty set by scale ({old_qty:.3f} + {scale_qty:.3f})")
                        self._block_signals = False
                        self._recalc_row(existing_row)
                        try:
                            self._recalc_totals()
                        except Exception:
                            pass
                    return  # Done - accumulated on existing row

            self._add_product_to_invoice(
                name=product["name"],
                price=price,
                part_no=product.get("part_no", ""),
                product_id=product.get("id"),
                uom=uom,
            )
            # ── Override qty for weight-based scale (and lock it) ────────────
            if scale_qty is not None:
                try:
                    last = getattr(self, "_last_filled_row", -1)
                    if last >= 0:
                        qty_col = getattr(self, "COL_QTY", 3)
                        qty_item = self.invoice_table.item(last, qty_col)
                        if qty_item:
                            self._block_signals = True
                            qty_item.setText(f"{scale_qty:.3f}")
                            # Lock - remove edit flag so cashier cannot override scale weight
                            qty_item.setFlags(qty_item.flags() & ~Qt.ItemIsEditable)
                            qty_item.setForeground(QColor(ACCENT))
                            qty_item.setToolTip("Qty set by scale \u2014 cannot be changed manually")
                            self._block_signals = False
                        self._recalc_row(last)
                        try:
                            self._recalc_totals()
                        except Exception:
                            pass
                except Exception as _qe:
                    print(f"[Scale Barcode] qty override error: {_qe}")
        else:
            # #31 - show popup then reopen search on the same row
            msg = QMessageBox(self)
            msg.setWindowTitle("Item Not Found")
            msg.setIcon(QMessageBox.Warning)
            msg.setText(f"No item matched:  \"{query}\"")
            msg.setInformativeText(
                "Check the code or description and try again.\n"
                "Double-click the row to open the full product search."
            )
            msg.setStandardButtons(QMessageBox.Ok)
            msg.setStyleSheet(f"""
                QMessageBox {{ background:{WHITE}; }}
                QLabel       {{ color:{DARK_TEXT}; font-size:13px; }}
                QPushButton  {{
                    background:{ACCENT}; color:{WHITE}; border:none;
                    border-radius:5px; padding:8px 22px; font-size:13px; min-width:80px;
                }}
                QPushButton:hover {{ background:{ACCENT_H}; }}
            """)
            msg.exec()
            # After OK - move to the next empty row so user can continue scanning
            next_row = self._find_next_empty_row()
            self._ensure_rows(next_row + 1)
            self._highlight_active_row(next_row)
            self.invoice_table.setCurrentCell(next_row, 0)
            self._active_row = next_row
            self._active_col = 0
            self._open_inline_search(next_row, 0)

    def _inline_commit_product(self, product):
        try:
            self._close_inline_search()
            if not product:
                return
            picked = self._pick_product_uom_and_price(product)
            if picked is None:
                return   # cancelled / blocked
            product, uom, price = picked
            self._add_product_to_invoice(
                name=product["name"],
                price=price,
                part_no=product.get("part_no", ""),
                product_id=product.get("id"),
                stock=product.get("stock"),
                uom=uom,
            )
        except Exception as _e:
            import traceback; traceback.print_exc()
            try:
                QMessageBox.warning(self, "Error", f"Could not add product:\n{_e}")
            except Exception:
                pass

    def _fill_row_from_product(self, row, product):
        """Write a product into a specific row - only used when the product is
        NOT already on the invoice (called from _add_product_to_invoice new-row path)."""
        self._block_signals = True
        self._init_row(row, part_no=product["part_no"], details=product["name"],
                       qty="1", amount=f"{product['price']:.2f}",
                       uom=(product.get("uom") or ""),
                       disc="0.00", tax="")
        item0 = self.invoice_table.item(row, self.COL_PART_NO)
        if item0: item0.setData(Qt.UserRole, product.get("id"))
        self._block_signals = False
        self._recalc_row(row)
        self.invoice_table.setCurrentCell(row, self.COL_QTY)
        self._active_row      = row
        self._active_col      = self.COL_QTY
        self._last_filled_row = row
        self._numpad_buffer   = ""
        self._highlight_active_row(row)
        self.invoice_table.setFocus()
        if self.parent_window:
            self.parent_window._set_status(
                f"Added: {product['name']} @ ${product['price']:.2f}  - type qty or Enter"
            )

    def _close_inline_search(self):
        if self._inline_popup:
            self._inline_popup.hide()
            self._inline_popup.deleteLater()
            self._inline_popup = None
        if self._inline_edit:
            self._inline_edit.hide()
            self._inline_edit.deleteLater()
            self._inline_edit = None
        self._inline_row = -1
        self._inline_col = -1

    def eventFilter(self, obj, event):
        from PySide6.QtCore import QEvent
        if event.type() != QEvent.KeyPress:
            ret = super().eventFilter(obj, event)
            return bool(ret) if ret is not None else False
        if getattr(self, "_in_event_filter", False):
            ret = super().eventFilter(obj, event)
            return bool(ret) if ret is not None else False
        self._in_event_filter = True
        try:
            res = self._event_filter_body_1(obj, event)
            if res is True:
                return True
        except Exception:
            pass
        finally:
            self._in_event_filter = False
        ret = super().eventFilter(obj, event)
        return bool(ret) if ret is not None else False

    def _event_filter_body_1(self, obj, event):
        from PySide6.QtCore import QEvent

        # ── Global Up/Down -> cart navigation ─────────────────────────────────
        # When the cashier is on the POS screen but focus is on a button / the
        # product grid / anywhere that isn't a text input, Up/Down should move
        # through the cart rows. The per-widget branches below still own the
        # specific behaviours (inline-search popup, table's own edit triggers).
        if event.type() == QEvent.KeyPress and getattr(self, "_global_cart_nav_ready", False):
            _k = event.key()
            if _k in (Qt.Key_Up, Qt.Key_Down):
                from PySide6.QtWidgets import QLineEdit, QTextEdit, QSpinBox, QDoubleSpinBox, QComboBox
                fw = QApplication.focusWidget()
                # Skip if the invoice_table or inline search already handle Up/Down
                # (their own branches below fire with the correct context).
                if fw in (self.invoice_table, self.invoice_table.viewport()) or fw is getattr(self, "_inline_edit", None):
                    pass  # fall through to specific branches
                elif isinstance(fw, (QLineEdit, QTextEdit, QSpinBox, QDoubleSpinBox, QComboBox)):
                    pass  # let text inputs handle Up/Down themselves
                elif fw and fw.window() and getattr(fw.window(), "isModal", lambda: False)():
                    pass  # let modal dialogs handle Up/Down themselves
                elif fw and fw.window() and isinstance(fw.window(), QDialog):
                    pass  # let dialogs handle Up/Down themselves
                elif hasattr(self, "invoice_table") and self.invoice_table is not None:
                    delta = -1 if _k == Qt.Key_Up else 1
                    cur_r = getattr(self, "_active_row", 0)
                    cur_r = cur_r if cur_r >= 0 else 0
                    target = max(0, min(cur_r + delta, self.invoice_table.rowCount() - 1))
                    self._active_row = target
                    col = getattr(self, "_active_col", self.COL_PART_NO)
                    col = col if col >= 0 else self.COL_PART_NO
                    self.invoice_table.setCurrentCell(target, col)
                    self._highlight_active_row(target)
                    try:
                        self.invoice_table.scrollToItem(
                            self.invoice_table.item(target, col),
                            QAbstractItemView.EnsureVisible)
                    except Exception:
                        pass
                    self.invoice_table.setFocus()
                    return True

        # ── inline search edit ────────────────────────────────────────────────
        if obj is self._inline_edit and event.type() == QEvent.KeyPress:
            key   = event.key()
            popup = self._inline_popup
            if key == Qt.Key_Down:
                if popup and popup.isVisible():
                    popup.setCurrentRow(min(popup.currentRow() + 1, popup.count() - 1))
                return True
            if key == Qt.Key_Up:
                if popup and popup.isVisible():
                    popup.setCurrentRow(max(popup.currentRow() - 1, 0))
                return True
            if key == Qt.Key_Escape:
                self._close_inline_search()
                self.invoice_table.setFocus()
                return True
            if key == Qt.Key_Tab:
                self._inline_on_enter()
                return True

        # ── invoice table ─────────────────────────────────────────────────────
        if obj in (self.invoice_table, self.invoice_table.viewport()) and event.type() == QEvent.KeyPress:
            key  = event.key()
            mods = event.modifiers()

            # #6 Enter/Return - always advance to next cart line
            if key in (Qt.Key_Return, Qt.Key_Enter):
                if self._inline_edit is not None:
                    self._inline_on_enter()
                    return True
                self._numpad_enter()
                return True

            # #36 Up arrow - move to row above.
            # Inline search only re-opens when the destination row is empty -
            # navigating across filled rows shouldn't spawn a search popup.
            if key == Qt.Key_Up:
                self._close_inline_search()
                target = max(0, self._active_row - 1)
                self._active_row = target
                self.invoice_table.setCurrentCell(target, self._active_col)
                self._highlight_active_row(target)
                self.invoice_table.scrollToItem(
                    self.invoice_table.item(target, self._active_col),
                    QAbstractItemView.EnsureVisible)
                if self._active_col in (self.COL_PART_NO, self.COL_NAME):
                    _n = self.invoice_table.item(target, self.COL_NAME)
                    if not (_n and _n.text().strip()):
                        self._open_inline_search(target, self._active_col)
                return True

            # #36 Down arrow - move to row below. Same skip-on-filled rule.
            if key == Qt.Key_Down:
                self._close_inline_search()
                target = min(self._active_row + 1, self.invoice_table.rowCount() - 1)
                self._active_row = target
                self.invoice_table.setCurrentCell(target, self._active_col)
                self._highlight_active_row(target)
                self.invoice_table.scrollToItem(
                    self.invoice_table.item(target, self._active_col),
                    QAbstractItemView.EnsureVisible)
                if self._active_col in (self.COL_PART_NO, self.COL_NAME):
                    _n = self.invoice_table.item(target, self.COL_NAME)
                    if not (_n and _n.text().strip()):
                        self._open_inline_search(target, self._active_col)
                return True

            # #36 Tab - cycle Code->Qty->Disc, wrap to next/prev row
            if key == Qt.Key_Tab:
                self._close_inline_search()
                _TAB = [self.COL_PART_NO, self.COL_QTY, self.COL_DISC]
                reverse = bool(mods & Qt.ShiftModifier)
                if reverse:
                    _TAB = list(reversed(_TAB))
                try:
                    nxt = _TAB.index(self._active_col) + 1
                except ValueError:
                    nxt = 0
                if nxt >= len(_TAB):
                    step = -1 if reverse else 1
                    self._active_row = max(0, min(
                        self._active_row + step,
                        self.invoice_table.rowCount() - 1))
                    self._active_col = _TAB[0]
                else:
                    self._active_col = _TAB[nxt]
                self.invoice_table.setCurrentCell(self._active_row, self._active_col)
                self._highlight_active_row(self._active_row)
                if self._active_col in (0, 1):
                    self._open_inline_search(self._active_row, self._active_col)
                return True

            if key == Qt.Key_Delete:    self._numpad_del_line(); return True
            if key == Qt.Key_Asterisk:  self._open_qty_popup();  return True
            if key == Qt.Key_F2:
                # Check if it's a pharmacy item
                _is_pharm_item = False
                if self._active_row >= 0:
                    _part_item = self.invoice_table.item(self._active_row, self.COL_PART_NO)
                    if _part_item:
                        _pm = _part_item.data(self.PHARMACY_META_ROLE)
                        if _pm and _pm.get("is_pharmacy"):
                            _is_pharm_item = True
                
                if _is_pharm_item:
                    self._edit_dosage(self._active_row)
                else:
                    self._save_sale()
                return True
            if key == Qt.Key_F3:        self._print_receipt();    return True
            if key == Qt.Key_F4:        self._on_discount_clicked(); return True
            # To this:
            if key == Qt.Key_F6: self._open_quotation_manager(); return True
            if key == Qt.Key_F5:        self._open_payment();     return True
            if key == Qt.Key_F9:        self._open_credit_note_dialog(); return True
            if key == Qt.Key_F7:        self._open_sales_list();  return True
            if key == Qt.Key_Q:         UnsyncedPopup("PAY", self).exec(); return True
            if key == Qt.Key_Escape:
                self._close_inline_search(); self._numpad_clear(); return True
            if key == Qt.Key_Backspace:
                if self._inline_edit is None and self._active_col in (self.COL_PRICE, self.COL_QTY, self.COL_DISC):
                    self._numpad_buffer = self._numpad_buffer[:-1]
                    self._block_signals = True
                    item = self.invoice_table.item(self._active_row, self._active_col)
                    if item: item.setText(self._numpad_buffer)
                    self._block_signals = False
                    self._recalc_row(self._active_row)
                    return True
            if self._inline_edit is None and self._active_col in (self.COL_PRICE, self.COL_QTY, self.COL_DISC):
                ch = None
                if Qt.Key_0 <= key <= Qt.Key_9:
                    ch = str(key - Qt.Key_0)
                elif Qt.Key_Keypad0 <= key <= Qt.Key_Keypad9:
                    ch = str(key - Qt.Key_Keypad0)
                elif key in (Qt.Key_Period, Qt.Key_KeypadDot):
                    ch = "."
                elif key in (Qt.Key_Minus, Qt.Key_Underscore):
                    ch = "-"
                if ch is not None:
                    self._numpad_press(ch); return True

            return False

    # =========================================================================
    # CELL CLICK / DOUBLE-CLICK
    # =========================================================================
    def _on_cell_clicked(self, row, col):
        self._active_row    = row
        self._active_col    = col
        self._numpad_buffer = ""
        if col == self.COL_NOTES:
            # Single tap on Notes cell -> open popup immediately
            self._open_item_note_popup(row)
            return
        elif col == self.COL_TAX:
            item = self.invoice_table.item(row, col)
            if item: item.setText("" if item.text() == "T" else "T")
        elif col in (self.COL_PART_NO, self.COL_NAME):
            # Open inline search ONLY on empty rows. Clicking an existing
            # cart line should just move the active row (so Up/Down arrow
            # navigation keeps working) - the search popup stole focus before.
            name_item = self.invoice_table.item(row, self.COL_NAME)
            is_filled = bool(name_item and name_item.text().strip())
            if is_filled:
                self._close_inline_search()
                self._highlight_active_row(row)
                self.invoice_table.setFocus()
                
                if col == self.COL_PART_NO:
                    self._edit_dosage(row)
            else:
                self._open_inline_search(row, col)
        else:
            # Clicking price/qty/disc cols - close search, ready for keyboard/numpad
            self._close_inline_search()
            self._highlight_active_row(row)
            self.invoice_table.setFocus()
        
        if col not in (0, 1):
            return
        # Removed ProductSearchDialog as requested - inline search handles this.

    def _edit_dosage(self, row):
        """Pops up the dosage dialog to edit the dosage for a pharmacy item."""
        part_item = self.invoice_table.item(row, self.COL_PART_NO)
        name_item = self.invoice_table.item(row, self.COL_NAME)
        if not part_item or not name_item:
            return
            
        pharm_meta = part_item.data(self.PHARMACY_META_ROLE)
        if pharm_meta and pharm_meta.get("is_pharmacy"):
            product_id = part_item.data(Qt.UserRole)
            new_meta = self._prompt_dosage_and_batch(product_id)
            if new_meta and (new_meta.get("dosage") or new_meta.get("batch_no") or new_meta.get("expiry_date")):
                pharm_meta.update(new_meta)
                part_item.setData(self.PHARMACY_META_ROLE, pharm_meta)
                
                # Update the displayed name with the new dosage
                name_text = name_item.text()
                base_name = name_text.split("  |  ")[0]
                if new_meta.get("dosage"):
                    name_item.setText(f"{base_name}  |  {str(new_meta['dosage']).strip()}")
                else:
                    name_item.setText(base_name)
            self._highlight_active_row(row)
            self.invoice_table.setFocus()

    def _on_cell_double_clicked(self, row, col):
        if col == self.COL_NOTES:
            self._open_item_note_popup(row)
            return
        
        # Other columns double-click behavior (e.g. open search if it's item name/code)
        if col in (self.COL_PART_NO, self.COL_NAME):
            # Already handled by _on_cell_clicked or inline search
            pass

    def _on_product_btn_clicked(self, product: dict):
        """Product tile tapped - debounce, then route through the shared
        template/variant/uom/price pipeline."""
        try:
            self._close_inline_search()

            import time as _time
            now  = _time.monotonic()
            last = getattr(self, "_last_grid_tap", 0)
            if now - last < 0.20:
                return
            self._last_grid_tap = now

            picked = self._pick_product_uom_and_price(product)
            if picked is None:
                return
            product, uom, price = picked

            self._add_product_to_invoice(
                name       = product.get("name", ""),
                price      = price,
                part_no    = product.get("part_no", ""),
                product_id = product.get("id"),
                stock      = product.get("stock"),
                uom        = uom,
            )
        except Exception as _e:
            import traceback; traceback.print_exc()
            try:
                QMessageBox.warning(self, "Error", f"Could not add product to cart:\n{_e}")
            except Exception:
                pass

    def _pick_product_uom_and_price(
        self, product: dict, barcode_uom: str = None
    ) -> tuple[dict, str, float] | None:
        """
        Shared pre-add pipeline used by every "add this product to cart"
        path (grid tile tap, inline search commit, double-click cell
        picker, barcode lookup, etc.).

        Steps:
          1. Resolve a (uom, price) pair against the active customer's
             price list first. `_resolve_price_for_product` opens
             `UomPickerDialog` when the item has more than one UOM row.
          2. If the product is a *template*, open the variant
             picker and swap in the selected variant second.
          3. Returns (product_actually_used, uom, price), or None if the
             cashier cancelled or anything was rejected.
        """
        if not product:
            return None

        # 1. Resolve UOM first
        picked = self._resolve_price_for_product(product, barcode_uom=barcode_uom)
        if picked is None:
            return None
        uom, price = picked

        # 2. Resolve Variant second
        if self._is_template_product(product):
            variant_product = self._pick_variant(product) or {}
            if not variant_product:
                return None  # user cancelled the variant picker
            product = variant_product
            
            # Re-resolve the price for the chosen variant with the selected UOM
            price_list = self._get_active_price_list()
            if price_list:
                var_rows = self._get_price_rows_for_list(product.get("part_no", ""), price_list)
                var_uom_row = next((r for r in var_rows if r["uom"].strip().upper() == uom.strip().upper()), None)
                if var_uom_row:
                    price = float(var_uom_row["price"])

        return (product, uom, price)

    # -----------------------------------------------------------------------
    # Price-list resolution (task 1e)
    # -----------------------------------------------------------------------

    def _get_active_price_list(self) -> str | None:
        """Active customer's price list name (cached in-memory for 0ms lookup)."""
        if getattr(self, "_cached_active_price_list_name", None):
            return self._cached_active_price_list_name

        cust = self._selected_customer or {}
        name = (cust.get("price_list_name") or "").strip()
        if not name:
            pl_id = cust.get("default_price_list_id")
            if pl_id:
                try:
                    from database.db import get_connection
                    _conn = get_connection(); _cur = _conn.cursor()
                    _cur.execute("SELECT name FROM price_lists WHERE id = ?", (pl_id,))
                    _row = _cur.fetchone(); _conn.close()
                    if _row and _row[0]: name = str(_row[0]).strip()
                except Exception: pass

        if not name and getattr(self, "_active_price_list", None):
            name = self._active_price_list

        if not name:
            name = "Standard Selling"

        self._cached_active_price_list_name = name
        return name

    def _get_price_rows_for_list(self, part_no: str, price_list: str) -> list[dict]:
        """All (uom, price) rows for an item under the given price list (cached in-memory)."""
        if not hasattr(self, "_price_rows_cache"):
            self._price_rows_cache = {}
        cache_key = (part_no, price_list)
        if cache_key in self._price_rows_cache:
            return self._price_rows_cache[cache_key]

        try:
            from database.db import get_connection
            conn = get_connection()
            cur  = conn.cursor()
            cur.execute("""
                SELECT uom, price FROM item_prices
                WHERE  part_no = ? AND price_list = ? AND price_type = 'selling'
                ORDER  BY CASE WHEN uom = 'nos' THEN 0 ELSE 1 END, price
            """, (part_no, price_list))
            rows = cur.fetchall()

            result = [{"uom": r[0], "price": float(r[1] or 0)} for r in rows]
            seen_uoms = {r["uom"].strip().upper() for r in result}

            try:
                cur.execute("""
                    SELECT uom, price FROM product_uom_prices
                    WHERE part_no = ?
                    ORDER BY price
                """, (part_no,))
                for r in cur.fetchall():
                    uom_key = str(r[0]).strip().upper()
                    if uom_key not in seen_uoms:
                        result.append({"uom": r[0], "price": float(r[1] or 0)})
                        seen_uoms.add(uom_key)
            except Exception:
                pass

            conn.close()
            self._price_rows_cache[cache_key] = result
            return result
        except Exception as e:
            print(f"[pos] _get_price_rows_for_list failed ({part_no}/{price_list}): {e}")
            return []
            return []

    def _resolve_price_for_product(self, product: dict, barcode_uom: str = None) -> tuple[str, float] | None:
        """
        Returns (uom, price) or None.

        None means "don't add to cart" - we've already shown an explanation to
        the cashier (no customer / no price list / item not priced / zero).
        """
        part_no  = product.get("part_no", "")
        base_uom = str(product.get("uom", "Nos") or "Nos")
        name     = product.get("name", part_no)

        if not self._selected_customer:
            self._warn_popup(
                "No customer selected",
                f"Pick a customer before adding <b>{name}</b> - the price "
                f"depends on the customer's price list.",
            )
            return None

        price_list = self._get_active_price_list()
        if not price_list:
            self._warn_popup(
                "No price list",
                f"The current customer has no default price list. "
                f"<b>{name}</b> can't be sold until one is assigned.",
            )
            return None

        rows = self._get_price_rows_for_list(part_no, price_list)
        if not rows or all(float(r.get("price", 0)) <= 0 for r in rows):
            # [BUNDLE-PRICE] Fallback to bundle component total if no parent price list entry
            try:
                is_bundle = product.get("is_product_bundle")
                if is_bundle:
                    import json
                    lines_json = product.get("bundle_lines") or "[]"
                    b_items = json.loads(lines_json)
                    
                    from models.item_price import get_prices_map
                    pm = get_prices_map(price_list)
                    
                    bundle_total = 0.0
                    for b_item in b_items:
                        i_code = (b_item.get("item_code") or b_item.get("product_code") or b_item.get("code") or b_item.get("part_no") or "").upper().strip()
                        i_qty  = float(b_item.get("quantity") or 0)
                        i_rate = float(b_item.get("rate") or b_item.get("sale_price") or 0)
                        if i_rate <= 0:
                            i_rate = float(pm.get(i_code, 0) or 0)
                        bundle_total += (i_qty * i_rate)
                    
                    if bundle_total > 0:
                        rows = [{"uom": base_uom, "price": bundle_total}]
            except Exception as e:
                print(f"[BundlePrice] Error resolving bundle price: {e}")

        if not rows:
            self._warn_popup(
                "Item not priced",
                f"<b>{name}</b> has no price in the <b>{price_list}</b> "
                f"price list. Add a rate on the server and re-sync.",
            )
            return None

        # Pre-selected barcode_uom (from scanned barcode) bypasses UOM picker
        if barcode_uom:
            picked = next((r for r in rows if r["uom"].strip().upper() == barcode_uom.strip().upper()), None)
            if not picked:
                # Fallback: if barcode UOM has no specific price, construct it with price=0.0
                picked = {"uom": barcode_uom, "price": 0.0}
        # Single UOM -> use it directly.
        elif len(rows) == 1:
            picked = rows[0]
        else:
            dlg = UomPickerDialog(
                product_name=name,
                uom_prices=rows,
                parent=self,
            )
            if dlg.exec() != QDialog.Accepted or not dlg.selected_uom:
                return None
            picked = {"uom": dlg.selected_uom, "price": dlg.selected_price}

        if float(picked["price"] or 0) < 0:
            self._warn_popup(
                "Negative-priced item",
                f"<b>{name}</b> is priced at 0 in <b>{price_list}</b>. "
                f"The POS won't sell negative-priced items - update the price "
                f"on the server and re-sync.",
            )
            return None

        return (picked.get("uom") or base_uom, float(picked["price"]))

    # -----------------------------------------------------------------------
    # Variants (task 3c) - picker placeholder wired in the dialog step
    # -----------------------------------------------------------------------

    def _is_template_product(self, product: dict) -> bool:
        """True for items flagged as variant templates by the sync."""
        return bool(product.get("is_template") or product.get("has_variants"))

    def _pick_variant(self, template: dict) -> dict | None:
        """
        Open the variant picker (built in task 3c). Import kept local so a
        missing module doesn't break POS startup.
        """
        try:
            from views.dialogs.variant_picker_dialog import VariantPickerDialog
        except Exception as e:
            print(f"[pos] variant picker unavailable: {e}")
            self._warn_popup(
                "Variants not available",
                "This item has variants but the picker dialog is not "
                "installed yet. Please update the POS.",
            )
            return None

        dlg = VariantPickerDialog(template=template, parent=self)
        if dlg.exec() != QDialog.Accepted or not dlg.selected_variant:
            return None
        return dlg.selected_variant

    # =========================================================================
    # PERMISSION CHECK HELPER  (#23)
    # =========================================================================
    def _check_permission(self, flag: str, action_label: str = "This action") -> bool:
        """
        Return True if the current user has the given permission flag.
        If denied, prompts for an admin PIN - grants access if PIN is valid.
        Falls back to True for admins; defaults to True if column not present yet.
        """
        from PySide6.QtWidgets import QInputDialog
        user = self.user or {}
        # Admins always have all permissions
        if (user.get("role") or "").lower() == "admin":
            return True
        # Check flag - default True if not set (backward compat)
        allowed = bool(user.get(flag, False))
        if not allowed:
            # Offer admin PIN bypass
            pin, ok = QInputDialog.getText(
                self,
                "Authorization Required",
                f"<b>{action_label}</b> requires admin authorization.\n\nEnter Admin PIN:",
                __import__("PySide6.QtWidgets", fromlist=["QLineEdit"]).QLineEdit.Password,
            )
            if not ok or not pin:
                return False
            try:
                from models.user import authenticate_by_pin
                manager = authenticate_by_pin(pin)
                if manager and (manager.get("role") or "").lower() == "admin":
                    return True
            except Exception:
                pass
            self._warn_popup(
                "Access Denied",
                f"<b>{action_label}</b> - invalid admin PIN.",
                icon=QMessageBox.Critical,
            )
            return False
        return True

    # =========================================================================
    # SHARED POPUP HELPER
    # =========================================================================
    def _warn_popup(self, title: str, html: str, icon=None):
        """Styled warning/info popup used by POS rule blocks."""
        msg = QMessageBox(self)
        msg.setWindowTitle(title)
        msg.setText(html)
        msg.setIcon(icon or QMessageBox.Warning)
        msg.setStandardButtons(QMessageBox.Ok)
        msg.setStyleSheet(f"""
            QMessageBox {{ background:{WHITE}; }}
            QLabel       {{ color:{DARK_TEXT}; font-size:13px; }}
            QPushButton  {{
                background:{ACCENT}; color:{WHITE}; border:none;
                border-radius:5px; padding:8px 22px; font-size:13px; min-width:80px;
            }}
            QPushButton:hover {{ background:{ACCENT_H}; }}
        """)
        msg.exec()
        # Return focus to the invoice table
        QTimer.singleShot(0, lambda: self.invoice_table.setFocus())

    # =========================================================================
    # =========================================================================
    # SHIFT GUARD  - called before any transaction action
    # =========================================================================
    def _prompt_open_shift_if_missing(self):
        """Called once after MainWindow is shown. If no shift is active, opens
        the Start Shift dialog to enter opening float in base currency."""
        try:
            from models.shift import get_active_shift
            if get_active_shift():
                return
        except Exception:
            return
        try:
            from views.dialogs.start_shift_dialog import StartShiftDialog
            dlg = StartShiftDialog(self, user=self.user)
            if dlg.exec() == QDialog.Accepted:
                self._refresh_shift_pill()
        except Exception as e:
            print(f"[MainWindow] prompt open-shift failed: {e}")

    def _require_active_shift(self) -> bool:
        """
        Returns True immediately when a shift is running.
        If no shift is active, opens the Start Shift dialog asking for base currency float.
        Returns True if shift was started, or False if canceled.
        """
        try:
            from models.shift import get_active_shift
            if get_active_shift():
                return True
        except Exception:
            return True   # can't check -> fail open, don't block

        # No active shift - open the Start Shift dialog
        try:
            from views.dialogs.start_shift_dialog import StartShiftDialog
            dlg = StartShiftDialog(self, user=self.user)
            if dlg.exec() == QDialog.Accepted:
                self._refresh_shift_pill()
                return True
            return False
        except Exception as e:
            print(f"[_require_active_shift] StartShiftDialog launch failed: {e}")
            return False

    # POS RULES HELPERS  (#3 #4 #7)
    # =========================================================================
    def _get_pos_rule(self, key: str, default: bool = True) -> bool:
        """Read a single toggle from pos_settings table. Fast; falls back to default."""
        if not hasattr(self, '_pos_rules_cache'): self._pos_rules_cache = {}
        import time
        cache_entry = self._pos_rules_cache.get(key)
        if cache_entry and time.time() - cache_entry[1] < 2.0:
            return cache_entry[0]
        try:
            from database.db import get_connection
            conn = get_connection(); cur = conn.cursor()
            cur.execute(
                "SELECT setting_value FROM pos_settings WHERE setting_key=?", (key,))
            row = cur.fetchone(); conn.close()
            val = bool(int(row[0])) if row else default
            self._pos_rules_cache[key] = (val, time.time())
            return val
        except Exception as e:
            print(f"[_get_pos_rule] Error fetching {key}: {e}")
            if cache_entry: return cache_entry[0]
            return default

    def _apply_pricing_rules(self, product_id, part_no: str, price: float) -> float:
        """#7 - fetch pricing rule discount and return adjusted price."""
        try:
            from services.frappe_api import get_pricing_rule_discount
            disc_pct = get_pricing_rule_discount(part_no) or 0.0
            if disc_pct > 0:
                return round(price * (1.0 - disc_pct / 100.0), 2)
        except Exception:
            pass
        return price

    
    # ── Invoice footer - Items | Paid | Change+InvoiceNo | TOTAL ─────────────
    def _build_invoice_footer(self):
        bar = QWidget(); bar.setFixedHeight(42)
        bar.setStyleSheet(f"background-color: #f0e8d0; border-top: 2px solid {BORDER};")
        layout = QHBoxLayout(bar)
        layout.setContentsMargins(14, 0, 14, 0)
        layout.setSpacing(0)

        self._bin_qty = QLabel("Items: 0")
        self._bin_qty.setStyleSheet(f"color: {MUTED}; font-size: 13px; background: transparent;")
        layout.addWidget(self._bin_qty)
        layout.addSpacing(12)

        sep1 = QLabel("|")
