        from PySide6.QtWidgets import QStackedWidget, QScrollArea, QGridLayout, QSizePolicy
        from PySide6.QtCore import QSize
        
        root = QVBoxLayout(self)
        root.setSpacing(0)
        root.setContentsMargins(0, 0, 0, 0)

