    # -------------------------------------------------------------------------
    # SUB-PAGE ICON GRID BUILDER
    # -------------------------------------------------------------------------
    def _build_sub_icon_grid(self, items, handlers, n_cols=4):
        """Build a scrollable icon-tile grid for sub-pages.
        items  = [(label, icon_name, color), ...]
        handlers = [callable, ...] (parallel list)
        """
        from PySide6.QtWidgets import QScrollArea, QGridLayout
        from PySide6.QtCore import QSize
        container = QWidget()
        container.setStyleSheet(f"background:{OFF_WHITE};")
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setStyleSheet("QScrollArea { border: none; background: transparent; }")
        grid_w = QWidget()
        grid_w.setStyleSheet("background: transparent;")
        grid = QGridLayout(grid_w)
        grid.setContentsMargins(50, 40, 50, 40)
        grid.setSpacing(22)
        grid.setAlignment(Qt.AlignCenter)
        for i, ((label, icon_name, color), handler) in enumerate(zip(items, handlers)):
            btn = self._create_sub_icon_button(label, icon_name, color)
            btn.clicked.connect(handler)
            grid.addWidget(btn, i // n_cols, i % n_cols)
        scroll.setWidget(grid_w)
        lay = QVBoxLayout(container)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.addWidget(scroll)
        return container

    def _create_sub_icon_button(self, name, icon_name, color):
        """Smaller icon tile for sub-pages (vs the big tiles on main grid)."""
        from PySide6.QtWidgets import QToolButton
        from PySide6.QtCore import QSize
        btn = QToolButton()
        btn.setFixedSize(128, 112)
        btn.setCursor(Qt.PointingHandCursor)
        btn.setIcon(qta.icon(icon_name, color=color))
        btn.setIconSize(QSize(38, 38))
        btn.setText(name)
        btn.setToolButtonStyle(Qt.ToolButtonTextUnderIcon)
        btn.setStyleSheet(f"""
            QToolButton {{
                background-color: {WHITE};
                border: 1px solid {BORDER};
                border-radius: 12px;
                color: {NAVY};
                font-weight: 600;
                font-size: 11px;
                padding-top: 14px;
                padding-bottom: 14px;
            }}
            QToolButton:hover {{
                background-color: #f0f4ff;
                border: 2px solid {color};
                color: {color};
            }}
            QToolButton:pressed {{
                background-color: {LIGHT};
            }}
        """)
        return btn

    def _open_module_page(self, idx, name):
        """Lazily build and display sub-modules on demand to keep initial dashboard creation 0ms instant."""
        if not hasattr(self, "_odoo_modules_loaded"):
            self._odoo_modules_loaded = {}

        if name not in self._odoo_modules_loaded:
            if name == "Company Defaults":
                widget = self._build_company_defaults_page()
            else:
                if not hasattr(self, "odoo_modules") or not self.odoo_modules:
                    from views.components.odoo_builders import build_odoo_modules
                    self.odoo_modules = build_odoo_modules(self)
                widget = self.odoo_modules.get(name, QWidget())

            self._odoo_modules_loaded[name] = widget
            # Replace placeholder widget in stack at index idx
            old_w = self.stack.widget(idx)
            if old_w and old_w != widget:
                self.stack.removeWidget(old_w)
                self.stack.insertWidget(idx, widget)

        self.stack.setCurrentIndex(idx)

    def _build_app_grid(self):
        from PySide6.QtWidgets import QScrollArea, QGridLayout
        from PySide6.QtCore import QSize
        container = QWidget()
        container.setStyleSheet(f"background:{OFF_WHITE};")
        
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setStyleSheet("QScrollArea { border: none; background: transparent; }")
        
        grid_widget = QWidget()
        grid_widget.setStyleSheet("background: transparent;")
        
        grid_layout = QGridLayout(grid_widget)
        grid_layout.setContentsMargins(60, 60, 60, 60)
        grid_layout.setSpacing(35)
        grid_layout.setAlignment(Qt.AlignCenter)
        
        def _open_inventory():
            self._open_module_page(4, "Inventory")
            try:
                if hasattr(self, "odoo_modules") and "Inventory" in self.odoo_modules:
                    self.odoo_modules["Inventory"].stack.setCurrentIndex(1)
                if hasattr(self, "_add_stock_btn"):
                    self._add_stock_btn.setVisible(True)
                self._load_stock_data()
            except Exception as e:
                print(f"[AdminDashboard] Error jumping to Products: {e}")

        apps = [
            ("Sales",            "fa5s.chart-line",         lambda: self._open_module_page(1, "Sales"),  ACCENT),
            ("Suppliers",        "fa5s.truck",              lambda: self._open_module_page(2, "Suppliers"),  "#e67e22"),
            ("Finance",          "fa5s.hand-holding-usd",   lambda: self._open_module_page(3, "Finance"),  "#8e44ad"),
            ("Inventory",        "fa5s.boxes",              _open_inventory,  SUCCESS),
            ("POS",              "fa5s.cash-register",      lambda: getattr(self.parent_window, "switch_to_pos", lambda: None)(), ACCENT),
            ("Expenses",         "fa5s.receipt",            lambda: self._open_module_page(5, "Expenses"),  "#f39c12"),
            ("Settings",         "fa5s.cog",                lambda: self._open_module_page(6, "Settings"),  "#7f8c8d"),
            ("Company Defaults", "fa5s.building",           lambda: self._open_module_page(7, "Company Defaults"),  "#16a085"),
        ]
        
        filtered_apps = []
        try:
            from services.credentials import get_system_mode
            from models.advance_settings import AdvanceSettings
            mode = get_system_mode()
            if mode in ("frappe", "odoo", "saas"):
                adv_settings = AdvanceSettings.load_from_file()
                toggles = {
                    "Sales": adv_settings.showAppSales,
                    "Suppliers": adv_settings.showAppSuppliers,
                    "Finance": adv_settings.showAppFinance,
                    "Inventory": adv_settings.showAppInventory,
                    "Expenses": adv_settings.showAppExpenses,
                }
                for name, icon, cb, color in apps:
                    if name in ("POS", "Settings", "Company Defaults"):
                        filtered_apps.append((name, icon, cb, color))
                    elif toggles.get(name):
                        filtered_apps.append((name, icon, cb, color))
            else:
                filtered_apps = apps
        except Exception as e:
            print(f"[AdminDashboard] Error filtering apps: {e}")
            filtered_apps = apps
        
        col_count = 4
        for i, (name, icon_name, callback, color) in enumerate(filtered_apps):
            btn = self._create_icon_button(name, icon_name, color)
            btn.clicked.connect(callback)
            grid_layout.addWidget(btn, i // col_count, i % col_count)
            
        scroll.setWidget(grid_widget)
        
        lay = QVBoxLayout(container)
        lay.setContentsMargins(0,0,0,0)
        lay.addWidget(scroll)
        return container
        
    def _create_icon_button(self, name, icon_name, color):
        from PySide6.QtWidgets import QToolButton
        from PySide6.QtCore import QSize
        btn = QToolButton()
        btn.setFixedSize(160, 150)
        btn.setCursor(Qt.PointingHandCursor)
        btn.setIcon(qta.icon(icon_name, color=color))
        btn.setIconSize(QSize(52, 52))
        btn.setText(name)
        btn.setToolButtonStyle(Qt.ToolButtonTextUnderIcon)
        btn.setStyleSheet(f"""
            QToolButton {{
                background-color: {WHITE};
                border: 1px solid {BORDER};
                border-radius: 14px;
                color: {NAVY};
                font-weight: 700;
                font-size: 15px;
                padding-top: 24px;
                padding-bottom: 24px;
            }}
            QToolButton:hover {{
                background-color: #f8f9fa;
                border: 2px solid {ACCENT};
                color: {ACCENT};
            }}
        """)
        return btn

