    def _build_overview_tab(self):
        w = QWidget()
        w.setStyleSheet(f"background:{OFF_WHITE};")
        lay = QVBoxLayout(w)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)

        # -- Sales Overview
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setStyleSheet(f"QScrollArea {{ border:none; background:{OFF_WHITE}; }}")
        
        overview_page = QWidget()
        overview_page.setStyleSheet(f"background:{OFF_WHITE};")
        scroll.setWidget(overview_page)

        o_lay = QVBoxLayout(overview_page)
        o_lay.setContentsMargins(24, 20, 24, 20)
        o_lay.setSpacing(18)

        # Product Performance Insights (Charts)
        try:
            from PySide6.QtCharts import QChart, QChartView
            from PySide6.QtGui import QPainter

            charts_lay = QHBoxLayout()
            charts_lay.setSpacing(16)

            from PySide6.QtCore import Qt
            self._sales_chart_qty = QChart()
            self._sales_chart_qty.setTitle("Top Products by Quantity")
            self._sales_chart_qty.setAnimationOptions(QChart.SeriesAnimations)
            self._sales_chart_qty.legend().setAlignment(Qt.AlignBottom)
            f = self._sales_chart_qty.legend().font()
            f.setPointSize(10)
            self._sales_chart_qty.legend().setFont(f)
            cv1 = QChartView(self._sales_chart_qty)
            cv1.setRenderHint(QPainter.Antialiasing)
            cv1.setStyleSheet("background:#ffffff; border:none; border-radius:8px;")
            cv1.setFixedHeight(300)
            charts_lay.addWidget(cv1)

            from PySide6.QtCore import Qt
            self._sales_chart_prof = QChart()
            self._sales_chart_prof.setTitle("Top Products by Profit")
            self._sales_chart_prof.setAnimationOptions(QChart.SeriesAnimations)
            self._sales_chart_prof.legend().setAlignment(Qt.AlignBottom)
            f = self._sales_chart_prof.legend().font()
            f.setPointSize(10)
            self._sales_chart_prof.legend().setFont(f)
            cv2 = QChartView(self._sales_chart_prof)
            cv2.setRenderHint(QPainter.Antialiasing)
            cv2.setStyleSheet("background:#ffffff; border:none; border-radius:8px;")
            cv2.setFixedHeight(300)
            charts_lay.addWidget(cv2)

            o_lay.addWidget(self._section_label("Product Performance Insights"))
            o_lay.addLayout(charts_lay)
        except Exception:
            pass

        # KPI row 1: Financial
        o_lay.addWidget(self._section_label("Financial Summary"))
        o_lay.addLayout(self._build_kpi_row_1())

        # KPI row 2: Stock values
        o_lay.addWidget(self._section_label("Stock Value Summary"))
        o_lay.addLayout(self._build_kpi_row_2())

        o_lay.addStretch()

        lay.addWidget(scroll)
        return w

    def _build_kpi_row_1(self):
        row = QHBoxLayout()
        row.setSpacing(14)
        self._kpi = {}

        for key, label, icon, color in [
            ("sales", "Total Sales", "fa5s.money-bill", ACCENT),
            ("expenses", "Expenses", "fa5s.chart-line", DANGER),
            ("profit", "Gross Profit", "fa5s.chart-line", SUCCESS),
            ("exp_profit", "Expected Profit", "fa5s.bullseye", AMBER),
        ]:
            card, val_lbl = self._kpi_card(label, icon, "$0.00", color)
            self._kpi[key] = val_lbl
            row.addWidget(card, 1)
        return row

    def _build_kpi_row_2(self):
        row = QHBoxLayout()
        row.setSpacing(14)

        for key, label, icon, color in [
            ("stock_cost", "Stock @ Cost", "fa5s.industry", NAVY),
            ("stock_sell", "Stock @ Selling", "fa5s.tag", ACCENT_H),
            ("potential", "Potential Profit", "fa5s.gem", SUCCESS),
        ]:
            card, val_lbl = self._kpi_card(label, icon, "$0.00", color)
            self._kpi[key] = val_lbl
            row.addWidget(card, 1)
        return row

    def _kpi_card(self, label: str, icon: str, initial: str, color: str):
        card = QWidget()
        card.setStyleSheet(f"""
            QWidget {{
                background:{WHITE}; border:none;
                border-radius:8px;
            }}
        """)
        card.setFixedHeight(88)
        cl = QVBoxLayout(card)
        cl.setContentsMargins(16, 12, 16, 12)
        cl.setSpacing(4)

        top = QHBoxLayout()
        lbl = QLabel(label)
        lbl.setStyleSheet(
            f"color:{MUTED}; font-size:11px; background:transparent; "
            "font-weight:bold; letter-spacing:0.5px; text-transform: uppercase;"
        )
        top.addWidget(lbl, 1)
        
        val = QLabel(initial)
        # Use NAVY for values to keep it clean and professional
        val.setStyleSheet(
            f"color:{NAVY}; font-size:22px; font-weight:bold; background:transparent;"
        )
        cl.addLayout(top)
        cl.addWidget(val)
        return card, val

