    # TAB: SHIFT RECONCILIATIONS HISTORY
    # =========================================================================

    def _build_shift_history_tab(self):
        from PySide6.QtWidgets import QStackedWidget, QStyledItemDelegate
        from PySide6.QtGui import QBrush, QColor
        
        class WhiteSelectionDelegate(QStyledItemDelegate):
            def initStyleOption(self, option, index):
                super().initStyleOption(option, index)
                from PySide6.QtWidgets import QStyle
                if option.state & QStyle.State_Selected:
                    option.foregroundBrush = QBrush(QColor("white"))
                    
        delegate = WhiteSelectionDelegate(self)
        w = QWidget()
        w.setStyleSheet(f"background:{OFF_WHITE};")
        lay = QVBoxLayout(w)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(12)

        self.shift_history_stack = QStackedWidget()
