    # SECTION LABEL HELPER
    # =========================================================================

    def _section_label(self, text):
        lbl = QLabel(text)
        lbl.setStyleSheet(f"""
            font-size:13px; font-weight:bold; color:{NAVY};
            background:transparent;
            border-left:3px solid {ACCENT}; padding-left:8px;
        """)
