    # =========================================================================
    # DATA LOADING
    # =========================================================================

    def _load_data(self):
        """Asynchronously chunk data loading steps so Qt main GUI thread never freezes."""
        from PySide6.QtCore import QTimer
        QTimer.singleShot(0, self._load_financial_kpis)
        QTimer.singleShot(40, self._load_top_items)
        QTimer.singleShot(80, self._load_recent_sales)
        QTimer.singleShot(120, self._load_stock_alerts)
        QTimer.singleShot(160, self.load_shift_history)
        QTimer.singleShot(200, self._load_stock_data)

    def load_shift_history(self):
        if not hasattr(self, "shift_history_table") or not self.shift_history_table:
            return
        try:
            from models.shift import get_shift_reports
            date_from = None
            date_to = None
            if hasattr(self, "shift_history_report"):
                date_from = self.shift_history_report.start_date.date().toString("yyyy-MM-dd") + " 00:00:00"
                date_to = self.shift_history_report.end_date.date().toString("yyyy-MM-dd") + " 23:59:59"
            shifts = get_shift_reports(date_from=date_from, date_to=date_to)
            
            self.shift_history_table.setRowCount(0)
            self.shift_cashiers_table.setRowCount(0) # Clear bottom table
            
            for s in shifts:
                shift_id = s.get("id")
                shift_no = s.get("shift_no")
                created_at = s.get("created_at")
                cashier_name = s.get("cashier_name") or "-"
                expected = float(s.get("expected_amount") or 0.0)
                actual = float(s.get("actual_amount") or 0.0)
                variance = float(s.get("variance") or 0.0)
                
                # Check if actual is 0 but it's an open shift
                is_open = s.get("actual_amount") is None
                
                if is_open:
                    actual_str = "Open"
                    variance_str = "Open"
                else:
                    actual_str = f"{actual:,.2f}"
                    variance_str = f"{variance:,.2f}"
                    
                # Format Date
                if created_at and hasattr(created_at, 'strftime'):
                    date_str = created_at.strftime("%Y-%m-%d")
                elif created_at:
                    date_str = str(created_at)[:10]
                else:
                    date_str = "-"
                    
                row_idx = self.shift_history_table.rowCount()
                self.shift_history_table.insertRow(row_idx)
                
                items = [
                    QTableWidgetItem(date_str),
                    QTableWidgetItem(str(shift_no)),
                    QTableWidgetItem(f"{expected:,.2f}"),
                    QTableWidgetItem(actual_str),
                    QTableWidgetItem(variance_str),
                ]
                
                # Store shift ID as UserRole data in the first item so we can fetch it when clicked
                items[0].setData(Qt.UserRole, shift_id)
                
                for col_idx, item in enumerate(items):
                    if col_idx in (2, 3, 4):
                        item.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                        if col_idx == 2:
                            item.setForeground(QColor(NAVY))
                        elif col_idx == 3 and not is_open:
                            item.setForeground(QColor(ACCENT))
                        elif col_idx == 4 and not is_open:
                            item.setForeground(QColor(SUCCESS if variance >= 0 else DANGER))
                    elif col_idx == 0:
                        item.setTextAlignment(Qt.AlignLeft | Qt.AlignVCenter)
                    else:
                        item.setTextAlignment(Qt.AlignCenter)
                        if col_idx == 3 and is_open:
                            item.setForeground(QColor(AMBER))
                            
                    self.shift_history_table.setItem(row_idx, col_idx, item)
                    
                self.shift_history_table.setRowHeight(row_idx, 34)
        except Exception as e:
            print(f"[AdminDashboard] Failed to load shift history: {e}")
            import traceback
            traceback.print_exc()

    def _on_view_details_clicked(self):
        selected_items = self.shift_history_table.selectedItems()
        if not selected_items:
            QMessageBox.information(self, "Selection Required", "Please select a shift to view details.")
            return
        row = selected_items[0].row()
        self._show_shift_details_by_row(row)

    def _on_shift_double_clicked(self, index):
        row = index.row()
        self._show_shift_details_by_row(row)

    def _show_shift_details_by_row(self, row):
        first_item = self.shift_history_table.item(row, 0)
        shift_no_item = self.shift_history_table.item(row, 1)
        if first_item:
            shift_id = first_item.data(Qt.UserRole)
            shift_date = first_item.text()
            shift_no = shift_no_item.text() if shift_no_item else "-"
            if shift_id:
                # Set title
                self.shift_detail_title.setText(f"Shift #{shift_no} Cashier Breakdown - Date: {shift_date}")
                # Load cashier slots
                self.load_cashiers_for_shift(shift_id)
                # Switch page
                self.shift_history_stack.setCurrentIndex(1)

    def _go_back_to_shift_list(self):
        self._on_modified_page = False
        self.shift_history_stack.setCurrentIndex(0)
        self.load_shift_history()

    def load_cashiers_for_shift(self, shift_id):
        try:
            self._current_shift_id = shift_id
            # Fetch all cashiers who worked this shift
            from models.shift import get_shift_by_id, get_all_cashier_reconciliations_for_shift
            shift = get_shift_by_id(shift_id)
            if not shift:
                return
            
            # Load cashier reconciliations recorded in DB
            recorded_cashiers = {rc["cashier_id"]: rc for rc in get_all_cashier_reconciliations_for_shift(shift_id)}
            
            cashier_sales = shift.get("cashier_sales", [])
            self._current_cashier_sales_list = cashier_sales
            
            # Build global collected maps across all cashiers for pro-rata expectations
            global_collected_map = {}
            for cashier in cashier_sales:
                cashier_payment_methods = cashier.get("totals", {}).get("payment_methods", {})
                cashier_credit_total = 0.0
                for sale in cashier.get("sales", []):
                    if sale.get("is_on_account", False) and sale.get("total", 0) > sale.get("tendered", 0):
                        cashier_credit_total += sale.get("total", 0) - sale.get("tendered", 0)
                
                c_methods = dict(cashier_payment_methods)
                if cashier_credit_total > 0:
                    c_methods["ON ACCOUNT"] = cashier_credit_total
                    
                for m, amt in c_methods.items():
                    m_key = m.strip().upper()
                    global_collected_map[m_key] = global_collected_map.get(m_key, 0.0) + float(amt)

            # Load global expected maps to calculate prorated expected per cashier
            global_expected_map = {}
            for sr in shift.get("rows", []):
                m_key = sr["method"].strip().upper()
                global_expected_map[m_key] = float(sr.get("total", 0.0))

            self.shift_cashiers_table.setRowCount(0)
            for cashier in cashier_sales:
                c_id = cashier.get("cashier_id")
                c_name = cashier.get("cashier_name", "Unknown")
                cashier_payment_methods = cashier.get("totals", {}).get("payment_methods", {})
                
                cashier_credit_total = 0.0
                for sale in cashier.get("sales", []):
                    if sale.get("is_on_account", False) and sale.get("total", 0) > sale.get("tendered", 0):
                        cashier_credit_total += sale.get("total", 0) - sale.get("tendered", 0)
                
                if cashier_credit_total > 0:
                    cashier_payment_methods = dict(cashier_payment_methods)
                    cashier_payment_methods["ON ACCOUNT"] = cashier_credit_total
                
                if not cashier_payment_methods:
                    continue

                # Get expected sum
                cashier_expected_sum = 0.0
                for method_key, amount_collected in cashier_payment_methods.items():
                    method_upper = method_key.strip().upper()
                    amount_collected = float(amount_collected)
                    total_collected = global_collected_map.get(method_upper, 0.0)
                    proportion = (amount_collected / total_collected) if total_collected > 0 else 0.0
                    cashier_expected_sum += global_expected_map.get(method_upper, 0.0) * proportion

                # Check recorded slot
                rc_record = recorded_cashiers.get(c_id, {})
                is_finalized = bool(rc_record.get("is_finalized", 0))
                finalized_at = rc_record.get("finalized_at", "")
                
                # Format date and time
                shift_date = shift.get("date", "")
                if hasattr(shift_date, 'strftime'):
                    shift_date = shift_date.strftime("%Y-%m-%d")
                    
                # Dynamically calculate From/Start Time based on the cashier's earliest sale or shift open time
                start_time_val = None
                sales = cashier.get("sales", [])
                if sales:
                    sale_times = []
                    for s in sales:
                        s_time = s.get("created_at")
                        if s_time:
                            sale_times.append(s_time)
                    if sale_times:
                        start_time_val = min(sale_times)
                
                if not start_time_val:
                    start_time_val = shift.get("created_at")
                    
                start_time_str = "-"
                if start_time_val:
                    if hasattr(start_time_val, 'strftime'):
                        start_time_str = start_time_val.strftime("%H:%M:%S")
                    else:
                        start_time_str = str(start_time_val).split("T")[-1].split(" ")[-1][:8]
                    
                if is_finalized:
                    if finalized_at and hasattr(finalized_at, 'strftime'):
                        to_time_str = finalized_at.strftime("%H:%M:%S")
                    elif finalized_at:
                        to_time_str = str(finalized_at).split("T")[-1].split(" ")[-1][:8] if "T" in str(finalized_at) else str(finalized_at)[:8]
                    else:
                        to_time_str = "Finalized"
                        
                    counted_data = rc_record.get("counted_data", {})
                    cashier_counted_sum = sum(float(v) for v in counted_data.values())
                    variance = cashier_counted_sum - cashier_expected_sum
                    
                    actual_str = f"{cashier_counted_sum:,.2f}"
                    variance_str = f"{variance:,.2f}"
                else:
                    # Dynamically calculate To/End Time based on the cashier's latest sale
                    latest_time_val = None
                    if sales:
                        sale_times = []
                        for s in sales:
                            s_time = s.get("created_at")
                            if s_time:
                                sale_times.append(s_time)
                        if sale_times:
                            latest_time_val = max(sale_times)
                    
                    if latest_time_val:
                        if hasattr(latest_time_val, 'strftime'):
                            to_time_str = latest_time_val.strftime("%H:%M:%S")
                        else:
                            to_time_str = str(latest_time_val).split("T")[-1].split(" ")[-1][:8]
                    else:
                        to_time_str = "Active"
                    actual_str = ""
                    variance_str = ""

                row_idx = self.shift_cashiers_table.rowCount()
                self.shift_cashiers_table.insertRow(row_idx)
                
                items = [
                    QTableWidgetItem(str(c_name)),
                    QTableWidgetItem(str(shift_date)),
                    QTableWidgetItem(str(start_time_str)),
                    QTableWidgetItem(str(to_time_str)),
                    QTableWidgetItem(f"{cashier_expected_sum:,.2f}"),
                    QTableWidgetItem(actual_str),
                    QTableWidgetItem(variance_str),
                ]
                
                # Store cashier ID as UserRole data in the first item so we can fetch it when clicked
                items[0].setData(Qt.UserRole, c_id)
                
                # Colors and alignments
                for col_idx, item in enumerate(items):
                    if col_idx in (4, 5, 6):
                        item.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                        if col_idx == 4:
                            item.setForeground(QColor(NAVY))
                        elif col_idx == 5 and is_finalized:
                            item.setForeground(QColor(ACCENT))
                        elif col_idx == 6 and is_finalized:
                            item.setForeground(QColor(SUCCESS if variance >= 0 else DANGER))
                    else:
                        item.setTextAlignment(Qt.AlignCenter if col_idx in (1, 2, 3) else Qt.AlignLeft | Qt.AlignVCenter)
                        if col_idx == 3:
                            item.setForeground(QColor(SUCCESS if is_finalized else AMBER))
                    
                    self.shift_cashiers_table.setItem(row_idx, col_idx, item)
                    
                self.shift_cashiers_table.setRowHeight(row_idx, 34)
        except Exception as e:
            print(f"[AdminDashboard] Failed to load cashier details for shift: {e}")
            import traceback
            traceback.print_exc()

    def _on_cashier_double_clicked(self, index):
        row = index.row()
        self._show_cashier_mode_details(row)

    def _go_back_to_cashier_list(self):
        prev_idx = getattr(self, '_previous_modes_page_index', 1)
        self.shift_history_stack.setCurrentIndex(prev_idx)

    def _show_cashier_mode_details(self, row):
        try:
            first_item = self.shift_cashiers_table.item(row, 0)
            if not first_item:
                return
            c_id = first_item.data(Qt.UserRole)
            c_name = first_item.text()
            
            if not hasattr(self, '_current_shift_id') or not self._current_shift_id:
                return
            
            # Fetch recorded cashier reconciliation
            from models.shift import get_shift_by_id, get_all_cashier_reconciliations_for_shift
            shift = get_shift_by_id(self._current_shift_id)
            if not shift:
                return
                
            recorded_cashiers = {rc["cashier_id"]: rc for rc in get_all_cashier_reconciliations_for_shift(self._current_shift_id)}
            rc_record = recorded_cashiers.get(c_id, {})
            is_finalized = bool(rc_record.get("is_finalized", 0))
            counted_data = rc_record.get("counted_data", {})
            is_modified = bool(rc_record.get("is_modified", 0))
            modify_reason = str(rc_record.get("modify_reason", "") or "")
            
            # Set the Page 3 title
            shift_no = shift.get("shift_no", "-")
            self.cashier_mode_title.setText(f"Cashier: {c_name} (Shift #{shift_no}) - Payment Mode Breakdown")
            
            if is_modified:
                reason_str = f" | Reason: {modify_reason}" if modify_reason else ""
                self.cashier_mode_subtitle.setText(f"*** MODIFIED / OVERRIDDEN ***{reason_str}")
                self.cashier_mode_subtitle.show()
            else:
                self.cashier_mode_subtitle.hide()
            
            # Find the specific cashier sales object from our sales list
            cashier_sales_obj = None
            if hasattr(self, '_current_cashier_sales_list') and self._current_cashier_sales_list:
                for c in self._current_cashier_sales_list:
                    if c.get("cashier_id") == c_id:
                        cashier_sales_obj = c
                        break
            
            if not cashier_sales_obj:
                return
                
            cashier_payment_methods = cashier_sales_obj.get("totals", {}).get("payment_methods", {})
            
            # Check for account sales (credits)
            cashier_credit_total = 0.0
            for sale in cashier_sales_obj.get("sales", []):
                if sale.get("is_on_account", False) and sale.get("total", 0) > sale.get("tendered", 0):
                    cashier_credit_total += sale.get("total", 0) - sale.get("tendered", 0)
            
            c_methods = dict(cashier_payment_methods)
            if cashier_credit_total > 0:
                c_methods["ON ACCOUNT"] = cashier_credit_total

            # Build global collected maps for pro-rata
            global_collected_map = {}
            for cashier in shift.get("cashier_sales", []):
                pm = cashier.get("totals", {}).get("payment_methods", {})
                cc_total = 0.0
                for sale in cashier.get("sales", []):
                    if sale.get("is_on_account", False) and sale.get("total", 0) > sale.get("tendered", 0):
                        cc_total += sale.get("total", 0) - sale.get("tendered", 0)
                
                methods = dict(pm)
                if cc_total > 0:
                    methods["ON ACCOUNT"] = cc_total
                    
                for m, amt in methods.items():
                    m_key = m.strip().upper()
                    global_collected_map[m_key] = global_collected_map.get(m_key, 0.0) + float(amt)

            # Load global expected maps to calculate prorated expected per cashier
            global_expected_map = {}
            for sr in shift.get("rows", []):
                m_key = sr["method"].strip().upper()
                global_expected_map[m_key] = float(sr.get("total", 0.0))

            # Populate Page 3 Modes Table
            self.cashier_modes_table.setRowCount(0)
            
            for method_key, amount_collected in c_methods.items():
                method_upper = method_key.strip().upper()
                amount_collected = float(amount_collected)
                total_collected = global_collected_map.get(method_upper, 0.0)
                proportion = (amount_collected / total_collected) if total_collected > 0 else 0.0
                mode_expected = global_expected_map.get(method_upper, 0.0) * proportion
                
                if is_finalized:
                    # Counted data can be recorded under upper-cased names
                    mode_counted = float(counted_data.get(method_upper, 0.0))
                    mode_variance = mode_counted - mode_expected
                    counted_str = f"{mode_counted:,.2f}"
                    variance_str = f"{mode_variance:,.2f}"
                else:
                    mode_variance = 0.0
                    counted_str = ""
                    variance_str = ""
                    
                row_idx = self.cashier_modes_table.rowCount()
                self.cashier_modes_table.insertRow(row_idx)
                
                items = [
                    QTableWidgetItem(method_key),
                    QTableWidgetItem(f"{mode_expected:,.2f}"),
                    QTableWidgetItem(counted_str),
                    QTableWidgetItem(variance_str),
                ]
                
                for col_idx, item in enumerate(items):
                    if col_idx in (1, 2, 3):
                        item.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                        if col_idx == 1:
                            item.setForeground(QColor(NAVY))
                        elif col_idx == 2 and is_finalized:
                            item.setForeground(QColor(ACCENT))
                        elif col_idx == 3 and is_finalized:
                            item.setForeground(QColor(SUCCESS if mode_variance >= 0 else DANGER))
                    else:
                        item.setTextAlignment(Qt.AlignLeft | Qt.AlignVCenter)
                        if col_idx == 2 and not is_finalized:
                            item.setForeground(QColor(AMBER))
                            
                    self.cashier_modes_table.setItem(row_idx, col_idx, item)
                self.cashier_modes_table.setRowHeight(row_idx, 34)
                
            # Switch view to Page 3
            self.shift_history_stack.setCurrentIndex(2)
            
        except Exception as e:
            print(f"[AdminDashboard] Failed to load cashier payment mode details: {e}")
            import traceback
            traceback.print_exc()

    def _on_view_modified_logs_clicked(self):
        self._on_modified_page = True
        self._load_modified_reconciliations()
        self.shift_history_stack.setCurrentIndex(3) # Slide to Page 4!

    def _load_modified_reconciliations(self):
        try:
            from models.shift import get_modified_cashier_reconciliations
            records = get_modified_cashier_reconciliations()
            self.modified_recons_table.setRowCount(0)
            
            for r in records:
                c_name = r.get("cashier_name", "-")
                c_id = r.get("cashier_id")
                shift_id = r.get("shift_id")
                shift_no = r.get("shift_no", "-")
                finalized_at = r.get("finalized_at")
                counted_data = r.get("counted_data", {})
                total_counted = sum(float(v) for v in counted_data.values())
                
                # Format Date/Time
                date_str = "-"
                if finalized_at:
                    if hasattr(finalized_at, 'strftime'):
                        date_str = finalized_at.strftime("%Y-%m-%d %H:%M:%S")
                    else:
                        date_str = str(finalized_at)[:19].replace("T", " ")

                row_idx = self.modified_recons_table.rowCount()
                self.modified_recons_table.insertRow(row_idx)

                items = [
                    QTableWidgetItem(date_str),
                    QTableWidgetItem(str(shift_no)),
                    QTableWidgetItem(str(c_name)),
                    QTableWidgetItem(f"${total_counted:,.2f}"),
                    QTableWidgetItem("Double-click to View"),
                ]
                
                # Store IDs inside items
                items[0].setData(Qt.UserRole, (shift_id, c_id, c_name))
                
                for col_idx, item in enumerate(items):
                    if col_idx == 3:
                        item.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                        item.setForeground(QColor(ACCENT))
                    elif col_idx == 4:
                        item.setTextAlignment(Qt.AlignCenter)
                        item.setForeground(QColor(SUCCESS))
                        item.setFont(QFont("Segoe UI", 9, QFont.Bold))
                    else:
                        item.setTextAlignment(Qt.AlignCenter if col_idx == 1 else Qt.AlignLeft | Qt.AlignVCenter)
                        
                    self.modified_recons_table.setItem(row_idx, col_idx, item)
                    
                self.modified_recons_table.setRowHeight(row_idx, 36)
        except Exception as e:
            print(f"[AdminDashboard] Failed to load modified reconciliations: {e}")

    def _on_modified_row_double_clicked(self, index):
        row = index.row()
        first_item = self.modified_recons_table.item(row, 0)
        if not first_item:
            return
        data = first_item.data(Qt.UserRole)
        if data:
            shift_id, c_id, c_name = data
            self._on_modified_page = True # Navigating from modified page!
            self._show_cashier_mode_details_directly(shift_id, c_id, c_name)

