# BARCODE SETTINGS DIALOG - global scale barcode configuration
# =============================================================================
class _BarcodePill(QWidget):
    """Animated toggle pill for barcode settings."""
    def __init__(self, size=20, parent=None):
        super().__init__(parent)
        self._size = size
        self._checked = False
        self._knob_pos = 0.0
        self.setFixedSize(int(2.2 * size), size)
        self.setCursor(Qt.PointingHandCursor)
        from PySide6.QtCore import QPropertyAnimation, QEasingCurve
        from PySide6.QtCore import Property as _Prop
        self._anim = QPropertyAnimation(self, b"knob_pos", self)
        self._anim.setDuration(220)
        self._anim.setEasingCurve(QEasingCurve.InOutCubic)

    def _get_knob_pos(self): return self._knob_pos
    def _set_knob_pos(self, v):
        self._knob_pos = v; self.update()
    from PySide6.QtCore import Property as _Prop
    knob_pos = _Prop(float, _get_knob_pos, _set_knob_pos)

    def isChecked(self): return self._checked
    def setChecked(self, value: bool, animated=False):
        self._checked = bool(value)
        target = 1.0 if self._checked else 0.0
        if animated:
            self._anim.stop()
            self._anim.setStartValue(self._knob_pos)
            self._anim.setEndValue(target)
            self._anim.start()
        else:
            self._knob_pos = target; self.update()

    def mousePressEvent(self, _ev):
        self.setChecked(not self._checked, animated=True)

    def paintEvent(self, _ev):
        from PySide6.QtGui import QPainter, QColor, QLinearGradient, QRadialGradient
        p = QPainter(self); p.setRenderHint(QPainter.Antialiasing)
        s = self._size; w = self.width(); h = self.height(); r = h / 2
        t = self._knob_pos
        if t < 0.01:
            p.setBrush(QColor("#d7d7d7")); p.setPen(Qt.NoPen)
            p.drawRoundedRect(0, 0, w, h, r, r)
        else:
            grad = QLinearGradient(0, 0, w, 0)
            grad.setColorAt(0, QColor("#f19af3")); grad.setColorAt(1, QColor("#f099b5"))
            p.setBrush(QColor("#d7d7d7")); p.setPen(Qt.NoPen)
            p.drawRoundedRect(0, 0, w, h, r, r)
            if t > 0.99:
                p.setBrush(grad); p.drawRoundedRect(0, 0, w, h, r, r)
            else:
                p.setOpacity(t); p.setBrush(grad)
                p.drawRoundedRect(0, 0, w, h, r, r); p.setOpacity(1.0)
        knob_d = 0.8*s; knob_r = knob_d/2
        off_x = 0.1*s; on_x = 1.3*s
        knob_x = off_x + self._knob_pos*(on_x - off_x); knob_y = 0.1*s
        cx = knob_x+knob_r; cy = knob_y+knob_r
        shadow = QRadialGradient(cx, cy+4, knob_r*1.1)
        shadow.setColorAt(0, QColor(0,0,0,55)); shadow.setColorAt(0.6, QColor(0,0,0,30))
        shadow.setColorAt(1, QColor(0,0,0,0))
        p.setBrush(shadow); p.setPen(Qt.NoPen)
        p.drawEllipse(int(knob_x-knob_r*0.15), int(knob_y+knob_r*0.5),
                      int(knob_d*1.3), int(knob_d*0.9))
        kg = QLinearGradient(cx, knob_y, cx, knob_y+knob_d)
        kg.setColorAt(0, QColor("#dedede")); kg.setColorAt(1, QColor("#ffffff"))
        p.setBrush(kg); p.setPen(Qt.NoPen)
        p.drawEllipse(int(knob_x), int(knob_y), int(knob_d), int(knob_d))
        p.end()


class BarcodeSettingsDialog(QDialog):
    """
    Barcode scale settings. Three main modes:
      No Scale           - standard lookup only
      Weight Based Scale - extracts weight from barcode (12 or 13 digit)
      Price Based Scale  - extracts price from barcode (future)
    Sub-setting barcode_scale_digits selects 12 or 13 digit format.
    """
    SETTING_KEY  = "barcode_scale_type"
    DIGITS_KEY   = "barcode_scale_digits"

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Barcode Settings")
        self.setFixedSize(520, 440)
        self.setModal(True)
        self.setWindowFlags(Qt.Dialog | Qt.FramelessWindowHint)
        self.setStyleSheet(f"QDialog {{ background:{WHITE}; border:1px solid {NAVY}; }}")
        self._toggles = {}
        self._build()
        self._load()

    def _build(self):
        from PySide6.QtWidgets import QComboBox
        root = QVBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)

        # ΓöÇΓöÇ Header ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        hdr = QWidget(); hdr.setFixedHeight(50)
        hdr.setStyleSheet(f"background:{NAVY};")
        hl = QHBoxLayout(hdr); hl.setContentsMargins(18, 0, 12, 0)
        ttl = QLabel("BARCODE SETTINGS")
        ttl.setStyleSheet("font-size:11px; font-weight:bold; color:#fff; letter-spacing:1.5px; background:transparent;")
        self._save_btn = QPushButton("SAVE")
        self._save_btn.setFixedSize(78, 28)
        self._save_btn.setCursor(Qt.PointingHandCursor)
        self._save_btn.setStyleSheet(
            f"QPushButton{{background:{SUCCESS};color:#fff;border:none;border-radius:3px;font-weight:bold;font-size:10px;}}"
            f"QPushButton:hover{{background:{SUCCESS_H};}}"
            f"QPushButton:disabled{{background:transparent;color:{SUCCESS};border:1px solid {SUCCESS};}}"
        )
        self._save_btn.clicked.connect(self._save)
        close_btn = QPushButton("\u2715")
        close_btn.setFixedSize(28, 28)
        close_btn.setCursor(Qt.PointingHandCursor)
        close_btn.setStyleSheet(
            "QPushButton{background:transparent;color:#fff;border:none;font-size:13px;}"
            "QPushButton:hover{background:#c0392b;border-radius:3px;}"
        )
        close_btn.clicked.connect(self.reject)
        hl.addWidget(ttl); hl.addStretch()
        hl.addWidget(self._save_btn); hl.addSpacing(6); hl.addWidget(close_btn)
        root.addWidget(hdr)

        # ΓöÇΓöÇ Body ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        body = QWidget()
        bl = QVBoxLayout(body); bl.setContentsMargins(26, 22, 26, 22); bl.setSpacing(14)

        sec_lbl = QLabel("SCALE TYPE")
        sec_lbl.setStyleSheet(f"color:{MUTED}; font-size:10px; font-weight:bold; letter-spacing:1.5px;")
        bl.addWidget(sec_lbl)

        modes = [
            ("No Scale", "Standard barcode lookup - no scale integration."),
            ("Weight Based Scale", "Extracts weight from barcode and sets quantity in kg."),
            ("Price Based Scale",  "Extracts price from barcode (future support)."),
        ]
        for key, desc in modes:
            row_w = QWidget()
            row_w.setStyleSheet(
                f"QWidget {{ background:{OFF_WHITE}; border:none; border-radius:8px; }}"
            )
            rl = QHBoxLayout(row_w); rl.setContentsMargins(16, 12, 16, 12); rl.setSpacing(12)
            pill = _BarcodePill(size=20)
            pill.mousePressEvent = lambda _ev, k=key: self._activate(k)
            self._toggles[key] = pill
            txt = QVBoxLayout(); txt.setSpacing(2)
            lbl = QLabel(key)
            lbl.setStyleSheet(f"font-size:13px; font-weight:bold; color:{NAVY}; background:transparent; border:none;")
            dlbl = QLabel(desc)
            dlbl.setStyleSheet(f"font-size:11px; color:{MUTED}; background:transparent; border:none;")
            dlbl.setWordWrap(True)
            txt.addWidget(lbl); txt.addWidget(dlbl)
            rl.addLayout(txt, 1); rl.addWidget(pill)
            bl.addWidget(row_w)

        # ΓöÇΓöÇ Digit format sub-option (only relevant for Weight Based Scale) ΓöÇΓöÇΓöÇ
        bl.addSpacing(4)
        sub_lbl = QLabel("BARCODE FORMAT")
        sub_lbl.setStyleSheet(f"color:{MUTED}; font-size:10px; font-weight:bold; letter-spacing:1.5px;")
        bl.addWidget(sub_lbl)

        fmt_w = QWidget()
        fmt_w.setStyleSheet(
            f"QWidget {{ background:{OFF_WHITE}; border:none; border-radius:8px; }}"
        )
        fl = QHBoxLayout(fmt_w); fl.setContentsMargins(16, 12, 16, 12); fl.setSpacing(12)
        fmt_lbl = QLabel("Digit Format")
        fmt_lbl.setStyleSheet(f"font-size:12px; font-weight:bold; color:{NAVY}; background:transparent; border:none;")
        self._digits_combo = QComboBox()
        self._digits_combo.addItems(["12-digit (DDPPPPPWWWWC)", "13-digit (DDPPPPPCWWWWC)"])
        self._digits_combo.setFixedHeight(34)
        self._digits_combo.setStyleSheet(f"""
            QComboBox {{
                background:{WHITE}; color:{DARK_TEXT}; border:none;
                border-radius:6px; padding:0 12px; font-size:12px;
            }}
            QComboBox:focus {{ border:2px solid {ACCENT}; }}
            QComboBox::drop-down {{ border:none; width:28px; }}
            QComboBox QAbstractItemView {{
                background:{WHITE}; color:{DARK_TEXT}; border:none;
                selection-background-color:{ACCENT}; selection-color:{WHITE};
            }}
        """)
        fl.addWidget(fmt_lbl); fl.addWidget(self._digits_combo, 1)
        self._fmt_widget = fmt_w
        bl.addWidget(fmt_w)

        hint = QLabel(
            "DD = prefix,  PPPPP = 5-digit item code,  C = check digit,\n"
            "WWWW = weight in grams Clear╖ 1000 -> qty in kg (locked)."
        )
        hint.setWordWrap(True)
        hint.setStyleSheet(
            f"color:{MUTED}; font-size:10px; background:transparent; border:none;"
            f" padding:4px 0 0 0;"
        )
        self._hint_lbl = hint
        bl.addWidget(hint)

        bl.addStretch()
        root.addWidget(body, 1)

    def _activate(self, key):
        for k, pill in self._toggles.items():
            pill.setChecked(k == key, animated=True)
        # Show/hide digit format selector
        is_weight = key == "Weight Based Scale"
        self._fmt_widget.setVisible(is_weight)
        self._hint_lbl.setVisible(is_weight)

    def _load(self):
        current = "No Scale"
        digits = "13-digit (DDPPPPPCWWWWC)"
        try:
            from database.db import get_connection
            conn = get_connection(); cur = conn.cursor()
            cur.execute("SELECT setting_value FROM pos_settings WHERE setting_key=?", (self.SETTING_KEY,))
            row = cur.fetchone()
            if row:
                val = row[0]
                # Migrate old values
                if val in ("12-digit (DDPPPPPWWWWC)", "13-digit (DDPPPPPCWWWWC)"):
                    current = "Weight Based Scale"
                    digits = val
                else:
                    current = val
            cur.execute("SELECT setting_value FROM pos_settings WHERE setting_key=?", (self.DIGITS_KEY,))
            drow = cur.fetchone()
            if drow:
                digits = drow[0]
            conn.close()
        except Exception:
            pass
        self._activate(current)
        idx = 0 if "12" in digits else 1
        self._digits_combo.setCurrentIndex(idx)

    def _save(self):
        try:
            self._save_btn.setEnabled(False); self._save_btn.setText("SAVING\u2026")
            selected = next((k for k, p in self._toggles.items() if p.isChecked()), "No Scale")
            digits = self._digits_combo.currentText()
            from database.db import get_connection
            conn = get_connection(); cur = conn.cursor()
            for key, val in [(self.SETTING_KEY, selected), (self.DIGITS_KEY, digits)]:
                cur.execute(
                    "MERGE pos_settings AS t "
                    "USING (SELECT ? AS k, ? AS v) AS s ON t.setting_key = s.k "
                    "WHEN MATCHED THEN UPDATE SET setting_value = s.v "
                    "WHEN NOT MATCHED THEN INSERT (setting_key, setting_value) VALUES (s.k, s.v);",
                    (key, val),
                )
            conn.commit(); conn.close()
            self._save_btn.setText("\u2713 SAVED")
            from PySide6.QtCore import QTimer
            QTimer.singleShot(1500, lambda: (self._save_btn.setEnabled(True), self._save_btn.setText("SAVE")))
        except Exception as e:
            self._save_btn.setEnabled(True); self._save_btn.setText("SAVE")
            QMessageBox.warning(self, "Error", f"Save failed:\n{e}")

    def keyPressEvent(self, event):
        if event.key() == Qt.Key_Escape: self.reject()
        else: super().keyPressEvent(event)


