# COSTING METHOD DIALOG  -  standalone, accessible from Maintenance
# =============================================================================
class CostingMethodDialog(QDialog):
    """
    Costing method configuration:
      Last Purchase Cost - uses the price from the most recent purchase
      Average Cost       - weighted average across all stock receipts
      LIFO               - Last In, First Out costing
    """
    SETTING_KEY = "costing_method"

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Costing Method Settings")
        self.setFixedSize(520, 350)
        self.setModal(True)
        self.setWindowFlags(Qt.Window | Qt.WindowCloseButtonHint)
        self.setStyleSheet(f"QDialog {{ background:{WHITE}; }}")
        self._toggles = {}
        self._build()
        self._load()

    def _build(self):
        root = QVBoxLayout(self)
        root.setContentsMargins(24, 20, 24, 20)
        root.setSpacing(14)

        # Title + Save row
        top_row = QHBoxLayout()
        ttl = QLabel("COSTING METHOD")
        ttl.setStyleSheet(
            f"color:{NAVY}; font-size:14px; font-weight:bold; letter-spacing:1px;"
        )
        self._save_btn = QPushButton("SAVE")
        self._save_btn.setFixedSize(78, 28)
        self._save_btn.setCursor(Qt.PointingHandCursor)
        self._save_btn.setStyleSheet(
            f"QPushButton{{background:{SUCCESS};color:#fff;border:none;border-radius:5px;font-weight:bold;font-size:10px;}}"
            f"QPushButton:hover{{background:{SUCCESS_H};}}"
            f"QPushButton:disabled{{background:transparent;color:{SUCCESS};border:1px solid {SUCCESS};}}"
        )
        self._save_btn.clicked.connect(self._save)
        top_row.addWidget(ttl)
        top_row.addStretch()
        top_row.addWidget(self._save_btn)
        root.addLayout(top_row)

        sec_lbl = QLabel("Select how item cost is calculated at the time of purchase:")
        sec_lbl.setStyleSheet(f"color:{MUTED}; font-size:11px;")
        root.addWidget(sec_lbl)

        methods = [
            ("Last Purchase Cost", "Use the price from the most recent purchase receipt."),
            ("Average",            "Weighted average cost across all stock receipts."),
            ("LIFO",               "Last In, First Out - most recently received stock is costed first."),
        ]

        for key, desc in methods:
            row_w = QWidget()
            row_w.setStyleSheet(
                f"QWidget {{ background:{OFF_WHITE}; border:none; border-radius:8px; }}"
            )
            rl = QHBoxLayout(row_w)
            rl.setContentsMargins(16, 12, 16, 12)
            rl.setSpacing(12)
            pill = _BarcodePill(size=20)
            pill.mousePressEvent = lambda _ev, k=key: self._activate(k)
            self._toggles[key] = pill
            txt = QVBoxLayout(); txt.setSpacing(2)
            lbl = QLabel(key)
            lbl.setStyleSheet(
                f"font-size:13px; font-weight:bold; color:{NAVY}; background:transparent; border:none;"
            )
            dlbl = QLabel(desc)
            dlbl.setStyleSheet(
                f"font-size:11px; color:{MUTED}; background:transparent; border:none;"
            )
            dlbl.setWordWrap(True)
            txt.addWidget(lbl); txt.addWidget(dlbl)
            rl.addLayout(txt, 1); rl.addWidget(pill)
            root.addWidget(row_w)

        root.addStretch()

    def _activate(self, key):
        for k, pill in self._toggles.items():
            pill.setChecked(k == key, animated=True)

    def _load(self):
        current = "Last Purchase Cost"
        try:
            from database.db import get_connection
            conn = get_connection(); cur = conn.cursor()
            cur.execute(
                "SELECT setting_value FROM pos_settings WHERE setting_key=?",
                (self.SETTING_KEY,)
            )
            row = cur.fetchone()
            if row and row[0]:
                current = row[0]
            conn.close()
        except Exception:
            pass
        self._activate(current)

    def _save(self):
        try:
            self._save_btn.setEnabled(False); self._save_btn.setText("SAVING\u2026")
            selected = next((k for k, p in self._toggles.items() if p.isChecked()), "Last Purchase Cost")
            from database.db import get_connection
            conn = get_connection(); cur = conn.cursor()
            cur.execute(
                "MERGE pos_settings AS t "
                "USING (SELECT ? AS k, ? AS v) AS s ON t.setting_key = s.k "
                "WHEN MATCHED THEN UPDATE SET setting_value = s.v "
                "WHEN NOT MATCHED THEN INSERT (setting_key, setting_value) VALUES (s.k, s.v);",
                (self.SETTING_KEY, selected),
            )
            conn.commit(); conn.close()
            self._save_btn.setText("\u2713 SAVED")
            from PySide6.QtCore import QTimer
            QTimer.singleShot(1500, lambda: (self._save_btn.setEnabled(True), self._save_btn.setText("SAVE")))
        except Exception as e:
            self._save_btn.setEnabled(True); self._save_btn.setText("SAVE")
            QMessageBox.warning(self, "Error", f"Save failed:\n{e}")

    def keyPressEvent(self, event):
        if event.key() == Qt.Key_Escape: self.reject()
        else: super().keyPressEvent(event)


