# POS RULES DIALOG  -  standalone, accessible from Options menu & Maintenance
# =============================================================================
class POSRulesDialog(QDialog):

    """
    Toggle-based POS business rules:
      #3  Block zero-price sales
      #4  Block zero-stock sales
      #7  Apply pricing rules
    Also shows per-user permission summary.
    """

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("POS Rules & Permissions")
        self.setMinimumSize(540, 480)
        self.setModal(True)
        self.setStyleSheet(f"QDialog {{ background:{WHITE}; }}")
        self._checks = {}
        self._build()

    def _build(self):
        root = QVBoxLayout(self)
        root.setSpacing(0); root.setContentsMargins(0, 0, 0, 0)

        # Header
        hdr = QWidget(); hdr.setFixedHeight(52)
        hdr.setStyleSheet(f"background:{NAVY};")
        hl = QHBoxLayout(hdr); hl.setContentsMargins(24, 0, 24, 0)
        t = QLabel("POS Business Rules")
        t.setStyleSheet(f"font-size:16px; font-weight:bold; color:{WHITE}; background:transparent;")
        hl.addWidget(t); hl.addStretch()
        close_x = QPushButton(); close_x.setIcon(qta.icon("fa5s.times", color="white"))
        close_x.setFixedSize(30, 30); close_x.setCursor(Qt.PointingHandCursor)
        close_x.setStyleSheet(
            f"QPushButton {{ background: {DANGER}; color: {WHITE}; border: none;"
            f" border-radius:4px; font-size:13px; font-weight:bold; }}"
            f"QPushButton:hover {{ background:{DANGER_H}; }}")
        close_x.clicked.connect(self.reject)
        hl.addWidget(close_x)
        root.addWidget(hdr)

        body = QWidget(); body.setStyleSheet(f"background:{WHITE};")
        bl = QVBoxLayout(body); bl.setSpacing(10); bl.setContentsMargins(28, 22, 28, 22)

        sec = QLabel("SALE RESTRICTIONS")
        sec.setStyleSheet(
            f"font-size:10px; font-weight:bold; color:{MUTED}; background:transparent;"
            f" letter-spacing:1px;")
        bl.addWidget(sec)

        rules = [
            ("block_zero_price",  "Block Zero-Price Sales",
             "Prevent adding items with $0.00 price to the invoice.", True),
            ("allow_negative_stock",  "Allow Negative Stock",
             "Allow selling items even when they have no stock.", True),
            ("use_pricing_rules", "Apply Pricing Rules",
             "Auto-apply discount rules when adding items.", False),
            ("require_pin_to_remove", "Require PIN for Item Removal",
             "Prompt for supervisor PIN when a cashier attempts to remove an item from the cart.", False),
            ("enable_kds_websocket", "ENABLE KITCHEN DISPLAY SYSTEM",
             "Enable live background synchronization for Kitchen Display System (KDS) screens.", False),
        ]
        for key, label, desc, default in rules:
            self._add_rule_row(bl, key, label, desc, default)

        bl.addSpacing(8)
        sep = QFrame(); sep.setFrameShape(QFrame.HLine)
        sep.setStyleSheet(f"background:{BORDER}; border:none;"); sep.setFixedHeight(1)
        bl.addWidget(sep); bl.addSpacing(8)

        note = QLabel(
            "Per-user permissions (Allow Discounts, Reprint, Credit Notes, Receipt)\n"
            "    are configured in  Maintenance -> Users -> edit a user."
        )
        note.setWordWrap(True)
        note.setStyleSheet(
            f"color:{MUTED}; font-size:11px; background:{OFF_WHITE};"
            f" border:none; border-radius:6px; padding:10px 14px;")
        bl.addWidget(note)
        
        bl.addSpacing(8)
        sep2 = QFrame(); sep2.setFrameShape(QFrame.HLine)
        sep2.setStyleSheet(f"background:{BORDER}; border:none;"); sep2.setFixedHeight(1)
        bl.addWidget(sep2); bl.addSpacing(8)

        # ---- Default Customer Dropdown ----
        c_rw = QWidget()
        c_rw.setStyleSheet(f"background:{OFF_WHITE}; border:none; border-radius:8px;")
        c_rl = QHBoxLayout(c_rw); c_rl.setContentsMargins(16, 12, 16, 12); c_rl.setSpacing(14)
        c_txt = QVBoxLayout(); c_txt.setSpacing(2)
        c_lbl = QLabel("Default Walk-in Customer")
        c_lbl.setStyleSheet(f"font-size:13px; font-weight:bold; color:{NAVY}; background:transparent;")
        c_dlbl = QLabel("Select the default customer to use instead of Cash Customer.")
        c_dlbl.setStyleSheet(f"font-size:11px; color:{MUTED}; background:transparent;")
        c_txt.addWidget(c_lbl); c_txt.addWidget(c_dlbl)
        
        self.cbo_default_cust = QComboBox()
        self.cbo_default_cust.setFixedSize(160, 32)
        self.cbo_default_cust.addItem("Cash Customer")
        
        # load customers
        saved_cust = ""
        try:
            from database.db import get_connection
            conn = get_connection(); cur = conn.cursor()
            cur.execute("SELECT setting_value FROM pos_settings WHERE setting_key='local_default_customer'")
            row = cur.fetchone()
            if row: saved_cust = str(row[0]).strip()
            
            cur.execute("SELECT customer_name FROM customers ORDER BY customer_name")
            for c_row in cur.fetchall():
                cname = str(c_row[0]).strip()
                if cname and cname.lower() != "cash customer":
                    self.cbo_default_cust.addItem(cname)
            conn.close()
        except Exception:
            pass

        if saved_cust:
            idx = self.cbo_default_cust.findText(saved_cust)
            if idx >= 0:
                self.cbo_default_cust.setCurrentIndex(idx)

        c_rl.addLayout(c_txt, 1); c_rl.addWidget(self.cbo_default_cust)
        bl.addWidget(c_rw)

        bl.addStretch()

        save_btn = navy_btn("Save Rules", height=42, color=SUCCESS, hover=SUCCESS_H)
        save_btn.setIcon(qta.icon("fa5s.save", color="white"))
        save_btn.clicked.connect(self._save)
        bl.addWidget(save_btn)

        root.addWidget(body, 1)

    def _add_rule_row(self, layout, key, label, desc, default):
        rw = QWidget()
        rw.setStyleSheet(
            f"background:{OFF_WHITE}; border:none; border-radius:8px;")
        rl = QHBoxLayout(rw); rl.setContentsMargins(16, 12, 16, 12); rl.setSpacing(14)
        txt = QVBoxLayout(); txt.setSpacing(2)
        lbl = QLabel(label)
        lbl.setStyleSheet(
            f"font-size:13px; font-weight:bold; color:{NAVY}; background:transparent;")
        dlbl = QLabel(desc)
        dlbl.setStyleSheet(f"font-size:11px; color:{MUTED}; background:transparent;")
        dlbl.setWordWrap(True)
        txt.addWidget(lbl); txt.addWidget(dlbl)
        chk = QCheckBox()
        chk.setFixedSize(44, 24)
        chk.setStyleSheet(f"""
            QCheckBox::indicator {{ width:40px; height:20px; border-radius:10px; }}
            QCheckBox::indicator:unchecked {{ background:{BORDER}; border:none; }}
            QCheckBox::indicator:checked   {{ background:{SUCCESS}; border:none; }}
        """)
        # Load saved value
        try:
            from database.db import get_connection
            conn = get_connection(); cur = conn.cursor()
            cur.execute(
                "SELECT setting_value FROM pos_settings WHERE setting_key=?", (key,))
            row = cur.fetchone(); conn.close()
            chk.setChecked(bool(int(row[0])) if row else default)
        except Exception:
            chk.setChecked(default)
        rl.addLayout(txt, 1); rl.addWidget(chk)
        self._checks[key] = chk
        layout.addWidget(rw)

    def _save(self):
        try:
            from database.db import get_connection
            conn = get_connection(); cur = conn.cursor()
            cur.execute("""
                IF NOT EXISTS (
                    SELECT 1 FROM INFORMATION_SCHEMA.TABLES
                    WHERE TABLE_NAME='pos_settings'
                )
                CREATE TABLE pos_settings (
                    setting_key   NVARCHAR(80)  NOT NULL PRIMARY KEY,
                    setting_value NVARCHAR(255) NOT NULL DEFAULT '0'
                )
            """)
            for key, chk in self._checks.items():
                val = "1" if chk.isChecked() else "0"
                cur.execute("""
                    MERGE pos_settings AS t
                    USING (SELECT ? AS k, ? AS v) AS s ON t.setting_key = s.k
                    WHEN MATCHED     THEN UPDATE SET setting_value = s.v
                    WHEN NOT MATCHED THEN INSERT (setting_key, setting_value)
                                          VALUES (s.k, s.v);
                """, (key, val))
                
            local_cust = self.cbo_default_cust.currentText().strip()
            cur.execute("""
                MERGE pos_settings AS t
                USING (SELECT 'local_default_customer' AS k, ? AS v) AS s ON t.setting_key = s.k
                WHEN MATCHED     THEN UPDATE SET setting_value = s.v
                WHEN NOT MATCHED THEN INSERT (setting_key, setting_value)
                                      VALUES (s.k, s.v);
            """, (local_cust,))
            conn.commit(); conn.close()
            QMessageBox.information(self, "Saved", "POS rules saved successfully.")
            self.accept()
        except Exception as e:
            QMessageBox.warning(self, "Error", f"Could not save rules:\n{e}")


# =============================================================================
# FRAPPE ERROR CLEANER
# =============================================================================
def _clean_frappe_error(raw: str) -> str:
    """Strip HTML tags and noise from server error messages."""
    if not raw:
        return ""
    import re as _re
    text = _re.sub(r"<[^>]+>", " ", str(raw))
    text = _re.sub(r"\\n|\\r", " ", text)
    text = _re.sub(r"\s+", " ", text).strip()
    for prefix in ("frappe.exceptions.", "ValidationError:", "LinkValidationError:",
                   "frappe.exceptions.ValidationError"):
        text = text.replace(prefix, "")
    return text.strip()[:320]


# =============================================================================
# UNSYNCED ITEMS POPUP
# Shown when user clicks SI / CN / SO badge.
# Displays only the pending rows for that document type, with error messages
# and a "Contact Admin" advisory.
# =============================================================================
# =============================================================================
# UNSYNCED ITEMS POPUP  (upgraded)
# Tabbed SI / CN / SO view.  Raw API errors shown verbatim and are copyable.
# Header shows count per tab.  Smart open: opens the right tab automatically.
# =============================================================================
class UnsyncedPopup(QDialog):
    """
    kind = "SI"  -> opens on the Sales Invoices tab
    kind = "CN"  -> opens on the Credit Notes tab
    kind = "SO"  -> opens on the Sales Orders tab
    kind = "BUNDLE" -> opens on the Bundles tab
    kind = ""    -> opens on whichever tab has errors (smart)
    """

    
    _TAB_META = {
        "SI":   ("  Sales Invoices",   DANGER,  DANGER_H),
        "CN":   ("  Credit Notes",     AMBER,   ORANGE),
        "SO":   ("  Sales Orders",     AMBER,   ORANGE),
        "PAY":  ("  Payment Entries",  ACCENT,  ACCENT_H),
        "BUNDLE": ("  Bundles",          ACCENT,  ACCENT_H),
        "CUST": ("  Customers",        NAVY_3,  NAVY_2),
    }

    def __init__(self, kind: str = "", parent=None):
        super().__init__(parent)
        self._start_kind = kind
        self.setWindowTitle("Unsynced Items")
        self.setMinimumSize(980, 580)
        self.setModal(True)
        self.setStyleSheet(f"QDialog {{ background:{OFF_WHITE}; }}")
        self._tables  = {}   # kind -> QTableWidget
        self._counts  = {}   # kind -> int
        self._build()
        self._load_all()
        self._select_smart_tab()
        
        from PySide6.QtCore import QTimer
        self._auto_refresh_timer = QTimer(self)
        self._auto_refresh_timer.timeout.connect(self._load_all)
        self._auto_refresh_timer.start(5000) # Auto-refresh every 5s

    def _get_currency_symbol(self) -> str:
        try:
            from models.company_defaults import get_defaults
            d = get_defaults() or {}
            return str(d.get("server_company_currency_symbol") or d.get("server_company_currency") or d.get("currency") or "").strip()
        except Exception:
            return ""

    # ΓöÇΓöÇ UI ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    def _build(self):
        root = QVBoxLayout(self)
        root.setSpacing(0)
        root.setContentsMargins(0, 0, 0, 0)

        # Header
        hdr = QWidget(); hdr.setFixedHeight(54)
        hdr.setStyleSheet(f"background:{NAVY};")
        hl = QHBoxLayout(hdr); hl.setContentsMargins(20, 0, 20, 0)
        t = QLabel("Unsynced Items")
        t.setStyleSheet(
            f"font-size:15px; font-weight:bold; color:{WHITE}; background:transparent;")
        self._hdr_count = QLabel("")
        self._hdr_count.setStyleSheet(
            f"color:{MID}; font-size:12px; background:transparent;")
        close_x = QPushButton("Close")
        close_x.setIcon(qta.icon("fa5s.times", color="white"))
        close_x.setFixedSize(92, 32); close_x.setCursor(Qt.PointingHandCursor)
        close_x.setStyleSheet(f"""
            QPushButton {{ background: {DANGER}; color: {WHITE}; border: none;
                           border-radius:4px;font-size:12px;font-weight:bold; }}
            QPushButton:hover {{ background:{DANGER_H}; }}
        """)
        close_x.clicked.connect(self.reject)
        hl.addWidget(t); hl.addSpacing(16); hl.addWidget(self._hdr_count)
        hl.addStretch(); hl.addWidget(close_x)
        root.addWidget(hdr)

        # Tab widget
        self._tab_widget = QTabWidget()
        self._tab_widget.setStyleSheet(f"""
            QTabWidget::pane {{ border:none; background:{OFF_WHITE}; }}
            QTabBar::tab {{
                background:{LIGHT}; color:{NAVY};
                padding:9px 22px; font-size:12px; font-weight:bold;
                border:none; border-bottom:none;
                margin-right:2px; border-radius:4px 4px 0 0;
            }}
            QTabBar::tab:selected {{
                background:{WHITE}; color:{ACCENT};
                border-bottom:2px solid {WHITE};
            }}
            QTabBar::tab:hover {{ background:{BORDER}; }}
        """)

        try:
            from services.credentials import get_system_mode
            is_saas = get_system_mode() == "saas"
        except Exception:
            is_saas = False

        for kind, (label, accent, _) in self._TAB_META.items():
            if is_saas and kind == "PAY":
                continue
            tab_widget = self._build_tab(kind, label, accent)
            self._tab_widget.addTab(tab_widget, label)

        root.addWidget(self._tab_widget, 1)

        # Admin hint
        hint = QLabel(
            "Check above for any errors and just copy and send to admin "
        )
        hint.setWordWrap(True)
        hint.setTextFormat(Qt.RichText)
        hint.setStyleSheet(f"""
            background:{LIGHT}; color:{DARK_TEXT};
            border:none; border-left:4px solid {DANGER};
            font-size:11px; padding:10px 16px;
        """)
        root.addWidget(hint)

    def _build_tab(self, kind: str, label: str, accent: str) -> QWidget:
        w = QWidget(); w.setStyleSheet(f"background:{OFF_WHITE};")
        bl = QVBoxLayout(w); bl.setContentsMargins(16, 12, 16, 10); bl.setSpacing(8)

        # Count label
        count_lbl = QLabel("Loading...")
        count_lbl.setStyleSheet(
            f"color:{MUTED}; font-size:11px; background:transparent;")
        setattr(self, f"_count_lbl_{kind}", count_lbl)
        bl.addWidget(count_lbl)

        # Table - 4 columns: Q: Ref | Customer | Amount | Raw Error
        tbl = QTableWidget(0, 4)
        tbl.setHorizontalHeaderLabels(["Q: Ref / No.", "Customer", "Amount", "Raw API Error"])
        hh = tbl.horizontalHeader()
        hh.setSectionResizeMode(0, QHeaderView.Fixed);  tbl.setColumnWidth(0, 150)
        hh.setSectionResizeMode(1, QHeaderView.Fixed);  tbl.setColumnWidth(1, 160)
        hh.setSectionResizeMode(2, QHeaderView.Fixed);  tbl.setColumnWidth(2, 90)
        hh.setSectionResizeMode(3, QHeaderView.Stretch)
        tbl.verticalHeader().setVisible(False)
        tbl.setEditTriggers(QAbstractItemView.NoEditTriggers)
        tbl.setSelectionBehavior(QAbstractItemView.SelectRows)
        tbl.setAlternatingRowColors(True)
        tbl.setStyleSheet(f"""
            QTableWidget {{
                background:{WHITE}; border:none;
                gridline-color:{LIGHT}; font-size:12px; outline:none;
            }}
            QTableWidget::item           {{ padding:6px 10px; }}
            QTableWidget::item:alternate {{ background:{ROW_ALT}; }}
            QHeaderView::section {{
                background:#f0e8d0; color:{NAVY};
                padding:8px 10px; border:none;
                border-right:1px solid {BORDER};
                font-size:11px; font-weight:bold;
            }}
        """)
        # Allow text selection so errors can be copied
        tbl.setTextElideMode(Qt.ElideNone)
        self._tables[kind] = tbl
        bl.addWidget(tbl, 1)

        # Copy button + retry button
        foot = QHBoxLayout(); foot.setSpacing(10)

        copy_btn = QPushButton("Copy Selected Error")
        copy_btn.setIcon(qta.icon("fa5s.clipboard", color="white"))
        copy_btn.setFixedHeight(34); copy_btn.setCursor(Qt.PointingHandCursor)
        copy_btn.setStyleSheet(f"""
            QPushButton {{ background:{NAVY_2};color:{WHITE};border:none;
                           border-radius:5px;font-size:12px;font-weight:bold; }}
            QPushButton:hover {{ background:{NAVY_3}; }}
        """)
        copy_btn.clicked.connect(lambda _=False, k=kind: self._copy_error(k))

        refresh_btn = QPushButton("Refresh")
        refresh_btn.setIcon(qta.icon("fa5s.sync-alt", color="white"))
        refresh_btn.setFixedHeight(34); refresh_btn.setCursor(Qt.PointingHandCursor)
        refresh_btn.setStyleSheet(f"""
            QPushButton {{ background:{NAVY_2};color:{WHITE};border:none;
                           border-radius:5px;font-size:12px;font-weight:bold; }}
            QPushButton:hover {{ background:{NAVY_3}; }}
        """)
        refresh_btn.clicked.connect(lambda _=False, k=kind: self._load_tab(k))

        retry_btn = QPushButton("Retry Sync Now")
        retry_btn.setIcon(qta.icon("fa5s.sync-alt", color="white"))
        retry_btn.setFixedHeight(34); retry_btn.setCursor(Qt.PointingHandCursor)
        retry_btn.setStyleSheet(f"""
            QPushButton {{ background:{ACCENT};color:{WHITE};border:none;
                           border-radius:5px;font-size:12px;font-weight:bold; }}
            QPushButton:hover {{ background:{ACCENT_H}; }}
            QPushButton:disabled {{ background:{LIGHT};color:{MUTED}; }}
        """)
        retry_btn.clicked.connect(lambda _=False, k=kind, b=retry_btn: self._on_retry(k, b))

        wipe_btn = QPushButton("Wipe Errors")
        wipe_btn.setIcon(qta.icon("fa5s.trash", color="white"))
        wipe_btn.setFixedHeight(34); wipe_btn.setCursor(Qt.PointingHandCursor)
        wipe_btn.setStyleSheet(f"""
            QPushButton {{ background:{DANGER};color:{WHITE};border:none;
                           border-radius:5px;font-size:12px;font-weight:bold; }}
            QPushButton:hover {{ background:{DANGER_H}; }}
        """)
        wipe_btn.clicked.connect(lambda _=False, k=kind: self._on_wipe_errors())

        foot.addWidget(copy_btn)
        foot.addWidget(refresh_btn)
        foot.addWidget(wipe_btn)
        foot.addStretch()
        foot.addWidget(retry_btn)
        bl.addLayout(foot)
        return w

    # ΓöÇΓöÇ Data ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    def _load_all(self):
        try:
            from services.credentials import get_system_mode
            is_saas = get_system_mode() == "saas"
        except Exception:
            is_saas = False

        total = 0
        for kind in self._TAB_META:
            if is_saas and kind == "PAY":
                continue
            if kind not in self._tables: continue
            n = self._load_tab(kind)
            self._counts[kind] = n
            total += n
        self._hdr_count.setText(
            f"{total} item{'s' if total != 1 else ''} pending sync across all types")
        # Update tab labels with counts
        tab_idx = 0
        for kind in self._TAB_META:
            if is_saas and kind == "PAY":
                continue
            label, _, _ = self._TAB_META[kind]
            n = self._counts.get(kind, 0)
            suffix = f"  ({n})" if n > 0 else ""
            self._tab_widget.setTabText(tab_idx, label + suffix)
            tab_idx += 1

    def _load_tab(self, kind: str) -> int:
        """Load rows for one tab. Returns row count."""
        if kind not in self._tables: return 0
        tbl = self._tables[kind]
        tbl.setRowCount(0)
        rows = self._fetch_rows(kind)
        n = len(rows)

        lbl = getattr(self, f"_count_lbl_{kind}", None)
        if lbl:
            lbl.setText(f"{n} item{'s' if n != 1 else ''} pending sync")

        for ref, customer, amount, raw_error in rows:
            r = tbl.rowCount()
            tbl.insertRow(r)
            tbl.setRowHeight(r, 42)

            def _cell(text, color=None, align=Qt.AlignLeft | Qt.AlignVCenter):
                it = QTableWidgetItem(str(text or ""))
                # Make selectable so user can Ctrl+C
                it.setFlags(it.flags() | Qt.ItemIsSelectable | Qt.ItemIsEnabled)
                it.setFlags(it.flags() & ~Qt.ItemIsEditable)
                it.setTextAlignment(align)
                if color:
                    it.setForeground(QColor(color))
                return it

            tbl.setItem(r, 0, _cell(ref, ACCENT))
            tbl.setItem(r, 1, _cell(customer))
            tbl.setItem(r, 2, _cell(amount, align=Qt.AlignRight | Qt.AlignVCenter))
            # Raw error - red, full text in tooltip too
            err_item = _cell(raw_error or "-", DANGER if raw_error else MUTED)
            if raw_error:
                err_item.setToolTip(str(raw_error))   # full text on hover
            tbl.setItem(r, 3, err_item)

        return n

    def _fetch_rows(self, kind: str):
        """
        Returns list of (ref, customer, amount_str, raw_error_str).
        Every query mirrors the badge SQL so popup count == badge count.
        Raw error_msg is pulled verbatim from sync_errors table - no cleaning,
        no truncation.  Falls back to "Pending" only when no error row exists.
        """
        rows = []
        try:
            from database.db import get_connection

            def _get_raw_errors(conn, doc_type_code: str) -> dict:
                """
                Returns {doc_ref: error_msg} for all unresolved rows of
                this doc_type.  Verbatim - newest row wins per ref.
                """
                errors = {}
                try:
                    cur2 = conn.cursor()
                    cur2.execute(
                        """
                        SELECT doc_ref, error_msg
                        FROM   sync_errors
                        WHERE  doc_type = ?
                          AND  resolved = 0
                        ORDER  BY id DESC
                        """,
                        (doc_type_code,),
                    )
                    for doc_ref, error_msg in cur2.fetchall():
                        if doc_ref not in errors:
                            errors[doc_ref] = error_msg or ""
                except Exception:
                    pass
                return errors

            def _match_error(error_map: dict, key: str) -> str:
                """Exact match first, then substring fallback."""
                if not key:
                    return ""
                if key in error_map:
                    return str(error_map[key])
                key_str = str(key).lower()
                for k, v in error_map.items():
                    if k is not None:
                        k_str = str(k).lower()
                        if k_str in key_str or key_str in k_str:
                            return str(v)
                return ""

            if kind == "SI":
                try:
                    conn = get_connection()
                    # collect errors under both code variants services may use
                    error_map = _get_raw_errors(conn, "SI")
                    for k, v in _get_raw_errors(conn, "sales_invoice").items():
                        error_map.setdefault(k, v)
                    cur = conn.cursor()
                    cur.execute("""
                        SELECT invoice_no, customer_name, total, method
                        FROM   sales
                        WHERE  synced = 0 OR synced IS NULL
                        ORDER  BY id DESC
                    """)
                    for inv, cust, amt, meth in cur.fetchall():
                        inv_key = inv or ""
                        raw_err = _match_error(error_map, inv_key)
                        display_err = (
                            raw_err if raw_err
                            else f"Pending - not yet attempted  (method: {meth or 'unknown'})"
                        )
                        rows.append((
                            inv_key or "-",
                            cust or "Walk-in",
                            f"{self._get_currency_symbol()}{float(amt or 0):.2f}",
                            display_err,
                        ))
                    conn.close()
                except Exception as e:
                    rows.append(("-", "-", "-", f"DB error: {e}"))

            elif kind == "CN":
                try:
                    conn = get_connection()
                    error_map = _get_raw_errors(conn, "CN")
                    for k, v in _get_raw_errors(conn, "credit_note").items():
                        error_map.setdefault(k, v)
                    cur = conn.cursor()
                    cur.execute("""
                        SELECT cn_number, customer_name, total, cn_status
                        FROM   credit_notes
                        WHERE  cn_status IN ('ready','pending_sync')
                        ORDER  BY id DESC
                    """)
                    for cn_no, cust, amt, status in cur.fetchall():
                        cn_key = cn_no or ""
                        raw_err = _match_error(error_map, cn_key)
                        display_err = (
                            raw_err if raw_err
                            else f"Pending - status: {status or 'ready'}"
                        )
                        rows.append((
                            cn_key or "-",
                            cust or "-",
                            f"{self._get_currency_symbol()}{float(amt or 0):.2f}",
                            display_err,
                        ))
                    conn.close()
                except Exception as e:
                    rows.append(("-", "-", "-", f"DB error: {e}"))
            
            elif kind == "SO":
                try:
                    conn = get_connection()
                    error_map = _get_raw_errors(conn, "SO")
                    for k, v in _get_raw_errors(conn, "sales_order").items():
                        error_map.setdefault(k, v)
                    cur = conn.cursor()
                    cur.execute("""
                        SELECT order_no, customer_name, total
                        FROM   sales_order
                        WHERE  synced = 0 OR synced IS NULL
                        ORDER  BY id DESC
                    """)
                    for ono, cust, amt in cur.fetchall():
                        so_key = ono or ""
                        raw_err = _match_error(error_map, so_key)
                        display_err = (
                            raw_err if raw_err
                            else "Pending - not yet attempted"
                        )
                        rows.append((
                            so_key or "-",
                            cust or "-",
                            f"{self._get_currency_symbol()}{float(amt or 0):.2f}",
                            display_err,
                        ))
                    conn.close()
                except Exception as e:
                    rows.append(("-", "-", "-", f"DB error: {e}"))

            elif kind == "PAY":
                try:
                    conn = get_connection()
                    error_map = _get_raw_errors(conn, "PAY")
                    for k, v in _get_raw_errors(conn, "PE").items():
                        error_map.setdefault(k, v)
                    for k, v in _get_raw_errors(conn, "payment_entry").items():
                        error_map.setdefault(k, v)
                    
                    cur = conn.cursor()
                    # Show ALL unsynced payment entries - including sale-linked ones.
                    # Currency column included so ZiG/ZWD entries are clearly labelled.
                    cur.execute("""
                        SELECT reference_no, party_name, paid_amount, currency, last_error, sync_attempts FROM (
                            SELECT pe.reference_no, pe.party_name, pe.paid_amount,
                                   pe.currency, ISNULL(pe.sync_error, pe.last_error) as last_error, pe.sync_attempts, pe.id
                            FROM   payment_entries pe
                            WHERE  (pe.synced = 0 OR pe.synced IS NULL)
                            
                            UNION ALL
                            
                            SELECT le.order_no as reference_no, le.customer_name as party_name, le.deposit_amount as paid_amount,
                                   le.deposit_currency as currency, ISNULL(le.sync_error, le.error_message) as last_error, le.sync_attempts, le.id
                            FROM   laybye_payment_entries le
                            WHERE  le.status != 'synced'

                            UNION ALL

                            SELECT cp.reference as reference_no, c.customer_name as party_name, cp.amount as paid_amount,
                                   cp.currency, cp.sync_error as last_error, cp.sync_attempts, cp.id
                            FROM   customer_payments cp
                            LEFT JOIN customers c ON cp.customer_id = c.id
                            WHERE  (cp.synced = 0 OR cp.synced IS NULL)
                        ) as combined
                        ORDER BY id DESC
                    """)
                    for ref, cust, amt, curr, db_err, attempts in cur.fetchall():
                        pay_key = ref or ""
                        raw_err = (db_err or "").strip() or _match_error(error_map, pay_key)
                        att = attempts or 0
                        if att >= 60:
                            attempt_str = f" (Max retries reached - click Retry to reset)"
                        elif att > 0:
                            attempt_str = f" (Attempt {att}/60)"
                        else:
                            attempt_str = ""
                        display_err = (
                            f"{raw_err}{attempt_str}" if raw_err
                            else "Pending - not yet attempted"
                        )
                        curr_display = (curr or "USD").upper()
                        rows.append((
                            pay_key or "-",
                            cust or "Walk-in",
                            f"{curr_display}  {float(amt or 0):,.2f}",
                            display_err,
                        ))
                    conn.close()
                except Exception as e:
                    rows.append(("-", "-", "-", f"DB error: {e}"))

            elif kind == "CUST":
                try:
                    conn = get_connection()
                    error_map = _get_raw_errors(conn, "CUST")
                    for k, v in _get_raw_errors(conn, "customer").items():
                        error_map.setdefault(k, v)
                    cur = conn.cursor()
                    cur.execute("""
                        SELECT id, customer_name, custom_telephone_number
                        FROM   customers
                        WHERE  frappe_synced = 0 OR frappe_synced IS NULL
                        ORDER  BY id DESC
                    """)
                    for cid, cname, phone in cur.fetchall():
                        cust_key = f"CUST-{cid}"
                        raw_err = (
                            _match_error(error_map, cust_key)
                            or _match_error(error_map, str(cid))
                            or (_match_error(error_map, cname) if cname else "")
                        )
                        display_err = (
                            raw_err if raw_err
                            else "Not yet synced to server"
                        )
                        rows.append((
                            cust_key,
                            cname or "-",
                            phone or "-",
                            display_err,
                        ))
                    conn.close()
                except Exception as e:
                    rows.append(("-", "-", "-", f"DB error: {e}"))

            elif kind == "BUNDLE":
                try:
                    conn = get_connection()
                    error_map = _get_raw_errors(conn, "BUNDLE")
                    for k, v in _get_raw_errors(conn, "bundle").items():
                        error_map.setdefault(k, v)
                    cur = conn.cursor()
                    cur.execute("""
                        SELECT id, name, description
                        FROM   product_bundles
                        WHERE  sync_status = 'pending' OR sync_status = 'failed'
                        ORDER  BY id DESC
                    """)
                    for bid, bname, bdesc in cur.fetchall():
                        bundle_key = bname or str(bid)
                        raw_err = _match_error(error_map, bundle_key)
                        display_err = (
                            raw_err if raw_err
                            else "Pending push to server"
                        )
                        rows.append((
                            f"BNDL-{bid}",
                            bname or "-",
                            "Bundle",
                            display_err,
                        ))
                    conn.close()
                except Exception as e:
                    rows.append(("-", "-", "-", f"DB error: {e}"))

        except Exception:
            pass

        return rows

    # ΓöÇΓöÇ Smart tab selection ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    def _select_smart_tab(self):
        kinds = list(self._TAB_META.keys())   # ["SI","CN","SO"]

        # If caller specified a kind, use it
        if self._start_kind in kinds:
            self._tab_widget.setCurrentIndex(kinds.index(self._start_kind))
            return

        # Auto: pick first tab that has errors
        for i, kind in enumerate(kinds):
            if self._counts.get(kind, 0) > 0:
                self._tab_widget.setCurrentIndex(i)
                return

    # ΓöÇΓöÇ Copy error ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    def _copy_error(self, kind: str):
        if kind not in self._tables: return 0
        tbl = self._tables[kind]
        rows = tbl.selectedItems()
        if not rows:
            # copy all errors for this tab
            lines = []
            for r in range(tbl.rowCount()):
                ref   = (tbl.item(r, 0) or QTableWidgetItem("")).text()
                cust  = (tbl.item(r, 1) or QTableWidgetItem("")).text()
                amt   = (tbl.item(r, 2) or QTableWidgetItem("")).text()
                err   = (tbl.item(r, 3) or QTableWidgetItem("")).text()
                lines.append(f"{ref} | {cust} | {amt} | {err}")
            text = "\n".join(lines) if lines else ""
        else:
            # copy error column of selected row(s)
            seen = set()
            parts = []
            for it in rows:
                r = it.row()
                if r in seen:
                    continue
                seen.add(r)
                ref  = (tbl.item(r, 0) or QTableWidgetItem("")).text()
                cust = (tbl.item(r, 1) or QTableWidgetItem("")).text()
                amt  = (tbl.item(r, 2) or QTableWidgetItem("")).text()
                err  = (tbl.item(r, 3) or QTableWidgetItem("")).text()
                parts.append(f"{ref} | {cust} | {amt}\n{err}")
            text = "\n\n".join(parts)

        if text:
            QApplication.clipboard().setText(text)
            # Show confirmation tooltip so cashier knows copy worked
            try:
                from PySide6.QtWidgets import QToolTip
                from PySide6.QtGui import QCursor
                tbl = self._tables.get(kind)
                if tbl:
                    QToolTip.showText(QCursor.pos(), "Copied to clipboard!", tbl, tbl.rect(), 2000)
            except Exception:
                pass
    def _on_wipe_errors(self):
        confirm = QMessageBox.question(
            self,
            "Wipe All Errors?",
            "Are you sure you want to permanently clear all recorded sync errors? "
            "This will clear the logs, but the system may still try to sync them if they remain unsynced.",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No
        )
        if confirm == QMessageBox.Yes:
            try:
                from services.sync_errors_service import clear_all_errors
                clear_all_errors()
                
                # Also reset all active sync_error columns and syncing locks in the database
                # This breaks the infinite loop if the system was stuck retrying
                from database.db import get_connection
                conn = get_connection()
                conn.cursor().execute("UPDATE sales SET sync_error = NULL")
                conn.cursor().execute("UPDATE sales_order SET sync_error = NULL")
                conn.cursor().execute("UPDATE credit_notes SET sync_error = NULL")
                conn.cursor().execute("UPDATE payment_entries SET sync_error = NULL, last_error = NULL")
                conn.cursor().execute("UPDATE laybye_payment_entries SET error_message = ''")
                conn.cursor().execute("UPDATE customer_payments SET sync_error = NULL")
                conn.commit()
                conn.close()
                
                self._load_all()
            except Exception as e:
                QMessageBox.warning(self, "Error", f"Could not wipe errors: {e}")

    # ΓöÇΓöÇ Retry ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    def _on_retry(self, kind: str, btn: QPushButton):
        btn.setEnabled(False)
        btn.setText("Retrying...")
        import threading

        def _do():
            try:
                from database.db import get_connection
                conn = get_connection()

                # ΓöÇΓöÇ STEP 1: Release all stale locks for this kind ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
                try:
                    if kind == "PAY":
                        conn = get_connection()
                        conn.cursor().execute("""
                            UPDATE laybye_payment_entries
                            SET status = 'retry'
                            WHERE status = 'syncing' OR status = 'failed'
                        """)
                        conn.commit(); conn.close()
                        conn = get_connection()
                        conn.cursor().execute("""
                            UPDATE payment_entries
                            SET synced = 0, syncing = 0
                            WHERE (synced = 0 OR synced IS NULL) AND syncing = 1
                        """)
                        conn.commit(); conn.close()
                        conn = get_connection()
                        conn.cursor().execute("""
                            UPDATE customer_payments
                            SET syncing = 0, sync_attempts = 0
                            WHERE (synced = 0 OR synced IS NULL) AND syncing = 1
                        """)
                        conn.commit(); conn.close()
                        conn = get_connection()
                        conn.cursor().execute("UPDATE sync_errors SET resolved = 1 WHERE doc_type IN ('PE', 'PAY')")
                        conn.commit(); conn.close()
                    elif kind == "SI":
                        conn = get_connection()
                        conn.cursor().execute("UPDATE sales SET syncing = 0 WHERE syncing = 1 AND synced = 0")
                        conn.commit(); conn.close()
                        conn = get_connection()
                        conn.cursor().execute("UPDATE sales SET sync_error = NULL WHERE synced = 0")
                        conn.commit(); conn.close()
                        conn = get_connection()
                        conn.cursor().execute("UPDATE sync_errors SET resolved = 1 WHERE doc_type IN ('SI', 'sales_invoice')")
                        conn.commit(); conn.close()
                        conn = get_connection()
                        cur = conn.cursor()
                        cur.execute("SELECT COUNT(*) FROM sales WHERE synced = 0 AND (syncing IS NULL OR syncing = 0)")
                        unlocked_count = cur.fetchone()[0]
                        conn.close()
                        print(f"[retry] SI locks reset. Ready to push: {unlocked_count} sale(s)")
                    elif kind == "CN":
                        conn = get_connection()
                        conn.cursor().execute("UPDATE credit_notes SET syncing = 0 WHERE syncing = 1")
                        conn.commit(); conn.close()
                        conn = get_connection()
                        conn.cursor().execute("UPDATE sync_errors SET resolved = 1 WHERE doc_type IN ('CN', 'credit_note')")
                        conn.commit(); conn.close()
                    elif kind == "SO":
                        conn = get_connection()
                        conn.cursor().execute("UPDATE sales_order SET synced = 0 WHERE synced = 2")
                        conn.commit(); conn.close()
                        conn = get_connection()
                        conn.cursor().execute("UPDATE sync_errors SET resolved = 1 WHERE doc_type IN ('SO', 'sales_order')")
                        conn.commit(); conn.close()
                    elif kind == "BUNDLE":
                        conn = get_connection()
                        conn.cursor().execute("UPDATE product_bundles SET sync_status = 'pending' WHERE sync_status = 'failed'")
                        conn.commit(); conn.close()
                        conn = get_connection()
                        conn.cursor().execute("UPDATE sync_errors SET resolved = 1 WHERE doc_type = 'BUNDLE'")
                        conn.commit(); conn.close()
                    elif kind == "CUST":
                        conn = get_connection()
                        conn.cursor().execute("UPDATE sync_errors SET resolved = 1 WHERE doc_type = 'CUST'")
                        conn.commit(); conn.close()
                except Exception as lock_e:
                    print(f"[retry] Lock reset error for {kind}: {lock_e}")
                    import traceback; traceback.print_exc()

                # ΓöÇΓöÇ STEP 1.5: Refresh UI immediately so user sees errors clear ΓöÇΓöÇ
                from PySide6.QtCore import QMetaObject, Qt as _Qt2
                QMetaObject.invokeMethod(self, "_load_all", _Qt2.QueuedConnection)

                import time
                time.sleep(0.5)

                # STEP 2: Trigger the sync service
                print(f"[retry] Starting upload for kind={kind}...")
                if kind == "SI":
                    try:
                        from services.pos_upload_service import push_unsynced_sales
                        result = push_unsynced_sales()
                        print(f"[retry] SI done: pushed={result.get('pushed',0)} failed={result.get('failed',0)} total={result.get('total',0)}")
                    except Exception as _si_e:
                        print(f"[retry] SI push error: {_si_e}")
                        import traceback; traceback.print_exc()
                elif kind == "CN":
                    from services.credit_note_sync_service import push_unsynced_credit_notes
                    push_unsynced_credit_notes(force=True)
                elif kind == "SO":
                    from services.sales_order_upload_service import push_unsynced_orders
                    push_unsynced_orders()
                elif kind == "PAY":
                    try:
                        from services.payment_entry_sync_service import push_unsynced_payment_entries
                        push_unsynced_payment_entries()
                    except Exception as e:
                        print(f"[retry] standard PE sync error: {e}")
                    try:
                        from services.laybye_payment_entry_service import sync_laybye_payment_entries
                        sync_laybye_payment_entries(force=True)
                    except Exception as e:
                        print(f"[retry] laybye PE sync error: {e}")
                elif kind == "CUST":
                    from services.credentials import get_all_credentials
                    if get_all_credentials().get("system_mode") == "odoo":
                        from services.odoo.sync_service import sync_customers_odoo
                        sync_customers_odoo()
                    else:
                        from services.customer_sync_service import sync_customers
                        sync_customers()
                        from models.customer import retry_unsynced_customers
                        retry_unsynced_customers()
                elif kind == "BUNDLE":
                    from services.bundle_sync_service import sync_pending_bundles
                    sync_pending_bundles()
            except Exception as e:
                print(f"[retry] _on_retry error for kind={kind}: {e}")

            from PySide6.QtCore import QMetaObject, Qt as _Qt2
            QMetaObject.invokeMethod(self, "_after_retry", _Qt2.QueuedConnection)

        threading.Thread(target=_do, daemon=True).start()

    @Slot()
    def _after_retry(self):
        # Re-enable all retry buttons and reload
        self._load_all()
        # Re-enable buttons (find them)
        for i in range(self._tab_widget.count()):
            tab = self._tab_widget.widget(i)
            if tab:
                for child in tab.findChildren(QPushButton):
                    if "Retry" in child.text() or "Retrying" in child.text():
                        child.setEnabled(True)
                        child.setText("Retry Sync Now")
                        child.setIcon(qta.icon("fa5s.sync-alt", color="white"))
from PySide6.QtCore import QObject as _QObject, Signal as _Signal
import threading

class _BadgeWorker(_QObject):
    done = _Signal(int, int, int, int, int, int, int)   # si, cn, so, pay, cust, bundle, fiscal

    def start(self):
        t = threading.Thread(target=self.run, daemon=True)
        t.start()

    def run(self):
        si = cn = so = pay = cust = bundle = fiscal = 0
        try:
            from database.db import get_connection
            conn = get_connection()
            cur = conn.cursor()

            # SI - unsynced sales invoices
            try:
                cur.execute(
                    "SELECT COUNT(*) FROM sales "
                    "WHERE synced = 0 OR synced IS NULL"
                )
                si = int(cur.fetchone()[0] or 0)
                
                # FISCAL - pending/failed fiscalization (for Z badge)
                cur.execute(
                    "SELECT COUNT(*) FROM sales "
                    "WHERE fiscal_status IN ('pending', 'failed')"
                )
                fiscal = int(cur.fetchone()[0] or 0)
            except Exception: pass

            # CN - Credit Notes
            try:
                cur.execute(
                    "SELECT COUNT(*) FROM credit_notes "
                    "WHERE cn_status IN ('ready', 'pending_sync')"
                )
                cn = int(cur.fetchone()[0] or 0)
            except Exception: pass

            # SO - Sales Orders / Laybyes
            try:
                cur.execute(
                    "SELECT COUNT(*) FROM sales_order "
                    "WHERE synced = 0 OR synced IS NULL"
                )
                so = int(cur.fetchone()[0] or 0)
            except Exception: pass

            try:
                cur.execute("""
                        SELECT SUM(c) FROM (
                            SELECT COUNT(*) as c FROM payment_entries pe 
                            WHERE (pe.synced = 0 OR pe.synced IS NULL)
                            UNION ALL
                            SELECT COUNT(*) as c FROM laybye_payment_entries le
                            WHERE le.status != 'synced'
                            UNION ALL
                            SELECT COUNT(*) as c FROM customer_payments cp
                            WHERE (cp.synced = 0 OR cp.synced IS NULL)
                        ) as combined
                """)
                pay = int(cur.fetchone()[0] or 0)
            except Exception: pass

            # CUST - locally-created customers not yet pushed
            try:
                cur.execute(
                    "SELECT COUNT(*) FROM customers "
                    "WHERE frappe_synced = 0 OR frappe_synced IS NULL"
                )
                cust = int(cur.fetchone()[0] or 0)
            except Exception: pass

            # BUNDLE - pending/failed bundles
            try:
                cur.execute(
                    "SELECT COUNT(*) FROM products "
                    "WHERE is_product_bundle = 1 AND sync_status IN ('pending', 'failed')"
                )
                bundle = int(cur.fetchone()[0] or 0)
            except Exception: pass

            conn.close()
        except Exception:
            pass

        self.done.emit(si, cn, so, pay, cust, bundle, fiscal)
class POSView(QWidget):
    MAX_ROWS = 999   # safety ceiling - table grows elastically
    INVOICE_COL_COUNT = 10
    COL_QTY     = 0
    COL_PART_NO = 1
    COL_NAME    = 2
    COL_PRICE   = 3
    COL_DISC    = 4
    COL_TAX     = 5
    COL_TOTAL   = 6
    COL_UOM     = 7
    COL_NOTES   = 8
    COL_PHARM   = 9

    PHARMACY_META_ROLE = 256

    def _ensure_rows(self, needed: int):
        """Grow the table in blocks of 20 so there are at least `needed` rows."""
        current = self.invoice_table.rowCount()
        if needed <= current:
            return
        new_count = min(self.MAX_ROWS, ((needed + 19) // 20) * 20)
        self.invoice_table.setRowCount(new_count)
        for r in range(current, new_count):
            self.invoice_table.setRowHeight(r, 20)
            self._init_row(r)
    def _do_nav_axis_fiscal(self):
        try:
            from views.dialogs.axis_fiscal_dialog import AxisFiscalDialog
            AxisFiscalDialog(self).exec()
        except Exception as e:
            print(f"[MainWindow] Axis dialog launch failed: {e}")

    def _do_nav_revmax_fiscal(self):
        try:
            from views.dialogs.revmax_fiscal_dialog import RevmaxFiscalDialog
            RevmaxFiscalDialog(self).exec()
        except Exception as e:
            print(f"[MainWindow] Revmax dialog launch failed: {e}")

    def _do_nav_sync_products(self):
        from PySide6.QtWidgets import QDialog, QHBoxLayout, QLabel, QPushButton
        from PySide6.QtCore import Qt, QThread, Signal, QObject
        import qtawesome as qta
        
        self._sync_dlg = QDialog(self)
        self._sync_dlg.setWindowFlags(Qt.FramelessWindowHint | Qt.Tool | Qt.WindowStaysOnTopHint)
        self._sync_dlg.setAttribute(Qt.WA_DeleteOnClose)
        self._sync_dlg.setFixedSize(220, 60)
        self._sync_dlg.setStyleSheet(f"QDialog {{ background: {WHITE}; border: 2px solid {ACCENT}; border-radius: 8px; }} QLabel {{ font-weight: bold; color: {NAVY}; font-size: 13px; }}")
        
        lay = QHBoxLayout(self._sync_dlg)
        lay.setContentsMargins(15, 5, 10, 5)
        
        from PySide6.QtWidgets import QProgressBar
        lbl = QLabel("Syncing...")
        lbl.setAlignment(Qt.AlignCenter)
        lay.addWidget(lbl)
        
        pbar = QProgressBar()
        pbar.setRange(0, 0)
        pbar.setFixedHeight(12)
        pbar.setTextVisible(False)
        lay.addWidget(pbar, 1)
        
        close_btn = QPushButton()
        close_btn.setIcon(qta.icon("fa5s.times", color=MUTED))
        close_btn.setFixedSize(24, 24)
        close_btn.setStyleSheet("border: none; background: transparent;")
        close_btn.setCursor(Qt.PointingHandCursor)
        close_btn.clicked.connect(self._sync_dlg.close)
        lay.addWidget(close_btn)

        # Calculate position to be centered on the main window
        if self.parentWidget():
            parent_rect = self.parentWidget().geometry()
            self._sync_dlg.move(parent_rect.center() - self._sync_dlg.rect().center())

        class _ProductSyncJob(QObject):
            done   = Signal(dict)
            failed = Signal(str)
            def run(self):
                try:
                    from services.credentials import get_system_mode
                    _mode = get_system_mode()
                    if _mode == "odoo":
                        from services.odoo.sync_service import sync_products_odoo
                        res = sync_products_odoo() or {}
                        self.done.emit({"inserted": res.get("products_synced", 0), "updated": 0, "total_api": res.get("products_synced", 0), "errors": 0})
                    else:
                        from services.credentials import get_credentials, has_credentials
                        if not has_credentials():
                            self.failed.emit("No credentials.")
                            return
                        key, secret = get_credentials()
                        from services.sync_all import sync_everything
                        res = sync_everything() or {}
                        self.done.emit(res)
                except Exception as e:
                    self.failed.emit(str(e))

        self._sync_thread = QThread(self)
        self._sync_job    = _ProductSyncJob()
        self._sync_job.moveToThread(self._sync_thread)
        self._sync_thread.started.connect(self._sync_job.run)
        
        class _SyncHandler(QObject):
            def __init__(self, pos_view, dialog):
                super().__init__(pos_view)
                self.pos = pos_view
                self.dlg = dialog
            def on_done(self, res):
                try:
                    self.pos._reload_current_category()
                except Exception: pass
                try:
                    self.dlg.close()
                except RuntimeError:
                    pass
                pw = getattr(self.pos, "parent_window", None)
                if pw and hasattr(pw, "_set_status"):
                    pw._set_status(f"Sync done - {res.get('inserted',0)} new, {res.get('updated',0)} updated.")
            def on_fail(self, msg):
                try:
                    self.dlg.close()
                except RuntimeError:
                    pass
                pw = getattr(self.pos, "parent_window", None)
                if pw and hasattr(pw, "_set_status"):
                    pw._set_status(f"Sync failed: {msg}")

        self._sync_handler = _SyncHandler(self, self._sync_dlg)
        self._sync_job.done.connect(self._sync_handler.on_done)
        self._sync_job.failed.connect(self._sync_handler.on_fail)
        self._sync_job.done.connect(self._sync_thread.quit)
        self._sync_job.failed.connect(self._sync_thread.quit)
        self._sync_thread.finished.connect(self._sync_job.deleteLater)
        self._sync_thread.finished.connect(self._sync_thread.deleteLater)
        self._sync_thread.finished.connect(self._sync_handler.deleteLater)
        
        self._sync_dlg.show()
        self._sync_thread.start()

    def _on_orders(self):
        if self.orders_btn.isChecked():
            if self.parent_window:
                self.parent_window.switch_to_orders()
        else:
            self._clear_restaurant_mode()

    def _set_view_only_mode(self, enabled: bool):
        """Disable or enable payment and editing buttons based on cashier permissions."""
        if hasattr(self, 'pay_btn'):
            self.pay_btn.setEnabled(not enabled)
            self.pay_btn.setToolTip("View-Only Mode: You do not have permission to close this order." if enabled else "")
        
        # Disable editing triggers on the table if view-only
        if hasattr(self, 'invoice_table'):
            if enabled:
                self.invoice_table.setEditTriggers(QAbstractItemView.NoEditTriggers)
            else:
                self.invoice_table.setEditTriggers(QAbstractItemView.DoubleClicked | QAbstractItemView.AnyKeyPressed | QAbstractItemView.EditKeyPressed)

    def link_to_table(self, table_data: dict, append_mode: bool = False, order_id: int = None, force_new: bool = False, edit_mode: bool = False):
        """
        Link the current cart to a restaurant table.
        - If force_new is True: Don't load any previous orders. Start empty.
        - If order_id is provided: Load that specific order (Edit KOT / Pay KOT).
        - If self._pay_all_mode is True: Load ALL orders for that table combined.
        - Otherwise: Load the most recent active order (Standard ADD/APPEND).
        """
        from database.db import get_connection
        from models.restaurant_order import get_order_by_table, get_order_items, get_orders_for_table
        
        # 1. Fetch OrderPower permissions
        view_others = True
        close_others = True
        try:
            conn = get_connection(); cur = conn.cursor()
            cur.execute("SELECT setting_key, setting_value FROM pos_settings WHERE setting_key IN ('allow_others_to_view_orders', 'allow_others_to_close_orders')")
            for k, v in cur.fetchall():
                if k == 'allow_others_to_view_orders': view_others = (str(v) == "1")
                if k == 'allow_others_to_close_orders': close_others = (str(v) == "1")
            conn.close()
        except Exception: pass

        order = None
        is_combined = getattr(self, "_pay_all_mode", False)

        # 2. Resolve WHICH Order(s) to load
        if force_new:
            order = None
        elif order_id:
            try:
                from database.db import fetchone_dict
                _conn = get_connection(); _cur = _conn.cursor()
                _cur.execute("SELECT o.*, t.name as table_name, t.table_number FROM restaurant_orders o JOIN restaurant_tables t ON o.table_id = t.id WHERE o.id = ?", (order_id,))
                order = fetchone_dict(_cur)
                _conn.close()
            except Exception: order = None
        elif is_combined:
            # COMBINED MODE: All orders for table
            orders = get_orders_for_table(table_data["id"])
            if orders:
                self._new_sale(confirm=False)
                
                # Set state AFTER _new_sale clears it
                self._current_order_ids = [o["id"] for o in orders]
                self._current_order_id = orders[0]["id"] # for legacy
                self._current_table = table_data
                self._restaurant_mode = True
                self._restaurant_append_mode = False
                # Re-assert waiter from first order after _new_sale wipes it
                _combined_waiter = ""
                if orders[0].get("waiter_id"):
                    from models.restaurant_order import get_waiter_name as _gwn
                    _combined_waiter = _gwn(orders[0]["waiter_id"]) or ""
                self._current_waiter_name = _combined_waiter
                
                all_items = []
                cnames = []
                for o in orders:
                    items = get_order_items(o["id"])
                    all_items.extend(items)
                    if o.get("customer_name") and o["customer_name"] not in cnames:
                        cnames.append(o["customer_name"])
                
                self._add_quotation_to_cart({
                    "cart_items": all_items,
                    "customer": ", ".join(cnames),
                    "quotation_name": f"Table {table_data['table_number']} (Combined)"
                })
                
                # Re-assert state in case _add_quotation_to_cart wiped it
                self._current_order_ids = [o["id"] for o in orders]
                self._current_order_id = orders[0]["id"]
                self._current_table = table_data
                self._restaurant_mode = True
                self._restaurant_append_mode = False
                self._refresh_pay_button_label()
                
                self._set_view_only_mode(False)
                if self.parent_window:
                    self.parent_window._set_status(f"Combined Payment for Table {table_data['table_number']} ({len(orders)} KOTs)")
                return
        else:
            # DEFAULT: Most recent active order
            order = get_order_by_table(table_data["id"])

        # 3. Ownership / Permission Check
        is_admin = (self.user.get("role") == "Administrator")
        current_waiter_id = self.user.get("id")

        if order and order.get("waiter_id") != current_waiter_id and not is_admin:
            if not view_others:
                QMessageBox.warning(self, "Permission Denied", "No permission to view others' orders.")
                return
            if not close_others:
                self._set_view_only_mode(True)
            else:
                self._set_view_only_mode(False)
        else:
            self._set_view_only_mode(False)
            
        # 3a. Capture Waiter Name
        self._current_waiter_name = ""
        _resolved_waiter_name = ""
        if order and order.get("waiter_id"):
            from models.restaurant_order import get_waiter_name
            _resolved_waiter_name = get_waiter_name(order["waiter_id"]) or ""
            self._current_waiter_name = _resolved_waiter_name
            print(f"[DEBUG] _link_to_table: order_id={order.get('id')}, waiter_id={order.get('waiter_id')}, name='{self._current_waiter_name}'")
        else:
            print(f"[DEBUG] _link_to_table: No order or waiter_id found for table {table_data.get('table_number')}")

        # 4. Apply UI Labels
        self._current_table = table_data
        self._restaurant_mode = True
        self._restaurant_append_mode = append_mode
        self._restaurant_edit_mode = edit_mode
        self._refresh_pay_button_label()
        # Show Notes column + notes bar when in restaurant mode
        if hasattr(self, 'invoice_table'):
            self.invoice_table.setColumnHidden(self.COL_NOTES, False)
        self.orders_btn.setChecked(True)
        self.orders_btn.setText(f"TABLE: {table_data['table_number']}")
        self.orders_btn.setStyleSheet(f"""
            QPushButton {{
                background-color: {ACCENT}; color: {WHITE}; border: none;
                border-radius: 4px; font-size: 11px; font-weight: bold;
            }}
        """)

        # 5. Load Items
        if order:
            saved_order_id = order["id"]
            order_items = get_order_items(order["id"])
            
            # Set ALL state BEFORE _new_sale so _refresh_pay_button_label reads correctly
            self._current_order_id = saved_order_id
            self._restaurant_mode = True
            self._restaurant_append_mode = append_mode
            self._new_sale(confirm=False)
            
            # Re-assert state after _new_sale clears _current_order_id
            self._current_order_id = saved_order_id
            self._current_table = table_data
            self._restaurant_mode = True
            self._restaurant_append_mode = append_mode
            self._current_waiter_name = _resolved_waiter_name  # re-assert after _new_sale wipes it
            
            self._add_quotation_to_cart({
                "cart_items": order_items,
                "customer": order.get("customer_name", ""),
                "quotation_name": f"KOT #ORD-{saved_order_id}",
                "bill_notes": order.get("bill_notes", ""),
            })
            
            # Re-assert state in case _add_quotation_to_cart wiped it
            self._current_order_id = saved_order_id
            self._current_table = table_data
            self._restaurant_mode = True
            self._restaurant_append_mode = append_mode
            # Ensure bill notes are loaded from the order
            self._bill_notes = order.get("bill_notes", "") or ""
            self._restaurant_edit_mode = edit_mode
            self._refresh_pay_button_label()
            
            if append_mode:
                self._recalc_totals()
                if self.parent_window:
                    self.parent_window._set_status(f"Editing KOT #ORD-{saved_order_id} (Table {table_data['table_number']})")
            else:
                if self.parent_window:
                    self.parent_window._set_status(f"Paying KOT #ORD-{saved_order_id}")
        else:
            self._current_order_id = None
            self._restaurant_mode = True
            self._restaurant_append_mode = False
            self._new_sale(confirm=False)
            # Re-assert restaurant mode after _new_sale
            self._restaurant_mode = True
            self._current_table = table_data
            self._current_order_id = None
            if self.parent_window:
                self.parent_window._set_status(f"MODE: Restaurant (Table {table_data.get('table_number')}) - New Order")

        # Final: always refresh Pay button label with correct state
        self._restaurant_edit_mode = edit_mode
        self._refresh_pay_button_label()

    def _clear_restaurant_mode(self):
        """Fully exit restaurant mode and return POS to standard sale state."""
        self._current_table = None
        self._current_order_id = None
        self._current_order_ids = []  # Clear combined list
        self._pay_all_mode = False
        self._restaurant_mode = False
        self._restaurant_append_mode = False
        self._current_waiter_name = ""  # Reset waiter name on mode exit
        self._refresh_pay_button_label()
        # Hide Notes column + notes bar in standard sale mode
        if hasattr(self, 'invoice_table'):
            self.invoice_table.setColumnHidden(self.COL_NOTES, True)
        
        if hasattr(self, 'orders_btn'):
            self.orders_btn.setText("Orders")
            self.orders_btn.setChecked(False)
            from models.restaurant_order import is_restaurant_enabled
            self.orders_btn.setVisible(is_restaurant_enabled())
            self.orders_btn.setStyleSheet(f"""
                QPushButton {{
                    background-color: {SUCCESS}; color: {WHITE}; border: none;
                    border-radius: 4px; font-size: 11px; font-weight: bold;
                }}
                QPushButton:hover {{ background-color: {SUCCESS_H}; }}
            """)
        
        self._set_view_only_mode(False)
        if self.parent_window:
            self.parent_window._set_status("MODE: Standard Sale")

    def _on_laybye(self):

        """
        Simple UI Switcher: 
        Changes the PAY F5 button to a DEPOSIT button without breaking header styles.
        """
        # Ensure references exist to prevent crashes
        if not hasattr(self, 'laybye_btn') or not hasattr(self, 'btn_pay'):
            return

        if self.laybye_btn.isChecked():
            # ΓöÇΓöÇ Permission check - mirrors discount PIN flow exactly ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
            from PySide6.QtWidgets import QInputDialog, QLineEdit
            from models.user import authenticate_by_pin

            current_user = (getattr(self, 'user', None)
                            or (getattr(self.parent_window, 'user', {})
                                if self.parent_window else {}))

            if not current_user.get('allow_laybye', True):
                pin, ok = QInputDialog.getText(
                    self, "Authorization",
                    "Manager PIN required for Laybye:",
                    QLineEdit.Password
                )
                if not ok or not pin:
                    self.laybye_btn.setChecked(False)
                    return
                manager = authenticate_by_pin(pin)
                if not manager or manager.get("role") != "admin":
                    QMessageBox.critical(self, "Access Denied", "Invalid Manager PIN.")
                    self.laybye_btn.setChecked(False)
                    return

            # 1. Clear cart if needed
            if self._collect_invoice_items():
                res = QMessageBox.question(
                    self, "Clear Cart", "Clear cart for new Laybye?", 
                    QMessageBox.Yes | QMessageBox.No
                )
                if res == QMessageBox.Yes:
                    self._new_sale(confirm=False)

            # 2. Force customer selection IMMEDIATELY - no confirmation popup
            from views.dialogs.laybye_confirm_dialog import _is_walk_in
            
            # If no customer selected OR it's walk-in, open picker immediately
            if not self._selected_customer or _is_walk_in(self._selected_customer):
                # Open customer picker directly - no warning message
                dlg = CustomerSearchPopup(self)
                if dlg.exec() == QDialog.Accepted and dlg.selected_customer:
                    # Single entry point keeps nav-bar btn + inline label +
                    # price list + grid re-price all in sync.
                    self._apply_selected_customer(dlg.selected_customer)
                else:
                    # User cancelled - turn off laybye mode
                    self.laybye_btn.setChecked(False)
                    return

            # 3. Change Main Action Button to Deposit
            self.btn_pay.setText("DEPOSIT (F5)")
            self.btn_pay.setStyleSheet(
                f"background-color: #e67e22; color: {WHITE}; font-weight: bold; "
                f"border-radius: 6px; font-size: 17px;"
            )
            
            if self.parent_window:
                self.parent_window._set_status("MODE: Laybye Active")
        
        else:
            # Reset Main Action Button (pharmacy-aware: PAY / FINALIZE QUOTE / DISPENSE)
            self._refresh_pay_button_label()
            self.btn_pay.setStyleSheet(
                f"background-color: {SUCCESS}; color: {WHITE}; font-weight: bold; "
                f"border-radius: 6px; font-size: 17px;"
            )
            
            if self.parent_window:
                self.parent_window._set_status("MODE: Standard Sale")

    def _execute_laybye_transaction(self):
        """
        Full Laybye flow logic separated for clean execution.
        Called by _open_payment if Laybye mode is active.
        DIRECT FLOW: Skips any confirmation dialogs.
        """
        if not _HAS_LAYBYE:
            QMessageBox.warning(self, "Not Available", 
                                "Laybye dialogs could not be loaded.\n"
                                "Ensure laybye_payment_dialog.py exists.")
            return

        # ΓöÇΓöÇ 1. Collect cart ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        cart_items = self._collect_invoice_items()
        if not cart_items:
            QMessageBox.information(self, "Empty Cart", "Add items to the cart first.")
            return

        try:
            cart_total = float(self._lbl_total.text() or "0")
        except ValueError:
            cart_total = sum(float(it.get("total", 0)) for it in cart_items)

        if cart_total <= 0:
            QMessageBox.information(self, "Zero Total", "Cart total is zero.")
            return

        # ΓöÇΓöÇ 2. CUSTOMER SELECTION - Already selected in _on_laybye, but verify ΓöÇΓöÇ
        from views.dialogs.laybye_confirm_dialog import _is_walk_in
        
        # If somehow customer is still missing, open picker directly
        if not self._selected_customer or _is_walk_in(self._selected_customer):
            dlg = CustomerSearchPopup(self)
            if dlg.exec() != QDialog.Accepted or not dlg.selected_customer:
                return
            self._apply_selected_customer(dlg.selected_customer)

        confirmed_customer = self._selected_customer

        # ΓöÇΓöÇ 3. Deposit dialog (Direct jump to payment) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

        from views.dialogs.laybye_payment_dialog import LaybyePaymentDialog
        
        cashier_id = self.user.get("id") if isinstance(self.user, dict) else None
        cashier_name = self.user.get("username", "") if isinstance(self.user, dict) else ""
        
        deposit_dlg = LaybyePaymentDialog(
            parent=self, 
            total=cart_total, 
            customer=confirmed_customer,
            cashier_id=cashier_id,
            cashier_name=cashier_name,
            subtotal=getattr(self, "subtotal", cart_total),
            total_vat=getattr(self, "total_vat", 0),
            shift_id=getattr(self, "shift_id", None),
            items=cart_items,
            waiter_name=getattr(self, "_current_waiter_name", ""),
        )
        if deposit_dlg.exec() != QDialog.Accepted:
            return

        deposit_amount = deposit_dlg.deposit_amount
        deposit_method = deposit_dlg.deposit_method
        deposit_splits = deposit_dlg.deposit_splits  # This is the dict with full details
        company_name   = deposit_dlg.accepted_company_name
        delivery_date  = deposit_dlg.delivery_date
        order_type     = deposit_dlg.order_type
        waiter_name    = deposit_dlg.waiter_name

        print(f"[Laybye] Deposit amount: {deposit_amount}")
        print(f"[Laybye] Deposit splits (full): {deposit_splits}")
        print(f"[Laybye] Number of splits: {len(deposit_splits) if deposit_splits else 0}")

        # Γ£à Convert splits to simple {method: usd_amount} format for the service
        simple_splits = {}
        if deposit_splits:
            for method, data in deposit_splits.items():
                # If data is a dict with 'usd' key, use that
                if isinstance(data, dict) and 'usd' in data:
                    simple_splits[method] = data['usd']
                # If data is already a number, use it directly
                elif isinstance(data, (int, float)):
                    simple_splits[method] = float(data)
                else:
                    simple_splits[method] = float(data) if data else 0.0
        
        print(f"[Laybye] Simple splits for service: {simple_splits}")

        # ΓöÇΓöÇ 4. Save Sales Order ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        try:
            from models.sales_order import create_sales_order as _create_sales_order
        except ImportError:
            QMessageBox.critical(self, "DB Error", "models/sales_order.py not found.")
            return

        so_items = [{
            "item_code": it.get("part_no", ""), 
            "item_name": it.get("product_name", ""),
            "qty": it.get("qty", 1), 
            "rate": it.get("price", 0.0), 
            "amount": it.get("total", 0.0)
        } for it in cart_items]

        try:
            order_id = _create_sales_order(
                cart_items=so_items, 
                total=cart_total, 
                deposit_amount=deposit_amount,
                deposit_method=deposit_method, 
                deposit_splits=deposit_splits,  # Pass the full splits with details
                customer=confirmed_customer,
                company=company_name, 
                delivery_date=delivery_date, 
                order_type=order_type,
                waiter_name=waiter_name,
                cashier_name=cashier_name,
            )
        except Exception as e:
            QMessageBox.critical(self, "Save Failed", f"Error: {e}")
            import traceback
            traceback.print_exc()
            return

        # ΓöÇΓöÇ 6. Print receipt ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        if _HAS_SO_PRINT:
            try:
                from services.sales_order_print import print_laybye_deposit as _print_laybye_deposit
                _print_laybye_deposit(order_id)
            except Exception as e:
                print(f"[Laybye] Print error: {e}")

        # ΓöÇΓöÇ 7. Feedback & UI Reset ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        self._refresh_unsynced_badge()
        self._new_sale(confirm=False)

        # Turn off the toggle in the header
        if hasattr(self, 'laybye_btn'):
            self.laybye_btn.setChecked(False)
            self._on_laybye()

        if self.parent_window:
            self.parent_window._set_status(f"Laybye #{order_id} Saved Successfully")

    def _refresh_pay_button_label(self):
        # Pharmacists always dispense (Quote workflow, no payment). Everyone
        # else follows the explicit cart-mode toggle. Checking is_pharmacist
        # live on every call - not relying on the potentially-stale
        # _cart_mode - means the label is always correct for the current
        # session regardless of init-time timing.
        if not hasattr(self, "btn_pay") or self.btn_pay is None:
            return
        _user = getattr(self, "user", None)
        _role = (_user or {}).get("role") if isinstance(_user, dict) else None
        _is_p = False
        try:
            from utils.roles import is_pharmacist
            _is_p = bool(is_pharmacist(_user))
        except Exception as _re:
            print(f"[POSView] is_pharmacist import failed: {_re}", flush=True)
        if _is_p:
            _allow_pay = (_user or {}).get("allow_pharmacist_pay", False)
            if _allow_pay and getattr(self, "_is_loaded_quotation", False):
                self._cart_mode = "sale"
                self.btn_pay.setText("PAY (F5)")
                self.btn_pay.setStyleSheet(
                    f"background-color: {SUCCESS}; color: {WHITE}; font-weight: bold; "
                    f"border-radius: 6px; font-size: 17px;"
                )
            else:
                # Lock pharmacists into Quote mode so _open_payment reroutes too
                self._cart_mode = "quote"
                self.btn_pay.setText("DISPENSE")
                self.btn_pay.setStyleSheet(
                    f"background-color: {SUCCESS}; color: {WHITE}; font-weight: bold; "
                    f"border-radius: 6px; font-size: 17px;"
                )
        elif getattr(self, "_restaurant_mode", False):
            if getattr(self, "_restaurant_edit_mode", False):
                self.btn_pay.setText("MODIFY KOT (F5)")
                self.btn_pay.setStyleSheet(
                    f"background-color: #f39c12; color: {WHITE}; font-weight: bold; "
                    f"border-radius: 6px; font-size: 17px;"
                )
            elif getattr(self, "_current_order_id", None) and not getattr(self, "_restaurant_append_mode", False):
                # Order loaded from an occupied table - ready for checkout
                self.btn_pay.setText("PAY ORDER (F5)")
                self.btn_pay.setStyleSheet(
                    f"background-color: {SUCCESS}; color: {WHITE}; font-weight: bold; "
                    f"border-radius: 6px; font-size: 17px;"
                )
            else:
                # Fresh table or Append Mode - save the order first
                self.btn_pay.setText("SAVE ORDER (F5)")
                self.btn_pay.setStyleSheet(
                    f"background-color: #3498db; color: {WHITE}; font-weight: bold; "
                    f"border-radius: 6px; font-size: 17px;"
                )
        elif getattr(self, "_cart_mode", "sales") == "quote":
            self.btn_pay.setText("FINALIZE QUOTE")
            self.btn_pay.setStyleSheet(
                f"background-color: {SUCCESS}; color: {WHITE}; font-weight: bold; "
                f"border-radius: 6px; font-size: 17px;"
            )
        else:
            self.btn_pay.setText("PAY  F5")
            self.btn_pay.setStyleSheet(
                f"background-color: {SUCCESS}; color: {WHITE}; font-weight: bold; "
                f"border-radius: 6px; font-size: 17px;"
            )
        print(f"[POSView] PAY label refresh: mode={getattr(self, '_cart_mode', '?')!r} "
              f"restaurant={getattr(self, '_restaurant_mode', False)} "
              f"role={_role!r} is_pharmacist={_is_p} -> {self.btn_pay.text()!r}",
              flush=True)

    def _on_quote_mode_toggle(self, checked: bool):
        # Flip cart mode and repaint the PAY button. Behavior switch happens
        # at click time inside _open_payment (which reads _cart_mode).
        self._cart_mode = "quote" if checked else "sales"
        self._refresh_pay_button_label()
        if getattr(self, "parent_window", None):
            try:
                self.parent_window._set_status(
                    f"MODE: {'Quote' if checked else 'Sales'}"
                )
            except Exception:
                pass

    def _toggle_offline(self):
        from models.company_defaults import get_defaults, save_defaults
        defaults = get_defaults() or {}
        current = defaults.get("work_offline") == "1"
        new_val = "0" if current else "1"
        defaults["work_offline"] = new_val
        save_defaults(defaults)
        
        # Update UI
        _off = (new_val == "1")
        self._offline_btn.setText("GO ONLINE" if _off else "GO OFFLINE")
        self._offline_btn.setStyleSheet(f"""
            QPushButton {{
                background-color: {SUCCESS if _off else DANGER};
                color: {WHITE}; border-radius: 4px; font-size: 12px; font-weight: bold;
            }}
            QPushButton:hover {{ background-color: {SUCCESS_H if _off else DANGER_H}; }}
        """)
        
        # Update mode label to show (OFFLINE)
        from services.credentials import get_system_mode
        _sys_mode = get_system_mode().upper()
        if _off:
            _sys_mode += " (OFFLINE)"
        
        # Find the mode label (it was added as a permanent widget)
        # We should have stored it as self._mode_lbl
        if hasattr(self, "_mode_lbl"):
            self._mode_lbl.setText(f"  MODE: {_sys_mode}  ")
            self._mode_lbl.setStyleSheet(f"color: {WHITE if 'ODOO' in _sys_mode else MID}; font-weight: bold; font-size: 11px;")

        QMessageBox.information(self, "Offline Mode", 
            f"System is now {'OFFLINE' if _off else 'ONLINE'}.\n"
            f"{'Syncing paused.' if _off else 'Syncing resumed.'}")

    def _open_payment(self):
        """
        Opens the payment dialog and processes the sale.
        Redirects to Laybye flow if toggled ON.
        In pharmacy mode, reroutes to save+print quotation (the "Dispense"
        path for pharmacists, "Finalize Quote" for everyone else).
        """
        # ΓöÇΓöÇ 0. SHIFT GUARD ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        if not self._require_active_shift():
            return

        # ΓöÇΓöÇ 0a. QUOTE MODE REROUTE ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        # Pharmacists always dispense (never finalize a sale). Other users
        # follow the explicit Quote-Mode toggle. Live is_pharmacist check so
        # this is immune to _cart_mode drift.
        _reroute = False
        try:
            from utils.roles import is_pharmacist
            _user = getattr(self, "user", getattr(self.parent_window, "user", None))
            if is_pharmacist(_user):
                _reroute = True
        except Exception:
            pass
        if not _reroute and getattr(self, "_cart_mode", "sales") == "quote":
            _reroute = True
        if hasattr(self, "btn_pay") and self.btn_pay and "PAY" in self.btn_pay.text().upper():
            _reroute = False
        if _reroute:
            self._save_quotation()
            return

        # ΓöÇΓöÇ 0b. REDIRECTION LOGIC (Laybye & Restaurant Check) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        # If the laybye switcher is toggled ON, execute the Laybye flow instead
        if hasattr(self, 'laybye_btn') and self.laybye_btn.isChecked():
            # This calls the full Laybye Flow (Confirmation -> Deposit -> Save)
            self._execute_laybye_transaction()
            return

        if getattr(self, "_restaurant_mode", False):
            if getattr(self, "_restaurant_edit_mode", False):
                self._save_restaurant_order()
                return
            btn_text = self.btn_pay.text().upper()
            if "PAY" in btn_text:
                pass # Fall through to normal payment flow
            elif getattr(self, "_restaurant_append_mode", False):
                # An existing order is loaded but we are in Append Mode.
                # Save the new items to the KOT first.
                self._save_restaurant_order()
                return
            
            if getattr(self, "_current_order_id", None):
                # Loaded order - go straight to payment
                pass  # fall through to normal payment flow below
            else:
                # Fresh table with new items - save as KOT order first
                self._save_restaurant_order()
                return

        # ΓöÇΓöÇ 1. PERMISSION & VALIDATION ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        # if not self._check_permission("allow_receipt", "Process Payment / Print Receipt"):
        #     return
            
        try:
            total = float(self._lbl_total.text() or "0")
        except ValueError:
            total = 0.0
            
        if total <= 0:
            QMessageBox.warning(self, "Empty Invoice", "Add items before payment.")
            return

        # ΓöÇΓöÇ 2. CUSTOMER REQUIREMENT ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        # Ensure the default customer is loaded if none selected yet.
        self._ensure_default_customer()
        # If still none is selected, open the customer picker now.
        if not self._selected_customer:
            QMessageBox.information(
                self, "Select Customer",
                "Please select a customer before processing payment."
            )
            _picker = CustomerSearchPopup(self)
            if _picker.exec() != QDialog.Accepted or not _picker.selected_customer:
                return  # cashier cancelled
            # Central setter - keeps nav btn + inline label + price list +
            # grid re-price + cart-clear prompt all consistent.
            self._apply_selected_customer(_picker.selected_customer)

        # ΓöÇΓöÇ 3. COLLECT INVOICE ITEMS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        items = self._collect_invoice_items()
        
        if not items or len(items) == 0:
            QMessageBox.warning(self, "No Items", "No items in the invoice to save.")
            return
        
        print(f"[POSView] Collected {len(items)} items from invoice table")
        for idx, it in enumerate(items):
            print(f"   Item {idx+1}: {it.get('product_name')} - qty: {it.get('qty')} - total: {it.get('total')}")
        
        # Calculate subtotal and VAT
        subtotal = 0.0
        total_vat = 0.0
        for it in items:
            subtotal += it.get("total", 0)
            total_vat += it.get("tax_amount", 0)
        
        # Get cashier info
        cashier_id = self.user.get("id") if isinstance(self.user, dict) else None
        cashier_name = self.user.get("username", "") if isinstance(self.user, dict) else ""
        
        # Get active shift ID
        from models.shift import get_active_shift
        active_shift = get_active_shift()
        shift_id = active_shift.get("id") if active_shift else None
        
        discount_pct = getattr(self, "current_discount_percent", 0.0)
        # ΓöÇΓöÇ FIX: discount_amount is tracked directly in _on_discount_clicked
        # from gross line totals.  Never recompute it here from `subtotal`
        # because subtotal is already the post-discount sum of COL_TOTAL values,
        # which would cause double-counting.
        discount_amt = getattr(self, "current_discount_amount", 0.0)
        
        # ΓöÇΓöÇ 4. OPEN PAYMENT DIALOG WITH ITEMS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        is_restaurant = getattr(self, "_restaurant_mode", False)
        _prefill = getattr(self, "_prefill_amounts", None)
        self._prefill_amounts = None  # consume it so next open is clean
        if _HAS_PAYMENT_DIALOG:
            dlg = _ExternalPaymentDialog(
                self,
                total=total,
                customer=self._selected_customer,
                items=items,
                cashier_id=cashier_id,
                cashier_name=cashier_name,
                subtotal=subtotal,
                total_vat=total_vat,
                discount_amount=discount_amt,
                discount_percent=discount_pct,
                shift_id=shift_id,
                is_restaurant_order=is_restaurant,
                prefill_amounts=_prefill,
                waiter_name=getattr(self, "_current_waiter_name", ""),
                table_id=getattr(self, "_current_table_id", None),
                warehouse_id=self.warehouse_id,
                cost_center_id=self.cost_center_id,
            )
        else:
            dlg = PaymentDialog(
                self,
                total=total,
                customer=self._selected_customer,
                items=items,
                cashier_id=cashier_id,
                cashier_name=cashier_name,
                subtotal=subtotal,
                total_vat=total_vat,
                discount_amount=discount_amt,
                discount_percent=discount_pct,
                shift_id=shift_id,
                is_restaurant_order=is_restaurant,
                prefill_amounts=_prefill,
                waiter_name=getattr(self, "_current_waiter_name", ""),
                table_id=getattr(self, "_current_table_id", None),
                warehouse_id=self.warehouse_id,
                cost_center_id=self.cost_center_id,
            )
        
        print(f"[DEBUG] _open_payment: Opening dialog with waiter_name='{getattr(self, '_current_waiter_name', '')}'")

        if dlg.exec() == QDialog.Accepted:
            # Γ£à EXTRACT DATA FROM THE DIALOG (sale already created inside PaymentDialog)
            if hasattr(dlg, "accepted_tendered"):
                tendered       = dlg.accepted_tendered
                method         = dlg.accepted_method
                change_out     = getattr(dlg, "accepted_change", max(tendered - total, 0.0))
                final_customer = getattr(dlg, "accepted_customer", self._selected_customer)
                sale_id_result = getattr(dlg, "accepted_sale_id", None)
                sale           = getattr(dlg, "accepted_sale", None)  # Γ£à USE THE SALE FROM DIALOG
                splits         = getattr(dlg, "accepted_splits", [])
                has_on_account = getattr(dlg, "accepted_is_credit", False)
                
                print(f"[POSView] Sale already created in PaymentDialog with ID: {sale_id_result}")
                
                # Γ£à CRITICAL: DO NOT CREATE SALE AGAIN - IT ALREADY EXISTS!
                # The sale was already created in PaymentDialog._save()
                # We just need to handle UI updates and any post-sale actions
                
                if sale is None and sale_id_result is not None:
                    # If we have sale ID but not the full sale object, fetch it
                    try:
                        from models.sale import get_sale_by_id
                        sale = get_sale_by_id(sale_id_result)
                        print(f"[POSView] Fetched sale {sale_id_result} from database")
                    except Exception as e:
                        print(f"[POSView] Error fetching sale: {e}")
                
                cust_name    = final_customer.get("customer_name", "Walk-in") if final_customer else "Walk-in"
                cust_contact = final_customer.get("custom_telephone_number", "") if final_customer else ""
                company_name = getattr(dlg, "accepted_company_name", "")

                # ΓöÇΓöÇ Work out real vs On Account amounts ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
                real_splits   = [sp for sp in splits if not sp.get("on_account")]
                oa_splits     = [sp for sp in splits if sp.get("on_account")]
                real_paid_usd = sum(sp.get("base_value", sp.get("amount", 0)) for sp in real_splits) if real_splits else (
                    0.0 if has_on_account else tendered
                )
                oa_amount      = round(sum(sp.get("base_value", sp.get("amount", 0)) for sp in oa_splits), 4)

                # ΓöÇΓöÇ 5. POST-SALE ACTIONS (Payment entries already created in PaymentDialog) ΓöÇΓöÇ
                # NOTE: Payment entries are already created in PaymentDialog._save()
                # We don't need to create them again here!
                
                print(f"[POSView] Sale #{sale.get('invoice_no', 'N/A') if sale else 'N/A'} completed")
                print(f"[POSView] Total: ${total:.2f} | Paid: ${tendered:.2f} | Change: ${change_out:.2f}")
                print(f"[POSView] Payment method: {method}")
                print(f"[POSView] On Account: {has_on_account}")
                print(f"[POSView] Splits: {len(splits)}")

                # ΓöÇΓöÇ 6. UI FEEDBACK & CLEANUP ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
                if sale:
                    self._update_prev_txn_display(
                        paid=tendered, change=change_out,
                        invoice_no=sale.get("invoice_no", "")
                    )
                    
                    # ΓöÇΓöÇ FISCALIZATION WAIT (SMART LOADER) ΓöÇΓöÇ
                    try:
                        from services.fiscalization_service import get_fiscalization_service
                        fs = get_fiscalization_service()
                        if fs and fs.is_fiscalization_enabled() and not sale.get("fiscal_qr_code"):
                            wait_dlg = FiscalWaitDialog(self, sale_id=sale.get("id"))
                            wait_dlg.exec()
                            if wait_dlg.success and wait_dlg.refreshed_sale:
                                sale.update(wait_dlg.refreshed_sale)
                            
                            # ── PRINT AFTER WAIT (Ensures 6s wait is respected) ──
                            try:
                                from services.printing_service import PrintingService
                                from models.sale import _get_active_printers, print_s
                                _ps = PrintingService()
                                _printers = _get_active_printers() or [None]
                                for _pname in _printers:
                                    _ps.print_invoice_receipt(sale, printer_name=_pname)
                                print_s(sale)
                            except Exception as e:
                                print(f"[Print] Error after wait: {e}")
                        else:
                            # ── PRINT IMMEDIATELY (if fiscalization is off or already has QR) ──
                            try:
                                from services.printing_service import PrintingService
                                from models.sale import _get_active_printers, print_s
                                _ps = PrintingService()
                                _printers = _get_active_printers() or [None]
                                for _pname in _printers:
                                    _ps.print_invoice_receipt(sale, printer_name=_pname)
                                print_s(sale)
                            except Exception as e:
                                print(f"[Print] Direct Error: {e}")
                    except Exception as e:
                        print(f"[FiscalWait] Error showing dialog: {e}")



                    if self.parent_window:
                        status = f"Sale #{sale.get('number', '')} saved - ${total:.2f} ({method})"
                        if cust_name and cust_name != "Walk-in":
                            status += f" - {cust_name}"
                        if has_on_account:
                            status += "  [On Account]"
                        self.parent_window._set_status(status)
                    self._refresh_unsynced_badge()
                else:
                    print(f"[POSView] WARNING: No sale object available after payment dialog")
                    QMessageBox.warning(self, "Sale Error", 
                        "The sale was processed but could not be retrieved. Please check the database.")
                    return

            else:
                # Fallback for older payment dialog that doesn't have accepted_sale
                print(f"[POSView] Using fallback - payment dialog didn't provide sale object")
                try:
                    tendered = float(dlg._amt.text() or "0")
                except (ValueError, AttributeError):
                    tendered = total
                method         = getattr(dlg, "_method", "CASH")
                change_out     = max(tendered - total, 0.0)
                final_customer = self._selected_customer
                sale_id_result = None
                splits         = []
                has_on_account = False
                
                # Fallback: Create sale here only if not already created
                from models.sale import create_sale
                from services.payment_entry_service import create_payment_entry
                
                discount_pct = getattr(self, "current_discount_percent", 0.0)
                discount_amt = getattr(self, "current_discount_amount", 0.0)
                cust_name = final_customer.get("customer_name", "Walk-in") if final_customer else "Walk-in"
                cust_contact = final_customer.get("custom_telephone_number", "") if final_customer else ""
                company_name = ""
                
                sale = create_sale(
                    items=items,
                    total=total,
                    tendered=tendered,
                    method=method,
                    cashier_id=cashier_id,
                    cashier_name=cashier_name,
                    customer_name=cust_name,
                    customer_contact=cust_contact,
                    company_name=company_name,
                    change_amount=change_out,
                    discount_percent=discount_pct,
                    discount_amount=discount_amt,
                    is_on_account=False,
                    skip_stock=False,
                    skip_print=True,  # SKIP AUTO-PRINT TO SHOW LOADER
                    shift_id=shift_id,
                    waiter_name=getattr(self, "_current_waiter_name", ""),
                )
                
                create_payment_entry(sale)

                # ΓöÇΓöÇ FISCALIZATION WAIT (SMART LOADER) ΓöÇΓöÇ
                try:
                    from services.fiscalization_service import get_fiscalization_service
                    fs = get_fiscalization_service()
                    if fs and fs.is_fiscalization_enabled() and not sale.get("fiscal_qr_code"):
                        wait_dlg = FiscalWaitDialog(self, sale_id=sale.get("id"))
                        wait_dlg.exec()
                        if wait_dlg.success and wait_dlg.refreshed_sale:
                            sale.update(wait_dlg.refreshed_sale)
                except Exception as e:
                    print(f"[FiscalWait] Fallback Error: {e}")

                # ── RECEIPT PRINT ──
                try:
                    from services.printing_service import PrintingService
                    from models.sale import _get_active_printers
                    _ps = PrintingService()
                    _printers = _get_active_printers() or [None]
                    for _pname in _printers:
                        _ps.print_invoice_receipt(sale, printer_name=_pname)
                except Exception as e:
                    print(f"[Print] Fallback Error: {e}")
                
                self._update_prev_txn_display(
                    paid=tendered, change=change_out,
                    invoice_no=sale.get("invoice_no", "")
                )
                if self.parent_window:
                    status = f"Sale #{sale.get('number', '')} saved - ${total:.2f} ({method})"
                    if cust_name and cust_name != "Walk-in":
                        status += f" - {cust_name}"
                    self.parent_window._set_status(status)
                self._refresh_unsynced_badge()

            # If in restaurant mode, close the active order and clear state
            if getattr(self, "_restaurant_mode", False) and getattr(self, "_current_table", None):
                try:
                    from database.db import get_connection
                    _conn = get_connection(); _cur = _conn.cursor()
                    _tid = self._current_table["id"]
                    # Mark order Paid (handle both 'Open' and legacy 'Ordered' status)
                    # We also set prep_status = 'Closed' so it leaves the KDS screen
                    _oid = getattr(self, "_current_order_id", None)
                    if _oid:
                        _cur.execute(
                            "UPDATE restaurant_orders SET status = 'Paid', prep_status = 'Closed', updated_at = CURRENT_TIMESTAMP WHERE id = ?",
                            (_oid,)
                        )
                    else:
                        _cur.execute(
                            "UPDATE restaurant_orders SET status = 'Paid', prep_status = 'Closed', updated_at = CURRENT_TIMESTAMP WHERE table_id = ? AND status IN ('Open', 'Ordered')",
                            (_tid,)
                        )
                    
                    # Mark table Available
                    _cur.execute("UPDATE restaurant_tables SET status = 'Available' WHERE id = ?", (_tid,))
                    _conn.commit(); _conn.close()

                    # Clear any collected shares for this table
                    try:
                        from models.restaurant_order import clear_bill_splits
                        clear_bill_splits(_tid)
                    except Exception:
                        pass

                    # Notify KDS monitors to clear this order
                    try:
                        from services.kds_service import kds_service
                        kds_service.broadcast_sync({"type": "refresh", "order_id": _oid or 0})
                    except Exception:
                        pass
                except Exception as _re:
                    print(f"[POSView] Error closing restaurant order: {_re}")
                
                self._clear_restaurant_mode()

            # Clear invoice for next customer
            self._new_sale(confirm=False)

            # Auto-logout if enabled
            if is_restaurant and self.parent_window:
                self.parent_window._restaurant_auto_logout()
            
        else:
            # Dialog was cancelled or rejected
            print(f"[POSView] Payment dialog cancelled")
            pass


    # =========================================================================
    # QUOTATION MANAGEMENT METHODS
    # =========================================================================
    
    def _get_active_warehouse_id(self):
        """Dynamically retrieve active warehouse_id: POS session -> user shop -> company defaults shop."""
        if getattr(self, "warehouse_id", None):
            return self.warehouse_id
        try:
            if hasattr(self, 'parent_window') and self.parent_window:
                if hasattr(self.parent_window, '_dashboard') and self.parent_window._dashboard:
                    cbo = getattr(self.parent_window._dashboard, '_stock_wh_cbo', None)
                    if cbo and cbo.currentData():
                        return cbo.currentData()
        except Exception:
            pass

        from models.product import get_warehouse_id_by_name

        # Check logged in user assigned warehouse
        if hasattr(self, 'user') and self.user:
            wh_id = self.user.get("warehouse_id")
            if wh_id:
                return wh_id
            wh_name = str(self.user.get("warehouse") or "").strip()
            if wh_name:
                wh_id = get_warehouse_id_by_name(wh_name)
                if wh_id:
                    return wh_id

        # Fallback to Company Defaults shop
        try:
            from models.company_defaults import get_defaults
            defs = get_defaults() or {}
            def_wh = str(defs.get("server_warehouse") or "").strip()
            if def_wh:
                wh_id = get_warehouse_id_by_name(def_wh)
                if wh_id:
                    return wh_id
        except Exception:
            pass

        return None

    def _open_quotation_manager(self):
        """Open quotation management dialog."""
        try:
            from views.dialogs.quotation_dialog import QuotationDialog
            dlg = QuotationDialog(self, user=getattr(self, "user", None))
            dlg.quotation_converted.connect(self._add_quotation_to_cart)
            dlg.exec()
        except ImportError as e:
            QMessageBox.warning(self, "Error", f"Could not open Quotation Manager:\n{e}")
        except Exception as e:
            QMessageBox.warning(self, "Error", f"Unexpected error:\n{e}")
    def _open_bundle_dialog(self):
        from views.dialogs.bundle_dialog import BundleDialog
        dlg = BundleDialog(self)
        dlg.exec()
    
    
    
    def _add_quotation_to_cart(self, data):
        """Add quotation items to cart."""
        cart_items = data.get("cart_items", [])
        customer = data.get("customer", "")
        quotation_name = data.get("quotation_name", "")

        # Loading a quotation converts it into an active sale - exit any active
        # Quote mode so the PAY button finalises a sale instead of saving back
        # into the quotation.
        if getattr(self, "_quotation_mode", False):
            self._quotation_mode = False
            try:
                if hasattr(self, "quote_btn") and hasattr(self.quote_btn, "setChecked"):
                    self.quote_btn.setChecked(False)
            except Exception:
                pass

        # Check if cart has items
        if self._collect_invoice_items():
            reply = QMessageBox.question(self, "Clear Cart",
                f"Load quotation {quotation_name}? This will clear the current cart.",
                QMessageBox.Yes | QMessageBox.No)
            if reply != QMessageBox.Yes:
                return
            self._new_sale(confirm=False)
            
        self._is_loaded_quotation = True
        self._loaded_quotation_name = quotation_name
        
        # Add items to cart - write directly into each empty row so the exact
        # quotation qty is preserved (bypasses the +1 duplicate logic in
        # _add_product_to_invoice which would reset every line to qty=1).
        for item in cart_items:
            qty = item.get("qty", 1)
            try:
                qty = float(qty)
                if qty <= 0:
                    qty = 1.0
            except (TypeError, ValueError):
                qty = 1.0

            # Support both quotation format (product_name/part_no)
            # and restaurant KOT format (item_name/item_code)
            name       = item.get("product_name") or item.get("item_name", "")
            price      = item.get("price", 0)
            part_no    = item.get("part_no") or item.get("item_code", "")
            product_id = item.get("product_id", None)
            discount   = item.get("discount", 0)

            # Resolve tax display from product record
            tax_display = ""
            if product_id:
                try:
                    from models.product import get_product_by_id
                    prod = get_product_by_id(product_id)
                    if prod:
                        tax_rate = prod.get("tax_rate", 0.0)
                        tax_display = f"VAT {tax_rate}%" if tax_rate > 0 else "ZERO RATED"
                except Exception:
                    pass
            if not tax_display and part_no:
                try:
                    from database.db import get_connection
                    conn = get_connection()
                    cursor = conn.cursor()
                    cursor.execute(
                        "SELECT tax_rate, tax_type FROM products WHERE part_no = ?",
                        (part_no,)
                    )
                    row = cursor.fetchone()
                    conn.close()
                    if row:
                        tax_rate = float(row[0] or 0)
                        tax_display = f"VAT {tax_rate}%" if tax_rate > 0 else "ZERO RATED"
                except Exception:
                    pass

            r = self._find_next_empty_row()
            self._ensure_rows(r + 1)
            self._block_signals = True
            _display_name = name
            if item.get("is_pharmacy") and item.get("dosage"):
                _display_name = f"{name}  -  {str(item.get('dosage')).strip()}"
                
            self._init_row(
                r,
                part_no=part_no,
                details=_display_name,
                qty=f"{qty:.4g}",
                amount=f"{price:.2f}",
                disc=f"{discount:.2f}",
                tax=tax_display
            )
            row_item = self.invoice_table.item(r, self.COL_PART_NO)
            if row_item:
                row_item.setData(Qt.UserRole, product_id)
                # Pharmacy: restore dosage/batch metadata on loaded quotation rows
                if item.get("is_pharmacy"):
                    row_item.setData(self.PHARMACY_META_ROLE, {
                        "is_pharmacy": True,
                        "dosage":      item.get("dosage"),
                        "batch_no":    item.get("batch_no"),
                        "expiry_date": item.get("expiry_date"),
                        "product_id":  product_id,
                        "from_quotation": True,
                    })
                    try:
                        row_item.setIcon(qta.icon("fa5s.prescription-bottle-alt",
                                                  color="#6a1b9a"))
                    except Exception:
                        pass
            self._block_signals = False
            self._recalc_row(r)
            self._last_filled_row = r

        self._recalc_totals()
        self._refresh_pay_button_label()

        # Set customer if provided - route through the central setter so
        # the grid reprices and the inline label stays in sync.
        if customer:
            try:
                from models.customer import search_customers
                customers = search_customers(customer)
                if customers:
                    self._apply_selected_customer(customers[0])
            except Exception as e:
                print(f"Error setting customer: {e}")
        
        if "bill_notes" in data and data["bill_notes"]:
            self._bill_notes = data["bill_notes"]
        
        if self.parent_window:
            self.parent_window._set_status(f"Loaded quotation: {len(cart_items)} items")
