    def _save_quotation(self):
        """Save and print the current cart as a Quotation."""
        items = self._collect_invoice_items()
        if not items:
            QMessageBox.information(self, "Empty Cart", "Add items before saving a Quotation.")
            return
        if not self._selected_customer:
            QMessageBox.information(self, "No Customer", "Please select a customer first.")
            return

        
        try:
            total = float(self._lbl_total.text() or "0")
        except ValueError:
            total = sum(float(i.get("total", 0)) for i in items)

        cname = self._selected_customer.get("customer_name", "")
        from PySide6.QtCore import QDateTime, QDate
        
        # =========================================================================
        # SAVE TO DATABASE
        # =========================================================================
        from datetime import date
        from models.quotation import Quotation, QuotationItem, save_quotation, get_all_quotations
        
        # Generate or reuse quotation number
        if getattr(self, "_is_loaded_quotation", False) and getattr(self, "_loaded_quotation_name", ""):
            qtn_name = self._loaded_quotation_name
        else:
            current_year = date.today().year
            existing = get_all_quotations()
            existing_names = [q.name for q in existing]
            
            qtn_num = 1
            while True:
                qtn_name = f"SAL-QTN-{current_year}-{qtn_num:05d}"
                if qtn_name not in existing_names:
                    break
                qtn_num += 1
        
        # Create quotation items with proper None handling
        quotation_items = []
        ln = 0
        for it in items:
            ln += 1
            part_no = it.get("part_no", "")
            product_name = it.get("product_name", "")
            
            # Pharmacy Enforcement: Block dispensing if dosage is missing for a pharmacy product
            is_pharm = it.get("is_pharmacy")
            if not is_pharm:
                is_pharm = self._is_pharmacy_product_lookup(it.get("product_id"), part_no)
            
            dosage = it.get("dosage")
            if is_pharm and not dosage:
                self.invoice_table.setCurrentCell(ln - 1, self.COL_NAME)
                QMessageBox.warning(
                    self, 
                    "Pharmacy Rule", 
                    f"Line {ln} ('{product_name}') requires a dosage before dispensing.\n\n"
                    f"Please select the row and press F2 to input the dosage."
                )
                return

            # Handle None values - convert to 0 if needed
            qty = it.get("qty")
            if qty is None:
                qty = 1.0
            else:
                qty = float(qty)
            
            price = it.get("price")
            if price is None:
                price = 0.0
            else:
                price = float(price)
            
            amount = it.get("total")
            if amount is None:
                amount = qty * price
            else:
                amount = float(amount)
            
            discount = it.get("discount")
            if discount is None:
                discount = 0.0
            else:
                discount = float(discount)
            
            part_no = it.get("part_no")
            if part_no is None:
                part_no = ""
            else:
                part_no = str(part_no)
            
            product_name = it.get("product_name")
            if product_name is None:
                product_name = ""
            else:
                product_name = str(product_name)
            
            uom = it.get("uom")
            if uom is None:
                uom = "Nos"
            else:
                uom = str(uom)
            
            # Calculate discounted rate if discount applied
            if discount > 0:
                discounted_rate = price * (1 - discount / 100)
            else:
                discounted_rate = price
            
            quotation_items.append(QuotationItem(
                item_code=part_no,
                item_name=product_name,
                description=product_name,
                qty=qty,
                rate=discounted_rate,
                amount=amount,
                uom=uom,
                part_no=part_no,
                # Pharmacy fields - propagate dosage/batch from row metadata
                is_pharmacy=bool(it.get("is_pharmacy", False)),
                dosage=it.get("dosage"),
                batch_no=it.get("batch_no"),
                expiry_date=it.get("expiry_date"),
            ))
        
        # Resolve a stable cashier_name for this quote so the pharmacy label
        # preview later can show the original creator even if a different
        # user opens the quote.
        _user_ctx = (getattr(self, 'user', None) or
                     (getattr(self.parent_window, 'user', {}) if self.parent_window else {}) or
                     {})
        quote_cashier_name = (
            _user_ctx.get("username")
            or _user_ctx.get("full_name")
            or "Unknown"
        )

        try:
            from utils.roles import is_pharmacist
            _user = getattr(self, "user", getattr(self.parent_window, "user", None))
            _q_status = "Dispensed" if is_pharmacist(_user) else "Draft"
        except Exception:
            _q_status = "Draft"

        # Create quotation object
        quotation = Quotation(
            name=qtn_name,
            transaction_date=date.today().isoformat(),
            grand_total=total,
            docstatus=0,  # Draft
            company=self._selected_customer.get("company_name", "APK Test"),
            status=_q_status,
            customer=cname,
            items=quotation_items,
            valid_till=None,
            reference_number=None,
            synced=False,  # ΓåÉ NOT SYNCED YET - local only
            cashier_name=quote_cashier_name,
            waiter_name=getattr(self, "_current_waiter_name", ""),
        )
        
        # Save to database
        try:
            local_id = save_quotation(quotation)
            if local_id:
                print(f"[Quotation] Γ£à Saved to database: {qtn_name} (ID: {local_id}, synced=False)")
                
                # =========================================================================
                # TRIGGER IMMEDIATE SYNC TO FRAPPE (with retry)
                # =========================================================================
                import threading
                from services.quotation_sync_service import sync_quotation_on_create
                
                # Start sync in background thread so it doesn't block UI
                def do_sync():
                    success = sync_quotation_on_create(local_id, max_retries=3)
                    if success:
                        print(f"[Quotation] Γ£à {qtn_name} synced to Frappe")
                    else:
                        print(f"[Quotation] ΓÜá∩╕Å {qtn_name} will be synced later by background worker")
                
                threading.Thread(target=do_sync, daemon=True).start()
                
            else:
                print(f"[Quotation] ΓÜá∩╕Å Failed to save to database")
                QMessageBox.warning(self, "Save Error", "Failed to save quotation to database.")
                return
        except Exception as e:
            print(f"[Quotation] Γ¥î Error saving: {e}")
            import traceback
            traceback.print_exc()
            QMessageBox.warning(self, "Save Error", f"Could not save quotation:\n{str(e)}")
            return

        # PRINT SILENTLY - no preview dialog, fire directly to printer
        _print_ok = False
        try:
            from services.quotation_print import print_quotation
            _print_ok = print_quotation({"name": qtn_name, "local_id": local_id})
        except Exception as _pe:
            _print_ok = False
            print(f"[Quotation] print_quotation raised: {_pe}")

        if self.parent_window and hasattr(self.parent_window, "_set_status"):
            self.parent_window._set_status(
                f"Quotation {qtn_name} sent to printer."
                if _print_ok else
                f"Quotation {qtn_name} saved; print failed - check printer."
            )

        # Trigger ZPL Label printing for Pharmacy Items
        try:
            from services.pharmacy_label_zpl_printer import auto_print_pharmacy_labels_for_quotation
            # Print silently (no popups) since it's part of the standard flow
            auto_print_pharmacy_labels_for_quotation(local_id, parent=self, silent=True)
        except Exception as _zpl_err:
            print(f"[Quotation] ZPL print error: {_zpl_err}")

        self._clear_cart()
        self._quotation_mode = False
        self._cart_mode = "sales"
        if hasattr(self, '_quotation_mode_btn'):
            self._quotation_mode_btn.setChecked(False)
        if hasattr(self, 'quote_mode_btn') and self.quote_mode_btn is not None:
            try:
                self.quote_mode_btn.blockSignals(True)
                self.quote_mode_btn.setChecked(False)
                self.quote_mode_btn.blockSignals(False)
            except Exception:
                pass
        try:
            self._refresh_pay_button_label()
        except Exception:
            pass

