    def _build_nav(self):
        bar = QWidget()
        bar.setFixedHeight(48)
        bar.setStyleSheet(f"background-color: {WHITE}; border-bottom: 2px solid {BORDER};")

        layout = QHBoxLayout(bar)
        layout.setContentsMargins(10, 0, 10, 0)
        layout.setSpacing(6)

        # ΓöÇΓöÇ Brand + Logo ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        logo = QLabel("Havano POS System")
        logo.setStyleSheet(f"font-size: 13px; font-weight: bold; color: {NAVY}; background: transparent;")
        layout.addWidget(logo)
        layout.addSpacing(12)

        # ΓöÇΓöÇ Uniform nav button spec ΓöÇΓöÇ
        NAV_H  = 30
        NAV_FS = 11   
        NAV_R  = 4    
        NAV_PX = 12   

        def _nav_style(bg, hov, extra=""):
            return (
                f"QPushButton {{ background-color:{bg}; color:{WHITE}; border:none; "
                f"border-radius:{NAV_R}px; font-size:{NAV_FS}px; font-weight:bold; "
                f"padding:0 {NAV_PX}px; {extra}}} "
                f"QPushButton:hover {{ background-color:{hov}; }} "
                f"QPushButton:pressed {{ background-color:{NAVY_3}; color:{WHITE}; }}"
            )

        # ΓöÇΓöÇ Helper: uniform nav button ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        def _nb(text, handler, color=NAVY_2, hov=NAVY_3, min_w=None):
            b = QPushButton(text)
            b.setFixedHeight(NAV_H)
            b.setCursor(Qt.PointingHandCursor)
            if min_w:
                b.setMinimumWidth(min_w)
            b.setStyleSheet(_nav_style(color, hov))
            b.clicked.connect(handler)
            return b

        # ΓöÇΓöÇ Fetch Mode and Toggles ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        toggles = {}
        try:
            from services.credentials import get_system_mode
            from models.advance_settings import AdvanceSettings
            mode = get_system_mode()
            if mode in ("frappe", "odoo", "saas"):
                adv_settings = AdvanceSettings.load_from_file()
                toggles = {
                    "sales": adv_settings.showAppSales,
                    "finance": adv_settings.showAppFinance,
                    "inventory": adv_settings.showAppInventory,
                }
            else:
                # If not frappe/odoo, act as if everything is enabled
                toggles = {"sales": True, "finance": True, "inventory": True}
        except Exception:
            pass

        # ΓöÇΓöÇ Sales button ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        sales_menu_btn = HoverMenuButton("Sales ", color=ACCENT, hov=ACCENT_H, height=NAV_H)
        sales_menu_btn.addItem("Sales Invoice List", self._open_sales_list)
        sales_menu_btn.addItem("Sales Orders",        self._open_sales_order_list)
        sales_menu_btn.addSeparator()
        sales_menu_btn.addItem("Sales Report", self._open_sales_report_tab)
        sales_menu_btn.addSeparator()
        sales_menu_btn.addItem("Payments", self._open_customer_payment_entry)
        sales_menu_btn.addSeparator()
