    def _is_pharmacy_product_lookup(self, product_id, part_no: str) -> bool:
        """Fetch is_pharmacy_product from DB; returns False if unresolved."""
        try:
            if product_id:
                from models.product import get_product_by_id
                prod = get_product_by_id(int(product_id))
                if prod:
                    return bool(prod.get("is_pharmacy_product", False))
            if part_no:
                from database.db import get_connection
                conn = get_connection(); cur = conn.cursor()
                cur.execute(
                    "SELECT COALESCE(is_pharmacy_product, 0) FROM products WHERE part_no = ?",
                    (part_no,),
                )
                row = cur.fetchone(); conn.close()
                if row:
                    return bool(row[0])
        except Exception as e:
            print(f"[Pharmacy] is_pharmacy_product lookup failed: {e}")
        return False

    def _is_butchery_product_lookup(self, product_id, part_no: str) -> bool:
        """Fetch is_butchery_product from DB; returns False if unresolved."""
        try:
            from database.db import get_connection
            conn = get_connection(); cur = conn.cursor()
            cur.execute("SELECT TOP 1 COALESCE(butchery_mode, '0') FROM company_defaults")
            row = cur.fetchone()
            if not row or str(row[0]) != '1':
                conn.close()
                return False
            
            if product_id:
                from models.product import get_product_by_id
                prod = get_product_by_id(int(product_id))
                if prod:
                    conn.close()
                    return bool(prod.get("is_butchery_product", False))
            if part_no:
                cur.execute(
                    "SELECT COALESCE(is_butchery_product, 0) FROM products WHERE part_no = ?",
                    (part_no,),
                )
                row2 = cur.fetchone()
                conn.close()
                if row2:
                    return bool(row2[0])
            conn.close()
        except Exception as e:
            print(f"[Butchery] is_butchery_product lookup failed: {e}")
        return False

    def _prompt_dosage_and_batch(self, product_id, part_no="") -> dict:
        """Pharmacy: modal dialog that captures dosage AND batch together.
        Returns {'dosage': str|None, 'batch_no': str|None, 'expiry_date': str|None}.
        Skipping returns all-None; no-batches path still allows the dosage
        to be captured and the cart add to proceed.

        Keyboard shortcuts: F1 = Skip, F6 = Use.

        Uses QDialog (not Qt.Popup) so the QComboBox drop-down lists inside
        are actually clickable - Qt.Popup-flagged windows auto-close as soon
        as their focus is stolen by a child popup, which made the dosage
        search combobox effectively dead."""
        if not product_id and part_no:
            try:
                from database.db import get_connection
                conn = get_connection(); cur = conn.cursor()
                cur.execute("SELECT id FROM products WHERE part_no = ?", (part_no,))
                r = cur.fetchone(); conn.close()
                if r: product_id = r[0]
            except Exception:
                pass

        try:
            from models.dosage import list_dosages
            dosages = list_dosages() or []
        except Exception as e:
            print(f"[Pharmacy] list_dosages failed: {e}")
            dosages = []

        try:
            from models.product import get_batches_for_product
            batches = get_batches_for_product(int(product_id)) if product_id else []
        except Exception as e:
            print(f"[Pharmacy] get_batches_for_product failed: {e}")
            batches = []

        # Sort batches by expiry ascending so the soonest-to-expire comes first
        # (becomes the default-selected combobox item for FIFO dispensing).
        def _exp_key(b):
            e = b.get("expiry_date") or ""
            return (e == "", str(e))  # empties last
        batches = sorted(batches, key=_exp_key)

        print(f"[Pharmacy] dosage_and_batch: {len(dosages)} dosage(s), "
              f"{len(batches)} batch(es) for product_id={product_id}", flush=True)

        # ΓöÇΓöÇ Highlighted autocomplete popup stylesheet ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        _autocomplete_popup_style = f"""
            QAbstractItemView {{
                background-color: {WHITE};
                color: {NAVY};
                font-size: 14px;
                border: 2px solid {ACCENT};
                border-radius: 6px;
                outline: none;
                padding: 2px;
            }}
            QAbstractItemView::item {{
                padding: 6px 10px;
                border-radius: 4px;
            }}
            QAbstractItemView::item:selected {{
                background-color: {ACCENT};
                color: {WHITE};
                font-weight: bold;
            }}
            QAbstractItemView::item:hover {{
                background-color: #dbeafe;
                color: {NAVY};
            }}
        """

        result = {"dosage": None, "batch_no": None, "expiry_date": None}
        state = {"last": "combo"}

        class _DispenseDlg(QDialog):
            """Inner dialog with F1/F6 shortcut handling."""
            def __init__(self_dlg, parent):
                super().__init__(parent)
                self_dlg._use_fn = None
                self_dlg._skip_fn = None

            def keyPressEvent(self_dlg, event):
                if event.key() == Qt.Key_F1:
                    if self_dlg._skip_fn:
                        self_dlg._skip_fn()
                    return
                if event.key() in (Qt.Key_F6, Qt.Key_Enter, Qt.Key_Return):
                    if self_dlg._use_fn:
                        self_dlg._use_fn()
                    return
                super().keyPressEvent(event)

        dlg = _DispenseDlg(self)
        dlg.setWindowTitle("Dispense Item - Dosage & Batch")
        dlg.setModal(True)
        dlg.setMinimumSize(560, 420)
        dlg.setStyleSheet(f"""
            QDialog {{ background: {WHITE}; }}
            QLabel  {{ color: {NAVY}; background: transparent; }}
            QComboBox, QLineEdit {{
                background: {WHITE}; color: {NAVY};
                border: 1px solid {BORDER}; border-radius: 4px;
                padding: 4px 8px; font-size: 13px; min-height: 28px;
            }}
            QComboBox:focus, QLineEdit:focus {{ border: 2px solid {ACCENT}; }}
        """)
        lay = QVBoxLayout(dlg)
        lay.setContentsMargins(16, 14, 16, 14)
        lay.setSpacing(8)

        title = QLabel("Dispense Item - Dosage & Batch")
        title.setStyleSheet(f"font-size: 15px; font-weight: bold; color: {NAVY};")
        lay.addWidget(title)

        # --- Dosage section ---
        dosage_hdr = QLabel("Dosage")
        dosage_hdr.setStyleSheet(
            f"font-size: 12px; font-weight: bold; color: {NAVY}; margin-top: 6px;")
        lay.addWidget(dosage_hdr)

        lay.addWidget(QLabel("Search saved dosage (type code or description):"))
        cbo = QComboBox(dlg)
        cbo.setEditable(True)
        cbo.setInsertPolicy(QComboBox.NoInsert)
        for d in dosages:
            desc = getattr(d, "description", "") or ""
            if not desc and hasattr(d, "get"): desc = d.get("description", "") or ""
            code = getattr(d, "code", "") or ""
            if not code and hasattr(d, "get"): code = d.get("code", "") or ""
            label = f"{code} - {desc}" if desc else code
            cbo.addItem(label, desc if desc else code)
        cbo.setCurrentIndex(-1)
        cbo.setEditText("")
        # Contains-mode case-insensitive completer for substring search
        try:
            _cmp = cbo.completer()
            if _cmp is not None:
                from PySide6.QtWidgets import QCompleter as _QCmp
                _cmp.setCompletionMode(_QCmp.PopupCompletion)
                _cmp.setFilterMode(Qt.MatchContains)
                _cmp.setCaseSensitivity(Qt.CaseInsensitive)
                _cmp.setMaxVisibleItems(12)
                popup_view = _cmp.popup()
                if popup_view:
                    popup_view.setStyleSheet(_autocomplete_popup_style)
        except Exception:
            pass
        lay.addWidget(cbo)

        lay.addWidget(QLabel("Or quick dosage (not saved):"))
        edit = QLineEdit(dlg)
        edit.setPlaceholderText("e.g. 1 tab TID x 5d")
        lay.addWidget(edit)

        # Track which dosage input the user touched last
        edit.textEdited.connect(lambda _t: state.update({"last": "edit"}))
        cbo.activated.connect(lambda _i: state.update({"last": "combo"}))

        # --- Batch section ---
        batch_hdr = QLabel("Batch & Expiry")
        batch_hdr.setStyleSheet(
            f"font-size: 12px; font-weight: bold; color: {NAVY}; margin-top: 8px;")
        lay.addWidget(batch_hdr)

        batch_cbo = QComboBox(dlg)
        if not batches:
            batch_cbo.addItem("- no batches registered -", None)
            batch_cbo.setEnabled(False)
        else:
            batch_cbo.setEditable(True)
            batch_cbo.setInsertPolicy(QComboBox.NoInsert)
            for b in batches:
                bn  = b.get("batch_no") or "(no batch no)"
                exp = b.get("expiry_date") or "?"
                qty = b.get("qty", 0)
                label = f"{bn}  -  expires {exp}   |   qty: {qty}"
                batch_cbo.addItem(label, b)
            # FIFO default: select the earliest-expiring batch (index 0 after sort)
            batch_cbo.setCurrentIndex(0)
            # Contains-filter completer so users can type batch number or date
            try:
                _bcmp = batch_cbo.completer()
                if _bcmp is not None:
                    from PySide6.QtWidgets import QCompleter as _QCmp
                    _bcmp.setCompletionMode(_QCmp.PopupCompletion)
                    _bcmp.setFilterMode(Qt.MatchContains)
                    _bcmp.setCaseSensitivity(Qt.CaseInsensitive)
                    _bcmp.setMaxVisibleItems(12)
                    popup_view = _bcmp.popup()
                    if popup_view:
                        popup_view.setStyleSheet(_autocomplete_popup_style)
            except Exception:
                pass
        lay.addWidget(batch_cbo)

        lay.addStretch()

        # --- Buttons with shortcut hints ---
        btn_row = QHBoxLayout()
        btn_row.setSpacing(8)
        cancel_btn = navy_btn("Cancel  (F1)", height=38, color=NAVY_2,  hover=NAVY_3)
        cancel_btn.setMinimumWidth(130)
        use_btn  = navy_btn("Use  (F6)",  height=38, color=SUCCESS, hover=SUCCESS_H)
        use_btn.setMinimumWidth(130)
        btn_row.addStretch(); btn_row.addWidget(cancel_btn); btn_row.addWidget(use_btn)
        lay.addLayout(btn_row)

        def _use():
            if state["last"] == "edit" and edit.text().strip():
                d_val = edit.text().strip()
            else:
                if not cbo.currentText().strip():
                    d_val = None
                else:
                    d_val = cbo.currentData() or cbo.currentText().strip()
            
            if not d_val:
                from PySide6.QtWidgets import QMessageBox
                QMessageBox.warning(dlg, "Dosage Required", "Please select or enter a dosage to dispense this product.")
                return
                
            result["dosage"] = d_val
            b = batch_cbo.currentData()
            if b:
                result["batch_no"] = b.get("batch_no") or None
                result["expiry_date"] = b.get("expiry_date")
            dlg.accept()
        def _skip():
            dlg.reject()

        dlg._use_fn = _use
        dlg._skip_fn = _skip
        use_btn.clicked.connect(_use)
        cancel_btn.clicked.connect(_skip)
        
        edit.returnPressed.connect(_use)
        if cbo.isEditable() and cbo.lineEdit():
            cbo.lineEdit().returnPressed.connect(_use)
        if batch_cbo.isEditable() and batch_cbo.lineEdit():
            batch_cbo.lineEdit().returnPressed.connect(_use)

        cbo.setFocus()
        dlg.exec()

        return {
            "dosage":      result["dosage"],
            "batch_no":    result["batch_no"],
            "expiry_date": result["expiry_date"],
        }

    def _is_pharmacy_row_locked(self, row: int) -> bool:
        # Cashiers cannot modify or delete rows stamped as pharmacy line items.
        # If the row is from a loaded quotation, 'allow_loaded_quotation_qty_change'
        # strictly allows or denies quantity modifications for BOTH cashiers & pharmacists.
        if row is None or row < 0:
            return False
        col0 = self.invoice_table.item(row, 0)
        if not col0:
            return False
        
        meta = col0.data(self.PHARMACY_META_ROLE)
        if not meta:
            return False
            
        is_from_quotation = meta.get("from_quotation", False)
        
        try:
            from database.db import get_connection as _gc
            _conn = _gc(); _cur = _conn.cursor()
            _cur.execute(
                "SELECT setting_value FROM pos_settings WHERE setting_key=?",
                ("allow_loaded_quotation_qty_change",),
            )
            _row = _cur.fetchone(); _conn.close()
            
            # If from quotation and setting is set, apply it to everyone
            if is_from_quotation and _row:
                if str(_row[0]) == "1":
                    return False  # explicitly allowed
                elif str(_row[0]) == "0":
                    return True   # explicitly blocked for everyone
        except Exception:
            pass
            
        try:
            from utils.roles import is_pharmacist
            return not is_pharmacist(getattr(self, "user", None))
        except Exception:
            return False

    def _notify_pharmacy_locked(self, row: int = -1):
        # Provide different message if it's locked because it's a quotation
        msg = "Pharmacy line items are locked - only a pharmacist can modify them."
        if row >= 0:
            col0 = self.invoice_table.item(row, 0)
            if col0:
                meta = col0.data(self.PHARMACY_META_ROLE)
                if meta and meta.get("from_quotation"):
                    try:
                        from database.db import get_connection as _gc
                        _conn = _gc(); _cur = _conn.cursor()
                        _cur.execute(
                            "SELECT setting_value FROM pos_settings WHERE setting_key=?",
                            ("allow_loaded_quotation_qty_change",),
                        )
                        _row = _cur.fetchone(); _conn.close()
                        if _row and str(_row[0]) == "0":
                            msg = "Quantities on loaded quotations are locked system-wide (see Maintenance settings)."
                    except Exception:
                        pass
        try:
            from utils.toast import show_toast
            show_toast(self, msg, duration_ms=3500, kind="warn")
        except Exception:
            pass
        QApplication.beep()

    def _add_product_to_invoice(self, name, price, part_no="", product_id=None, stock=None, uom="", notes=""):
        # ΓöÇΓöÇ Always close any open inline search before we touch the table ΓöÇΓöÇΓöÇΓöÇΓöÇ
        self._close_inline_search()

        # ΓöÇΓöÇ #0 Require a running shift ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        if not self._require_active_shift():
            return

        # ΓöÇΓöÇ Pharmacist: prompt customer selection on first cart add ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        if not getattr(self, "_pharmacist_customer_prompted", False):
            try:
                from utils.roles import is_pharmacist as _is_pharm_add
                if _is_pharm_add(getattr(self, "user", None)):
                    # Check if cart is empty (first product being added)
                    _cart_empty = True
                    for _r in range(self.invoice_table.rowCount()):
                        try:
                            if self.invoice_table.item(_r, 1) and self.invoice_table.item(_r, 1).text().strip():
                                _cart_empty = False
                                break
                        except AttributeError:
                            pass
                    if _cart_empty:
                        _current_cust = getattr(self, "_selected_customer", None)
                        _cust_name = ""
                        if _current_cust:
                            _cust_name = (_current_cust.get("customer_name") or
                                          _current_cust.get("name") or "").strip()
                        # Ask pharmacist to confirm or change customer
                        _msg = (f"Current customer: <b>{_cust_name or 'Cash Customer'}</b><br><br>"
                                "Continue with this customer or select a different one?")
                        _box = QMessageBox(self)
                        _box.setWindowTitle("Pharmacist - Select Customer")
                        _box.setText(_msg)
                        _box.setIcon(QMessageBox.Question)
                        _btn_continue = _box.addButton("Continue", QMessageBox.AcceptRole)
                        _btn_select = _box.addButton("Select Customer", QMessageBox.ActionRole)
                        _box.setDefaultButton(_btn_continue)
                        _box.setStyleSheet(f"""
                            QMessageBox {{ background-color: {WHITE}; }}
                            QLabel {{ color: {DARK_TEXT}; font-size: 13px; }}
                            QPushButton {{
                                background-color: {ACCENT}; color: {WHITE}; border: none;
                                border-radius: 5px; padding: 8px 22px; font-size: 13px;
                                min-width: 120px; font-weight: bold;
                            }}
                            QPushButton:hover {{ background-color: {ACCENT_H}; }}
                        """)
                        _box.exec()
                        if _box.clickedButton() == _btn_select:
                            self._select_customer()
                        self._pharmacist_customer_prompted = True
            except Exception as _pce:
                print(f"[Pharmacy] customer prompt error: {_pce}")

        # ── Pharmacy gate + dosage/batch capture ─────────────────────────────────
        pharmacy_meta = None
        if self._is_pharmacy_product_lookup(product_id, part_no):
            _allow_cashier = False
            try:
                from database.db import get_connection as _gc
                _c = _gc(); _cur = _c.cursor()
                _cur.execute("SELECT allow_cashier_pharmacy_sales FROM company_defaults")
                _row = _cur.fetchone()
                _c.close()
                _allow_cashier = (_row and str(_row[0]).strip() == "1")
            except Exception:
                pass

            from utils.roles import is_pharmacist as _is_pharm
            if not _is_pharm(self.user):
                if not _allow_cashier:
                    try:
                        QApplication.beep()
                    except Exception:
                        pass
                    try:
                        from utils.toast import show_toast
                        show_toast(
                            self,
                            "Only pharmacists can add pharmacy products - "
                            "ask a pharmacist to create a quote.",
                            duration_ms=3500, kind="warn",
                        )
                    except Exception:
                        pass
                    print(f"[Pharmacy] Blocked add - user is not pharmacist: {name}")
                    return
                # if _allow_cashier is True, they bypass the gate without dosage prompt.
                pharmacy_meta = {
                    "is_pharmacy": True,
                    "dosage":      "",
                    "batch_no":    "",
                    "expiry_date": None,
                    "product_id":  product_id,
                }
            else:
                # Pharmacist - single merged popup captures dosage + batch together
                combined = self._prompt_dosage_and_batch(product_id, part_no)
                if not combined.get("dosage"):
                    # Dosage is mandatory; if canceled/skipped, abort adding to cart
                    return

                pharmacy_meta = {
                    "is_pharmacy": True,
                    "dosage":      combined.get("dosage"),
                    "batch_no":    combined.get("batch_no"),
                    "expiry_date": combined.get("expiry_date"),
                    "product_id":  product_id,
                }

        # ── Butchery Amount Prompt ───────────────────────────────────────────────
        add_qty = 1.0
        if self._is_butchery_product_lookup(product_id, part_no):
            from views.dialogs.butchery_dialog import ButcheryAmountDialog
            dlg = ButcheryAmountDialog(self, product_name=name)
            if not dlg.exec():
                return  # Cancelled
            amount = dlg.get_amount()
            if amount <= 0:
                return  # Invalid amount
            if price > 0:
                add_qty = amount / float(price)
            else:
                self._warn_popup("Zero Price", f"{name} has no unit price set. Cannot calculate quantity.")
                return


        # ΓöÇΓöÇ #3 Block zero-price ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        if price <= 0 and self._get_pos_rule("block_zero_price", default=False):
            self._warn_popup(
                "Zero Price Blocked",
                f"<b>{name}</b> has no selling price set.<br>"
                "Update the price in the server and re-sync, or disable the "
                "'Block Zero-Price Sales' rule in Maintenance -> POS Rules.",
                icon=QMessageBox.Warning,
            )
            return

        # ── #4 Block zero/negative stock ─────────────────────────────────────
        if not self._get_pos_rule("allow_negative_stock", default=True):
            item_stock = None
            p_track_stock = True
            p_is_bundle = False
            p_cat = ""
            if product_id:
                try:
                    from models.product import get_product_by_id
                    wh_id = getattr(self, "_get_active_warehouse_id", lambda: None)()
                    p = get_product_by_id(product_id, warehouse_id=wh_id)
                    if p:
                        item_stock = float(p.get("stock") if p.get("stock") is not None else 0)
                        p_cat = p.get("category") or ""
                        p_track_stock = p.get("track_stock", True)
                        p_is_bundle = p.get("is_product_bundle", False)
                        if p_is_bundle:
                            try:
                                from database.db import get_connection
                                _conn = get_connection(); _c = _conn.cursor()
                                _c.execute("SELECT id FROM product_bundles WHERE name=?", (p.get("name"),))
                                _b = _c.fetchone()
                                if _b:
                                    _c.execute("SELECT item_code, quantity FROM bundle_items WHERE bundle_id=?", (_b[0],))
                                    _items = _c.fetchall()
                                    _bundle_stock = 999999.0
                                    for _icode, _qty in _items:
                                        _c.execute("SELECT stock FROM products WHERE part_no=?", (_icode,))
                                        _prow = _c.fetchone()
                                        if _prow:
                                            _cstock = float(_prow[0] if _prow[0] is not None else 0)
                                            _req = float(_qty)
                                            if _req > 0:
                                                _possible = _cstock / _req
                                                if _possible < _bundle_stock: _bundle_stock = _possible
                                    item_stock = _bundle_stock if _items else item_stock
                                _conn.close()
                            except Exception:
                                pass
                except Exception:
                    pass
            if item_stock is None and stock is not None:
                item_stock = float(stock)
            if item_stock is None:
                item_stock = 0.0

            if item_stock is not None:
                requested_total = add_qty
                for r_idx in range(self.invoice_table.rowCount()):
                    try:
                        row_name = self.invoice_table.item(r_idx, self.COL_NAME).text().strip() if self.invoice_table.item(r_idx, self.COL_NAME) else ""
                        row_part = self.invoice_table.item(r_idx, self.COL_PART_NO).text().strip() if self.invoice_table.item(r_idx, self.COL_PART_NO) else ""
                        row_pid  = self.invoice_table.item(r_idx, self.COL_PART_NO).data(Qt.UserRole) if self.invoice_table.item(r_idx, self.COL_PART_NO) else None
                        
                        match = (row_pid and row_pid == product_id) or \
                                (part_no and row_part == part_no) or \
                                (name and row_name == name)
                        if match:
                            row_qty_item = self.invoice_table.item(r_idx, self.COL_QTY)
                            row_qty = row_qty_item.text().strip() if row_qty_item else "0"
                            try:
                                current_qty = float(row_qty or "0")
                            except ValueError:
                                current_qty = 0.0
                            requested_total += current_qty
                    except AttributeError:
                        continue
                        
                if requested_total > item_stock:
                    allow_zero = False
                    if not p_track_stock:
                        allow_zero = True
                    elif p_cat:
                        try:
                            from views.main_window import load_negative_stock_categories
                            if p_cat in load_negative_stock_categories():
                                allow_zero = True
                        except: pass
                    
                    if not allow_zero:
                        self._warn_popup(
                            "Exceeding Stock Limit",
                            f"<b>{name}</b> has only {item_stock:g} unit(s) available in stock.<br>"
                            f"Requested quantity ({requested_total:g}) exceeds available stock.<br><br>"
                            "Enable 'Allow Negative Stock' in "
                            "Maintenance -> POS Rules to override.",
                            icon=QMessageBox.Warning,
                        )
                        return

        # ΓöÇΓöÇ #7 Apply Frappe pricing rules ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        if self._get_pos_rule("use_pricing_rules", default=True):
            price = self._apply_pricing_rules(product_id, part_no, price)
        
        # ΓöÇΓöÇ GET TAX INFORMATION FROM PRODUCT ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        tax_rate = 0.0
        tax_type = "ZERO RATED"
        tax_display = ""
        
        if product_id:
            try:
                from models.product import get_product_by_id
                prod = get_product_by_id(product_id)
                if prod:
                    tax_rate = prod.get("tax_rate", 0.0)
                    tax_type = prod.get("tax_type", "ZERO RATED")
                    if not tax_type:
                        tax_type = "ZERO RATED"
                    if tax_rate > 0:
                        tax_display = f"VAT {tax_rate}%"
                    else:
                        tax_display = "ZERO RATED"
                    print(f"[AddProduct] {name} - Tax Rate: {tax_rate}%, Type: {tax_type}")
            except Exception as e:
                print(f"[AddProduct] Error getting tax: {e}")
        
        for r in range(self.invoice_table.rowCount()):
            try:
                row_name   = self.invoice_table.item(r, self.COL_NAME).text().strip()
                row_amount = self.invoice_table.item(r, self.COL_PRICE).text().strip()
                row_qty    = self.invoice_table.item(r, self.COL_QTY).text().strip()
            except AttributeError:
                continue
            if not row_name:
                continue
            row_pid = self.invoice_table.item(r, self.COL_PART_NO).data(Qt.UserRole) if self.invoice_table.item(r, self.COL_PART_NO) else None
            # Must match BOTH product_id AND price - different UOMs have same id but different price
            match = (row_pid and row_pid == product_id and row_amount == f"{price:.2f}") or \
                    (not product_id and row_name == name and row_amount == f"{price:.2f}")
            if match:
                try:
                    current_qty = float(row_qty or "0")
                except ValueError:
                    current_qty = 0.0
                new_qty = current_qty + add_qty

                # ΓöÇΓöÇ Collect this row's data so we can move it ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
                def _cell_text(row, col):
                    it = self.invoice_table.item(row, col)
                    return it.text() if it else ""
                def _cell_data(row, col):
                    it = self.invoice_table.item(row, col)
                    return it.data(Qt.UserRole) if it else None

                saved_part_no    = _cell_text(r, self.COL_PART_NO)
                saved_pid        = _cell_data(r, self.COL_PART_NO)
                saved_name       = _cell_text(r, self.COL_NAME)
                saved_price      = _cell_text(r, self.COL_PRICE)
                saved_uom        = _cell_text(r, self.COL_UOM)
                saved_disc       = _cell_text(r, self.COL_DISC)
                # Use existing tax or new tax display
                existing_tax = _cell_text(r, self.COL_TAX)
                saved_tax = existing_tax if existing_tax else tax_display
                saved_notes = _cell_text(r, self.COL_NOTES)
                if saved_notes.startswith("*"):
                    saved_notes = saved_notes.lstrip("*").strip()
                if saved_notes == "":
                    saved_notes = ""

                # ΓöÇΓöÇ Remove this row and compact upward ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
                self._block_signals = True
                self._init_row(r)
                # Shift all filled rows above the gap down by one
                for shift in range(r, self.invoice_table.rowCount() - 1):
                    try:
                        next_name = self.invoice_table.item(shift + 1, 1).text().strip()
                    except AttributeError:
                        next_name = ""
                    if not next_name:
                        break
                    # copy shift+1 -> shift
                    for col in range(self.INVOICE_COL_COUNT):
                        src = self.invoice_table.item(shift + 1, col)
                        dst = self.invoice_table.item(shift, col)
                        if src and dst:
                            dst.setText(src.text())
                            dst.setTextAlignment(src.textAlignment())
                            dst.setData(Qt.UserRole, src.data(Qt.UserRole))
                    # clear the row we just copied from
                    self._init_row(shift + 1)
                self._block_signals = False

                # ΓöÇΓöÇ Find last filled row after compaction ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
                last_filled = -1
                for scan in range(self.invoice_table.rowCount()):
                    try:
                        if self.invoice_table.item(scan, 1).text().strip():
                            last_filled = scan
                    except AttributeError:
                        pass

                dest = last_filled + 1
                self._ensure_rows(dest + 1)

                # ΓöÇΓöÇ Write to destination row with tax info ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
                self._block_signals = True
                self._init_row(dest, part_no=saved_part_no, details=saved_name,
                               qty=f"{new_qty:.4g}", amount=saved_price,
                               uom=saved_uom,
                               disc=saved_disc or "0.00", tax=saved_tax, notes=saved_notes)
                item0 = self.invoice_table.item(dest, self.COL_PART_NO)
                if item0:
                    item0.setData(Qt.UserRole, saved_pid)
                    # Pharmacy meta survives row compaction: re-stamp if we had it
                    if pharmacy_meta:
                        item0.setData(self.PHARMACY_META_ROLE, pharmacy_meta)
                        try:
                            item0.setIcon(qta.icon("fa5s.prescription-bottle-alt",
                                                   color="#6a1b9a"))
                        except Exception:
                            pass
                qty_item = self.invoice_table.item(dest, self.COL_QTY)
                if qty_item:
                    qty_item.setTextAlignment(Qt.AlignCenter)
                self._block_signals = False

                self._recalc_row(dest)
                self._recalc_totals()
                self._active_row      = dest
                self._active_col      = self.COL_QTY
                self._last_filled_row = dest
                self._numpad_buffer   = ""
                self.invoice_table.setCurrentCell(dest, self.COL_QTY)
                self.invoice_table.scrollToItem(
                    self.invoice_table.item(dest, self.COL_QTY),
                    QAbstractItemView.PositionAtBottom
                )
                self._highlight_active_row(dest)
                self.invoice_table.setFocus()
                if self.parent_window:
                    self.parent_window._set_status(f"{name}  Clear{new_qty:.4g}  @ ${price:.2f}")
                # Move to next empty row and reopen inline search
                next_r = self._find_next_empty_row()
                if next_r != dest:
                    self._active_row = next_r
                    self._active_col = 0
                    self.invoice_table.setCurrentCell(next_r, 0)
                    self._highlight_active_row(next_r)
                    QTimer.singleShot(120, lambda r=next_r: self._open_inline_search(r, 0))
                return

        # ΓöÇΓöÇ New row with tax info ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        r = self._find_next_empty_row()
        self._block_signals = True
        # Fall back to the product's stock UOM when the caller didn't pass one.
        # Callers going through `_pick_product_uom_and_price` always set `uom`;
        # only legacy direct invocations (e.g. from pharmacy auto-dispense)
        # may leave it blank.
        _row_uom = uom
        if not _row_uom and product_id:
            try:
                from models.product import get_product_by_id
                _p = get_product_by_id(product_id)
                if _p:
                    _row_uom = str(_p.get("uom") or "").strip()
            except Exception:
                _row_uom = ""
        # Pharmacy: surface the dosage on the cart so the cashier can see
        # what was captured in the dispense popup - appended to the details
        # cell as "<name>  |  <dosage>". Full metadata still lives in
        # PHARMACY_META_ROLE so save_sale keeps its fields intact.
        _display_name = name
        if pharmacy_meta and pharmacy_meta.get("dosage"):
            _display_name = f"{name}  -  {str(pharmacy_meta['dosage']).strip()}"

        self._init_row(r, part_no=part_no, details=_display_name, qty=f"{add_qty:.4g}",
                       amount=f"{price:.2f}",
                       uom=_row_uom,
                       disc="0.00", tax=tax_display, notes=notes)
        item = self.invoice_table.item(r, self.COL_PART_NO)
        if item:
            item.setData(Qt.UserRole, product_id)
            # Pharmacy: stamp the row with dosage/batch metadata for save path + Phase 7
            if pharmacy_meta:
                item.setData(self.PHARMACY_META_ROLE, pharmacy_meta)
                try:
                    item.setIcon(qta.icon("fa5s.prescription-bottle-alt",
                                          color="#6a1b9a"))
                except Exception:
                    pass
        self._block_signals = False
        self._recalc_row(r)
        self._last_filled_row = r
        self._numpad_buffer   = ""
        self._highlight_active_row(r)
        self.invoice_table.scrollToItem(
            self.invoice_table.item(r, 1),
            QAbstractItemView.PositionAtBottom
        )
        self.invoice_table.setFocus()
        if self.parent_window:
            sym = self._get_currency_symbol()
            self.parent_window._set_status(f"Added: {name} @ {sym}{price:.2f} (Tax: {tax_display})")
        # Move cursor to the NEXT empty row and reopen inline search.
        next_r = self._find_next_empty_row()
        self._active_row = next_r
        self._active_col = 0
        self.invoice_table.setCurrentCell(next_r, 0)
        self._highlight_active_row(next_r)
        QTimer.singleShot(120, lambda r=next_r: self._open_inline_search(r, 0))
        
    def _collect_invoice_items(self) -> list[dict]:
        """Collect items from the invoice table with tax information"""
        items = []
        import re
        
        for r in range(self.invoice_table.rowCount()):
            try:
                qty = float(self.invoice_table.item(r, self.COL_QTY).text() or "0")
            except (ValueError, AttributeError):
                qty = 0.0
            if qty <= 0:
                continue
            try:
                part_no      = self.invoice_table.item(r, self.COL_PART_NO).text()
                # Name cell may be decorated with " ┬╖ <dosage>" for pharmacy rows;
                # keep product_name canonical so sale_items / Frappe see the raw name.
                _name_cell   = self.invoice_table.item(r, self.COL_NAME).text()
                product_name = _name_cell.split("  ┬╖  ", 1)[0].strip()
                price        = float(self.invoice_table.item(r, self.COL_PRICE).text() or "0")
                disc         = float((self.invoice_table.item(r, self.COL_DISC).text() or "0").replace('%', '').strip())
                tax_text     = self.invoice_table.item(r, self.COL_TAX).text() or ""
                total        = float(self.invoice_table.item(r, self.COL_TOTAL).text() or "0")
                product_id   = self.invoice_table.item(r, self.COL_PART_NO).data(Qt.UserRole)
                _uom_item    = self.invoice_table.item(r, self.COL_UOM)
                uom_cell     = _uom_item.text().strip() if _uom_item else ""
                _notes_item  = self.invoice_table.item(r, self.COL_NOTES)
                _raw_note    = _notes_item.text().strip() if _notes_item else ""
                _raw_note    = _raw_note.lstrip("*").strip() if _raw_note.startswith("*") else _raw_note
                notes        = "" if _raw_note == "" else _raw_note
                
                # Parse tax rate from tax column
                tax_rate = 0.0
                tax_type = "ZERO RATED"
                
                # Try to extract numeric rate from tax column (e.g., "15.5", "15.5%", "VAT 15.5%")
                numbers = re.findall(r'(\d+\.?\d*)', tax_text)
                if numbers:
                    tax_rate = float(numbers[0])
                    if tax_rate > 0:
                        tax_type = "VAT"
                else:
                    # Check text-based tax types
                    if "VAT" in tax_text.upper():
                        tax_rate = 15.5  # Default VAT rate
                        tax_type = "VAT"
                    elif "ZERO" in tax_text.upper():
                        tax_rate = 0.0
                        tax_type = "ZERO RATED"
                    elif "EXEMPT" in tax_text.upper():
                        tax_rate = 0.0
                        tax_type = "EXEMPT"
                
                # If still no tax rate, try to get from product database
                if tax_rate == 0.0 and product_id:
                    try:
                        from models.product import get_product_by_id
                        prod = get_product_by_id(product_id)
                        if prod:
                            tax_rate = prod.get("tax_rate", 0.0)
                            tax_type = prod.get("tax_type", "ZERO RATED")
                            print(f"[Tax] Product {product_name} has tax_rate={tax_rate} from DB")
                    except Exception as e:
                        print(f"[Tax] Error getting product tax: {e}")
                
                print(f"[Tax] Item: {product_name} - Rate: {tax_rate}% - Type: {tax_type}")
                
            except (ValueError, AttributeError) as e:
                print(f"[Tax] Error collecting item: {e}")
                continue
            
            # Pharmacy meta (if stamped by _add_product_to_invoice)
            pharm = None
            try:
                part_cell = self.invoice_table.item(r, self.COL_PART_NO)
                if part_cell:
                    pharm = part_cell.data(self.PHARMACY_META_ROLE)
            except Exception:
                pharm = None

            # UOM: prefer the cart cell (reflects the user's UOM-picker choice);
            # fall back to the product row so legacy adds still carry the stock UOM.
            uom_val = uom_cell
            if not uom_val and product_id:
                try:
                    from models.product import get_product_by_id
                    _p = get_product_by_id(product_id)
                    if _p:
                        uom_val = str(_p.get("uom") or "").strip()
                except Exception as _e:
                    print(f"[UOM] Could not resolve uom for product_id={product_id}: {_e}")

            items.append({
                "part_no": part_no,
                "product_name": product_name,
                "qty": qty,
                "price": price,
                "discount": disc,
                "tax": tax_text,
                "total": total,
                "product_id": product_id,
                "tax_rate": tax_rate,      # ADD THIS - numeric rate
                "tax_type": tax_type,      # ADD THIS - text type
                "tax_amount": total - (total / (1 + (tax_rate / 100))) if tax_rate > 0 else 0,
                # Unit of measure - populated for both sale & quotation paths.
                # Empty string when unresolvable (legacy product rows).
                "uom":         uom_val,
                "notes":       notes,
                # Pharmacy round-trip fields (None if not a pharmacy row)
                "is_pharmacy": bool(pharm.get("is_pharmacy")) if pharm else False,
                "dosage":      pharm.get("dosage") if pharm else None,
                "batch_no":    pharm.get("batch_no") if pharm else None,
                "expiry_date": pharm.get("expiry_date") if pharm else None,
            })

        print(f"[Tax] Total items collected: {len(items)}")
        return items

    def _save_sale(self):
        items = self._collect_invoice_items()
        if not items:
            QMessageBox.warning(self, "Empty Invoice", "Add items before saving.")
            return
        try:
            total = float(self._lbl_total.text() or "0")
        except ValueError:
            total = 0.0
        try:
            from models.sale import create_sale
            from models.shift import get_active_shift
            
            cashier_id   = self.user.get("id") if isinstance(self.user, dict) else None
            cashier_name = self.user.get("username", "") if isinstance(self.user, dict) else ""
            
            # Get active shift ID
            active_shift = get_active_shift()
            shift_id = active_shift.get("id") if active_shift else None
            
            # Calculate subtotal and total VAT
            subtotal = sum(item.get("total", 0) for item in items)
            total_vat = sum(item.get("tax_amount", 0) for item in items)
            discount_pct = getattr(self, "current_discount_percent", 0.0)
            discount_amt = getattr(self, "current_discount_amount", 0.0)
            
            sale = create_sale(
                items=items,
                total=total,
                tendered=total,
                method="CASH",
                cashier_id=cashier_id,
                cashier_name=cashier_name,
                customer_name=self._selected_customer.get("customer_name", "") if self._selected_customer else "",
                customer_contact=self._selected_customer.get("custom_telephone_number", "") if self._selected_customer else "",
                change_amount=0.0,
                discount_percent=discount_pct,
                discount_amount=discount_amt,
                subtotal=subtotal,
                total_vat=total_vat,
                shift_id=shift_id,
                waiter_name=getattr(self, "_current_waiter_name", ""),
            )
            self._update_prev_txn_display(paid=total, change=0.0, invoice_no=sale.get("invoice_no", ""))
            if self.parent_window:
                self.parent_window._set_status(f"Sale #{sale['number']} saved - ${total:.2f}")
            # ΓöÇΓöÇ Increment offline sync counter ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
            try:
                from services.printing_service import printing_service as _ps
                _ps.get_next_sync_number()
            except Exception:
                pass
            # ΓöÇΓöÇ Badge refresh: immediately after DB write, before UI reset ΓöÇΓöÇ
            self._refresh_unsynced_badge()
            self._new_sale(confirm=False)
        except Exception as e:
            QMessageBox.warning(self, "Save Error", _friendly_db_error(e))
        
    
