        def _make_badge(label, tip, handler):
            b = QPushButton(label)
            b.setFixedHeight(NAV_H)
            b.setMinimumWidth(50)
            b.setCursor(Qt.PointingHandCursor)
            b.setStyleSheet(_nav_style(NAVY_2, NAVY_3))
