    def _build_invoice_footer(self):
        bar = QWidget(); bar.setFixedHeight(45)
        bar.setStyleSheet(f"background-color: #f0e8d0; border: none;")
        layout = QHBoxLayout(bar)
        layout.setContentsMargins(14, 2, 14, 2)
        layout.setSpacing(0)

        # Left side: stacked Invoice, Paid, Change (very small)
        self._lbl_prev_invoice = QLabel("-")
        self._lbl_prev_paid = QLabel("-")
        self._lbl_prev_change = QLabel("-")

        info_vbox = QVBoxLayout()
        info_vbox.setSpacing(0)
        info_vbox.setContentsMargins(0, 0, 0, 0)
        
        def make_small(lbl, title=False):
            lbl.setStyleSheet(f"color: {MUTED}; font-size: 10px; font-weight: {'bold' if title else 'normal'}; background: transparent;")
            if not title:
                lbl.setAlignment(Qt.AlignLeft | Qt.AlignVCenter)
            else:
                lbl.setFixedWidth(55)
                
        def small_row(title, val_lbl):
            h = QHBoxLayout()
            h.setSpacing(4)
            h.setContentsMargins(0, 0, 0, 0)
            tl = QLabel(title)
            make_small(tl, True)
            make_small(val_lbl, False)
            h.addWidget(tl)
            h.addWidget(val_lbl)
            h.addStretch(1)
            return h

        info_vbox.addLayout(small_row("INVOICE:", self._lbl_prev_invoice))
        info_vbox.addLayout(small_row("PAID:", self._lbl_prev_paid))
        info_vbox.addLayout(small_row("CHANGE:", self._lbl_prev_change))
        
        layout.addLayout(info_vbox)

        # Stretch pushes Items/Rows to the center
        layout.addStretch(1)

        # Middle: Items | Rows
        self._bin_qty = QLabel("Items: 0")
        self._bin_qty.setStyleSheet(f"color: {MUTED}; font-size: 13px; background: transparent;")
        layout.addWidget(self._bin_qty)
        layout.addSpacing(16)

        sep1 = QLabel("|")
        sep1.setStyleSheet(f"color: {BORDER}; font-size: 13px; background: transparent;")
        layout.addWidget(sep1)
        layout.addSpacing(16)

        self._lbl_row_count = QLabel("Rows: 0")
        self._lbl_row_count.setStyleSheet(f"color: {MUTED}; font-size: 13px; background: transparent;")
        layout.addWidget(self._lbl_row_count)
        
        # Stretch pushes TOTAL to the right
        layout.addStretch(1)

        tot_lbl = QLabel("TOTAL")
        tot_lbl.setStyleSheet(f"color: #1e3a8a; font-size: 18px; font-weight: bold; letter-spacing: 1.5px; background: transparent;")
        tot_lbl.setAlignment(Qt.AlignVCenter)
        self._lbl_total = QLabel("")
        self._lbl_total.setAlignment(Qt.AlignRight | Qt.AlignVCenter)
        self._lbl_total.setStyleSheet(f"color: #1e3a8a; font-size: 26px; font-weight: bold; background: transparent; min-width: 120px; margin-right: 17px;")
        layout.addWidget(tot_lbl); layout.addSpacing(12); layout.addWidget(self._lbl_total)

