# MAIN WINDOW
# =============================================================================

class MainWindow(QMainWindow):
    # Class-level socket - lives for the entire process lifetime.
    # Never released on logout so re-login never drops the lock.
    _instance_sock = None

    @staticmethod
    def _acquire_instance_lock() -> bool:
        """
        Bind the sentinel port once per process.
        Returns True if this is the first (and only) instance.
        Returns False if another EXE already owns the port.
        Safe to call multiple times (re-login path): if already bound,
        returns True immediately without touching the socket.
        """
        import socket as _socket
        if MainWindow._instance_sock is not None:
            return True   # already locked by this process
        sock = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM)
        sock.setsockopt(_socket.SOL_SOCKET, _socket.SO_REUSEADDR, 0)
        try:
            sock.bind(("127.0.0.1", 47634))
            MainWindow._instance_sock = sock   # keep alive at class level
            return True
        except OSError:
            try:
                sock.close()
            except Exception:
                pass
            return False

    def __init__(self, user=None):
        super().__init__()

        # Single-instance guard
        if not MainWindow._acquire_instance_lock():
            from PySide6.QtWidgets import QApplication, QMessageBox as _MB
            for w in QApplication.topLevelWidgets():
                if w.__class__.__name__ == "SleekLoaderOverlay":
                    w.hide()
            _MB.warning(None, "Already Running", "Havano POS is already open.")
            import sys; sys.exit(0)

        self.user = user or {"username": "admin", "role": "admin"}
        self.setWindowTitle("Havano POS System")

        # Dismiss any leftover top-level sleek loaders from startup
        try:
            from PySide6.QtWidgets import QApplication
            for w in QApplication.topLevelWidgets():
                if w.__class__.__name__ == "SleekLoaderOverlay":
                    w.hide()
                    w.close()
                    w.deleteLater()
        except Exception:
            pass

        # Run DB migrations (idempotent - safe to run every time)
        try:
            from models.user import migrate as _user_migrate
            from models.restaurant_order import migrate as _restaurant_migrate
            _user_migrate()
            _restaurant_migrate()
        except Exception as _me:
            import logging; logging.getLogger("main_window").warning("DB migrate: %s", _me)
            
        try:
            from services.sync_errors_service import start_auto_wipe_daemon
            start_auto_wipe_daemon()
        except Exception as _we:
            print(f"[MainWindow] Auto-wipe daemon failed: {_we}")
        self.setMinimumSize(1280, 820)
        self.setStyleSheet(GLOBAL_STYLE)

        # ── 1. Init Status Bar FIRST so views can find it ──────────────────
        from PySide6.QtWidgets import QStatusBar
        self._status_bar = QStatusBar()
        self._status_bar.setSizeGripEnabled(False)
        self._status_bar.showMessage("  Ready")
        self.setStatusBar(self._status_bar)
        
        # Mode indicator in footer
        from services.credentials import get_system_mode
        from models.company_defaults import get_defaults
        _sys_mode = get_system_mode().upper()
        _work_off = (get_defaults() or {}).get("work_offline") == "1"
        display_mode = "OFFLINE" if _work_off else _sys_mode
        
        self._mode_lbl = QLabel(f"  MODE: {display_mode}  ")
        self._mode_lbl.setStyleSheet(f"color: {WHITE if display_mode in ['ODOO','OFFLINE'] else MID}; font-weight: bold; font-size: 11px;")
        self._mode_lbl.hide()


        # Permanent widgets in footer
        self.download_lbl_main = QLabel("")
        self.download_lbl_main.setStyleSheet(f"color: {SUCCESS}; font-weight: bold; font-size: 11px; margin-right: 15px;")
        self.download_lbl_main.hide()
        self._status_bar.addPermanentWidget(self.download_lbl_main)

        _sys_mode_lower = get_system_mode().lower()
        if _sys_mode_lower == "saas":
            _defs = get_defaults() or {}
            _wh = _defs.get("server_warehouse") or ""
            if not _wh:
                _wh = _defs.get("server_shop_id") or "Main Store"

            # Check all subscription expiry sources (defaults, sql_settings.json, user dict)
            _raw_exp = (
                _defs.get("subscription_expiry") or 
                _defs.get("expiry_date") or 
                _defs.get("valid_till") or 
                _defs.get("subscription_end_date") or 
                ""
            )
            _days_left = _defs.get("subscription_days_left") or _defs.get("days_left")
            
            if isinstance(self.user, dict):
                raw_u = self.user.get("raw_data") if isinstance(self.user.get("raw_data"), dict) else {}
                sub_u = raw_u.get("subscription") if isinstance(raw_u.get("subscription"), dict) else (self.user.get("subscription") if isinstance(self.user.get("subscription"), dict) else {})
                if _days_left is None or str(_days_left).strip() == "":
                    _days_left = sub_u.get("days_left") or self.user.get("days_left") or self.user.get("subscription_days") or raw_u.get("days_left")
                if not _raw_exp:
                    _raw_exp = sub_u.get("end_date") or sub_u.get("subscription_expiry") or self.user.get("subscription_expiry") or self.user.get("expiry_date") or self.user.get("valid_till") or ""

            if _days_left is None or str(_days_left).strip() == "":
                try:
                    import os, json
                    cfg_p = os.path.join("app_data", "sql_settings.json")
                    if os.path.exists(cfg_p):
                        with open(cfg_p, "r", encoding="utf-8") as f:
                            cfg_data = json.load(f)
                            _days_left = cfg_data.get("subscription_days_left") or cfg_data.get("days_left")
                            _raw_exp = _raw_exp or cfg_data.get("subscription_expiry") or cfg_data.get("expiry_date")
                except Exception:
                    pass

            if (_days_left is None or str(_days_left).strip() == "") and _raw_exp:
                try:
                    from datetime import datetime, date
                    exp_s = str(_raw_exp)[:10]
                    exp_d = datetime.strptime(exp_s, "%Y-%m-%d").date()
                    _days_left = (exp_d - date.today()).days
                except Exception:
                    pass

            if (_days_left is None or str(_days_left).strip() == ""):
                try:
                    from utils.license_manager import get_trial_info
                    t_info = get_trial_info()
                    if t_info.get("status") == "Active":
                        _days_left = t_info.get("days_remaining")
                except Exception:
                    pass

            if _days_left is not None and str(_days_left).strip() != "":
                try:
                    _d_int = int(_days_left)
                    if _d_int <= 0:
                        _days_str = "EXPIRED  | "
                        _color = DANGER
                    elif _d_int <= 3:
                        _days_str = f"{_d_int} day{'s' if _d_int != 1 else ''} left  | "
                        _color = "#E65100"
                    else:
                        _days_str = f"{_d_int} day{'s' if _d_int != 1 else ''} left  | "
                        _color = "#27AE60"
                except Exception:
                    _days_str = f"{_days_left} left  | "
                    _color = "#27AE60"
                
                self._sub_days_lbl = QLabel(_days_str)
                self._sub_days_lbl.setStyleSheet(f"color: {_color}; font-size: 11px; font-weight: bold;")
                self._status_bar.addPermanentWidget(self._sub_days_lbl)

            try:
                from main import APP_VERSION
            except Exception:
                APP_VERSION = "2.0.8.20"

            _ver_lbl = QLabel(f"v{APP_VERSION}  | ")
            _ver_lbl.setStyleSheet(f"color: {MID}; font-size: 11px; font-weight: bold;")
            self._status_bar.addPermanentWidget(_ver_lbl)

            _store_lbl = QLabel(f"Store: {_wh}  | ")
            _store_lbl.setStyleSheet(f"color: {MID}; font-size: 11px; font-weight: bold;")
            self._status_bar.addPermanentWidget(_store_lbl)

            _term = _defs.get("server_terminal_name") or "Terminal 1"
            _term_lbl = QLabel(f"Terminal: {_term}  | ")
            _term_lbl.setStyleSheet(f"color: {MID}; font-size: 11px; font-weight: bold;")
            self._status_bar.addPermanentWidget(_term_lbl)
            self.setWindowTitle("Havano POS System")

        _uname = self.user.get("username", "") if isinstance(self.user, dict) else ""
        _urole = (self.user.get("role", "cashier") if isinstance(self.user, dict) else "cashier") or "cashier"
        _user_lbl = QLabel(f"  {_uname} [{_urole.upper()}]  ")
        _user_lbl.setStyleSheet(f"color: {MID}; font-size: 11px;")
        self._status_bar.addPermanentWidget(_user_lbl)
        

        # Connect to updater
        try:
            from updater import update_notifier
            def _on_update_progress_main(val):
                self.download_lbl_main.setText(f"Downloading update... {val}%")
                self.download_lbl_main.show()

            def _on_update_finished_main():
                self.download_lbl_main.setText("Update ready to install!")
                self.download_lbl_main.show()

            update_notifier.progress.connect(_on_update_progress_main)
            update_notifier.finished.connect(_on_update_finished_main)
        except Exception:
            pass

        # ── 2. Views ──────────────────────────────────────────────────────
        self._stack = QStackedWidget()
        self._pos_view = POSView(parent_window=self, user=self.user)
        self._stack.addWidget(self._pos_view)
        
        # F1 Qty Keypad Shortcut
        from PySide6.QtGui import QShortcut, QKeySequence
        self._qty_shortcut = QShortcut(QKeySequence("F1"), self)
        self._qty_shortcut.activated.connect(self._pos_view._open_qty_keypad)
        
        self._f2_shortcut = QShortcut(QKeySequence("F2"), self)
        self._f2_shortcut.activated.connect(self._pos_view._save_sale)
        
        self._f3_shortcut = QShortcut(QKeySequence("F3"), self)
        self._f3_shortcut.activated.connect(self._pos_view._print_receipt)
        
        self._f4_shortcut = QShortcut(QKeySequence("F4"), self)
        self._f4_shortcut.activated.connect(self._pos_view._on_discount_clicked)
        
        self._f5_shortcut = QShortcut(QKeySequence("F5"), self)
        self._f5_shortcut.activated.connect(self._pos_view._open_payment)
        
        self._f6_shortcut = QShortcut(QKeySequence("F6"), self)
        self._f6_shortcut.activated.connect(self._pos_view._open_quotation_manager)
        
        self._f7_shortcut = QShortcut(QKeySequence("F7"), self)
        self._f7_shortcut.activated.connect(self._pos_view._open_sales_list)
        
        self._f9_shortcut = QShortcut(QKeySequence("F9"), self)
        self._f9_shortcut.activated.connect(self._pos_view._open_credit_note_dialog)

        # Secret Resource Monitor HUD Shortcut (Ctrl + Shift + Alt + M)
        self._hud_instance = None
        self._hud_shortcut = QShortcut(QKeySequence("Ctrl+Shift+Alt+M"), self)
        self._hud_shortcut.activated.connect(self._toggle_resource_hud)

        # RestaurantView and AdminDashboard are created lazily on first access
        self._restaurant_view = None
        self._restaurant_view_ready = False

        from models.user import is_admin
        _can_backoffice = is_admin(self.user) or bool(self.user.get("allow_backoffice", False))
        self._dashboard = None
        self._can_backoffice = _can_backoffice
        # AdminDashboard created lazily via self._ensure_dashboard_created() when admin tab is opened

        # ── 3. Finalize UI ────────────────────────────────────────────────
        self.setCentralWidget(self._stack)
        self.menuBar().hide() # Hide redundant navbar as requested

        # -- 4. Initial logic after UI is up -------------------------------
        self._start_terminal_takeover_timer()
        # Default Landing Page: Check Restaurant Settings
        try:
            from models.restaurant_order import get_restaurant_settings
            rs = get_restaurant_settings()
            if rs.get("default_view_restaurant"):
                QTimer.singleShot(50, self.switch_to_orders)
            else:
                QTimer.singleShot(50, self.switch_to_pos)
        except Exception:
            QTimer.singleShot(50, self.switch_to_pos)

        # Proactively prompt for a shift right after login if none is running.
        QTimer.singleShot(150, self._prompt_open_shift_if_missing)

        # ── Defer ALL heavy background services to after window is shown ──
        QTimer.singleShot(2000, self._deferred_init_services)

    def _toggle_resource_hud(self):
        """Toggle the secret real-time System Resource Monitor HUD window."""
        try:
            if self._hud_instance is None:
                from views.components.resource_monitor_hud import ResourceMonitorHUD
                self._hud_instance = ResourceMonitorHUD(self)

            if self._hud_instance.isVisible():
                self._hud_instance.hide()
            else:
                if hasattr(self._hud_instance, "expand_full_mode"):
                    self._hud_instance.expand_full_mode()
                # Position HUD near top-right corner of main window
                geo = self.geometry()
                self._hud_instance.move(max(10, geo.x() + geo.width() - 460), max(10, geo.y() + 60))
                self._hud_instance.show()
                self._hud_instance.raise_()
                self._hud_instance.activateWindow()
        except Exception as e:
            print(f"[HUD] Error toggling secret resource monitor HUD: {e}")

    def _prompt_open_shift_if_missing(self):
        try:
            if hasattr(self, "_pos_view") and hasattr(self._pos_view, "_prompt_open_shift_if_missing"):
                self._pos_view._prompt_open_shift_if_missing()
            else:
                from models.shift import get_active_shift
                if get_active_shift():
                    return
                from views.dialogs.start_shift_dialog import StartShiftDialog
                dlg = StartShiftDialog(self, user=self.user)
                if dlg.exec() == QDialog.Accepted:
                    self._refresh_shift_pill()
        except Exception as e:
            print(f"[MainWindow] prompt open-shift failed: {e}")

    def _start_terminal_takeover_timer(self):
        """Continuously send fast ping heartbeat and monitor terminal takeover status."""
        try:
            from services.credentials import get_system_mode
            if get_system_mode() != "saas":
                return
        except Exception:
            pass
        from utils.hardware import get_machine_id
        from models.company_defaults import get_defaults, save_defaults
        from services.auth_service import set_active_session_user
        
        u_email = ""
        if hasattr(self, "user") and isinstance(self.user, dict):
            u_email = self.user.get("email") or self.user.get("username") or self.user.get("frappe_user") or ""
        if u_email:
            set_active_session_user(u_email)

        my_dev = get_machine_id().strip().lower()
        d = get_defaults() or {}
        d["bound_device_id"] = my_dev
        d["device_hardware_id"] = my_dev
        save_defaults(d)

        # Delay first ping by 5s to allow login session & token to fully commit to DB
        # before the first select_terminal check (avoids spurious 401 on startup).
        QTimer.singleShot(5000, lambda: self._do_terminal_takeover(force_takeover=True))

        if not hasattr(self, "_takeover_timer") or self._takeover_timer is None:
            print("[takeover_monitor] Started — ping/takeover check every 30s in SaaS mode")
            self._takeover_timer = QTimer(self)
            self._takeover_timer.setInterval(30000)  # 30 seconds
            self._takeover_timer.timeout.connect(lambda: self._do_terminal_takeover(force_takeover=True))
            self._takeover_timer.start()

    @Slot()
    def _evict_and_logout_user(self):
        """Safely executed on the Main GUI thread to stop timers, warn user, and restart to Login Dialog."""
        print("[takeover_monitor] Executing session eviction on Main GUI Thread...")
        if hasattr(self, "_takeover_timer") and self._takeover_timer:
            try:
                self._takeover_timer.stop()
            except Exception:
                pass
        try:
            msg_box = QMessageBox(self)
            msg_box.setWindowTitle("Terminal Session Disconnected")
            msg_box.setIcon(QMessageBox.Warning)
            msg_box.setText("Your terminal session was taken over by another device.")
            msg_box.setInformativeText("Please log in again with your email to take over this terminal.")
            msg_box.setStandardButtons(QMessageBox.Ok)
            msg_box.exec()
        except Exception as _e:
            print(f"[takeover_monitor] Warning popup error: {_e}")

        try:
            from PySide6.QtCore import QProcess
            from PySide6.QtWidgets import QApplication
            import sys
            print("[takeover_monitor] Restarting application to Login Screen...")
            QProcess.startDetached(sys.executable, sys.argv)
            QApplication.quit()
        except Exception as _e:
            print(f"[takeover_monitor] Restart error: {_e}")
            try:
                self.close()
            except Exception:
                pass

    def _do_terminal_takeover(self, force_takeover: bool = True):
        """
        Called on login AND every 30 seconds.
        Runs status check/takeover ping in a background thread to prevent UI freezing.
        If another device has claimed the terminal, logs out the current user session.
        """
        import threading
        def _worker():
            try:
                from services.credentials import get_system_mode
                if get_system_mode() != "saas":
                    return

                from models.company_defaults import get_defaults, save_defaults
                from utils.hardware import get_machine_id, is_same_device
                from services.auth_service import select_terminal
                from PySide6.QtCore import QMetaObject, Qt

                d = get_defaults() or {}
                term_id = str(d.get("server_terminal_id") or d.get("terminal_id") or "").strip()
                shop_id = str(d.get("server_shop_id") or "").strip()
                if shop_id and term_id == shop_id:
                    term_id = ""
                if not term_id:
                    return

                u_email = ""
                if hasattr(self, "user") and isinstance(self.user, dict):
                    candidate = str(self.user.get("email") or self.user.get("frappe_user") or "").strip()
                    if "@" in candidate:
                        u_email = candidate
                    else:
                        uid = self.user.get("id")
                        uname = self.user.get("username")
                        try:
                            from database.db import get_connection
                            conn = get_connection()
                            cur = conn.cursor()
                            if uid:
                                cur.execute("SELECT email FROM users WHERE id=?", (uid,))
                            elif uname:
                                cur.execute("SELECT email FROM users WHERE username=?", (uname,))
                            row = cur.fetchone()
                            if row and row[0] and "@" in str(row[0]):
                                u_email = str(row[0]).strip()
                            conn.close()
                        except Exception:
                            pass

                if not u_email or "@" not in u_email:
                    try:
                        from services.auth_service import get_active_session_user
                        _active_e = get_active_session_user()
                        if _active_e and "@" in str(_active_e):
                            u_email = str(_active_e).strip()
                    except Exception:
                        pass

                if not u_email or "@" not in u_email:
                    try:
                        _def_e = (d.get("saas_user_email") or d.get("saas_email") or d.get("user_email") or d.get("email") or "")
                        if _def_e and "@" in str(_def_e):
                            u_email = str(_def_e).strip()
                    except Exception:
                        pass

                my_dev = get_machine_id()
                res = select_terminal(term_id, takeover=False, user_email=u_email)

                if not (res.get("success") and res.get("data")):
                    err = str(res.get("error") or res.get("message") or "no response")
                    print(f"[takeover_monitor] Takeover check response: {err}")
                    err_lower = err.lower()
                    # Only evict on explicit ownership conflict — NOT on plain 401 / unauthorized
                    # which can occur transiently when the session token hasn't fully propagated.
                    if any(k in err_lower for k in ["assigned to another", "taken over", "403"]):
                        print(f"[takeover_monitor] EVICTION TRIGGERED — server rejected terminal session: {err}")
                        d["server_terminal_id"] = ""
                        save_defaults(d)
                        QMetaObject.invokeMethod(self, "_evict_and_logout_user", Qt.QueuedConnection)
                        return
                    return

                user_obj   = res.get("data", {}).get("user") or {}
                sel_term_id = (user_obj.get("selected_terminal_id") or term_id) if isinstance(user_obj, dict) else term_id
                cloud_bound = ""
                found = False
                for shop in (user_obj.get("shops") or [] if isinstance(user_obj, dict) else []):
                    for term in (shop.get("terminals") or []):
                        if str(term.get("id")) == str(sel_term_id):
                            cloud_bound = str(term.get("device_hardware_id") or "").strip()
                            found = True
                            break
                    if found:
                        break

                if not cloud_bound and res.get("success"):
                    cloud_bound = my_dev

                if cloud_bound and is_same_device(cloud_bound, my_dev):
                    d["bound_device_id"] = my_dev
                    save_defaults(d)
                    print(f"[takeover_monitor] [PING OK] Active Device: {my_dev[:16]} | User: {u_email or 'n/a'}")
                elif cloud_bound and not is_same_device(cloud_bound, my_dev):
                    d["bound_device_id"] = cloud_bound
                    save_defaults(d)
                    print(f"[takeover_monitor] TAKEOVER EVICTION — terminal is bound to another device ID '{cloud_bound}' (my_dev='{my_dev}'). Emitting eviction.")
                    QMetaObject.invokeMethod(self, "_evict_and_logout_user", Qt.QueuedConnection)

            except Exception as _e:
                print(f"[takeover_monitor] Error: {_e}")

        threading.Thread(target=_worker, daemon=True).start()


    # Keep old names as aliases so any existing call-sites don't break
    def _send_online_ping_heartbeat(self):
        self._do_terminal_takeover()

    def _check_terminal_takeover_status(self):
        self._do_terminal_takeover()


    def _ensure_dashboard_created(self):
        """Lazily create AdminDashboard only when first needed."""
        if self._dashboard is None and self._can_backoffice:
            self._dashboard = AdminDashboard(parent_window=self, user=self.user)
            self._stack.addWidget(self._dashboard)
        return self._dashboard

    def _ensure_restaurant_view_created(self):
        """Lazily create RestaurantView only when first needed."""
        if self._restaurant_view_ready:
            return self._restaurant_view
        self._restaurant_view_ready = True
        try:
            from views.restaurant_view import OrderView
            self._restaurant_view = OrderView(parent=self)
            self._restaurant_view.back_to_pos.connect(self.switch_to_pos)
            self._restaurant_view.table_selected.connect(lambda t: self._on_table_selected_from_restaurant(t, append_mode=False))
            self._restaurant_view.action_add_order.connect(lambda t: self._on_table_selected_from_restaurant(t, append_mode=False, force_new=True))
            self._restaurant_view.action_pay_order.connect(lambda o: self._on_kot_action("pay", o))
            self._restaurant_view.action_edit_kot.connect(lambda o: self._on_kot_action("edit", o))
            self._restaurant_view.action_cancel_kot.connect(self._on_cancel_kot)
            from models.user import is_admin
            self._restaurant_view.user = self.user
            self._restaurant_view._is_admin = is_admin(self.user)
            self._restaurant_view._current_waiter_id = self.user.get("id")
            self._restaurant_view.action_pay_all.connect(self._on_pay_all_orders)
            self._stack.addWidget(self._restaurant_view)
            print("[MainWindow] RestaurantView created (lazy).")
        except Exception as e:
            print(f" restaurant view error: {e}")
            self._restaurant_view = None
        return self._restaurant_view

    def _deferred_init_services(self):
        """Start all background sync services AFTER the UI is fully drawn."""
        print("[MainWindow] Starting deferred background services...")

        # ── Quotation sync thread ─────────────────────────────────────────
        try:
            from services.quotation_sync_service import start_quotation_sync_thread
            self.quotation_sync_thread = start_quotation_sync_thread()
        except Exception as _e:
            print(f"[MainWindow] Quotation sync thread error: {_e}")

        # ── KDS WebSocket Server ───────────────────────────────────────────
        try:
            from database.db import get_connection
            conn = get_connection(); cur = conn.cursor()
            cur.execute("SELECT setting_value FROM pos_settings WHERE setting_key='enable_kds_websocket'")
            row = cur.fetchone(); conn.close()
            kds_enabled = bool(int(row[0])) if row else False
            
            if kds_enabled:
                from services.kds_service import kds_service
                kds_service.start_server()
                print("[MainWindow] KDS WebSocket server started on port 8765")
            else:
                print("[MainWindow] KDS WebSocket server disabled by POS rules")
        except Exception as _e:
            print(f"[MainWindow] KDS server failed: {_e}")

        # ── Background sync services ──────────────────────────────────────────
        # Customer sync (every 5 min) - pulls Frappe/SaaS customers into local DB
        try:
            from services.customer_sync_service import start_customer_sync_thread
            self._customer_sync_thread = start_customer_sync_thread()
        except Exception as _e:
            import logging
            logging.getLogger("MainWindow").warning("Customer sync service could not start: %s", _e)

        # Product sync (every 15 s) - keeps local product list up to date
        try:
            from services.product_sync_windows_service import start_sync_daemon
            self._product_sync_thread = start_sync_daemon()
        except Exception as _e:
            import logging
            logging.getLogger("MainWindow").warning(
                "Product sync service could not start: %s", _e)

        # POS upload (every 60 s) - pushes local unsynced sales to server
        try:
            from services.pos_upload_service import start_upload_thread
            self._upload_worker = start_upload_thread()
        except Exception as _e:
            import logging
            logging.getLogger("MainWindow").warning(
                "POS upload service could not start: %s", _e)

        # Payment entry sync - pushes local payment entries -> Server
        try:
            from services.payment_entry_service import start_payment_sync_daemon
            self._payment_sync = start_payment_sync_daemon()
        except Exception as _e:
            import logging
            logging.getLogger("MainWindow").warning(
                "Payment entry sync could not start: %s", _e)
                
        # Customer payment sync - pushes account payments -> Server
        try:
            from services.payment_upload_service import start_payment_sync_daemon as start_customer_payment_sync
            self._customer_payment_sync = start_customer_payment_sync()
            
            from services.odoo.payment_sync_service import start_odoo_payment_sync_daemon
            self._odoo_payment_sync = start_odoo_payment_sync_daemon()
        except Exception as _e:
            import logging
            logging.getLogger("MainWindow").warning(
                "Customer payment sync could not start: %s", _e)

        # Accounts + exchange rates sync (hourly)
        try:
            from services.accounts_sync_service import start_accounts_sync_daemon
            self._accounts_sync = start_accounts_sync_daemon()
        except Exception as _e:
            import logging
            logging.getLogger("MainWindow").warning(
                "Accounts sync could not start: %s", _e)
        
        # Sales Order pull - pulls Frappe Sales Orders -> local DB every 5 min
        try:
            from services.sales_order_pull_service import start_sales_order_pull_daemon
            self._sales_order_pull = start_sales_order_pull_daemon()
        except Exception as _e:
            import logging
            logging.getLogger("MainWindow").warning(
                "Sales Order pull could not start: %s", _e)

        # Credit note sync (every 60s) -- pushes ready CNs to server
        try:
            from services.credit_note_sync_service import start_credit_note_sync_daemon
            self._cn_sync = start_credit_note_sync_daemon()
        except Exception as _e:
            import logging
            logging.getLogger("MainWindow").warning(
                "Credit note sync could not start: %s", _e)

        # Sales Order (Laybye) sync - pushes unsynced SOs to server
        try:
            from services.sales_order_upload_service import start_so_upload_thread
            self._so_upload_thread = start_so_upload_thread()
        except Exception as _e:
            import logging
            logging.getLogger("MainWindow").warning(
                "Sales Order upload service could not start: %s", _e)

        # Laybye Payment Entry sync - pushes local laybye deposits -> Server
        try:
            from services.laybye_payment_entry_service import start_laybye_pe_sync_daemon
            self._laybye_payment_sync = start_laybye_pe_sync_daemon()
        except Exception as _e:
            import logging
            logging.getLogger("MainWindow").warning(
                "Laybye payment entry sync could not start: %s", _e)

        # ── Ensure sync_errors table exists ────────────────────────────────────
        try:
            from services.sync_errors_service import ensure_table as _set
            _set()
        except Exception:
            pass

        # ── Sync error bus - route background sync errors to the GUI ─────────────
        try:
            from services.sync_errors_service import sync_error_bus
            sync_error_bus.error_posted.connect(
                self._on_sync_error,
                Qt.QueuedConnection)
        except Exception:
            pass
        
        try:
            from services.bundle_sync_service import start_bundle_sync_daemon
            self._bundle_sync = start_bundle_sync_daemon()
        except Exception as _e:
            print(f"[MainWindow] Bundle sync daemon error: {_e}")

        # -- Price List Assignment Background Task -------------------------
        try:
            self._price_list_timer = QTimer(self)
            self._price_list_timer.setInterval(60000) # every 1 minute
            self._price_list_timer.timeout.connect(self._ensure_default_price_list_assigned)
            self._price_list_timer.start()
            QTimer.singleShot(5000, self._ensure_default_price_list_assigned) # Initial check
        except Exception as _e:
            print(f"[MainWindow] Price list timer error: {_e}")

        print("[MainWindow] All deferred services started.")

    def _ensure_default_price_list_assigned(self):
        """
        Background task to ensure ALL customers have a default price list.
        Corrects records where price list is NULL or 0.
        """
        try:
            from database.db import get_connection
            conn = get_connection(); cur = conn.cursor()
            cur.execute("SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'price_lists'")
            if cur.fetchone()[0] == 0:
                conn.close()
                return
            
            # 1. Ensure at least one price list exists
            cur.execute("SELECT TOP 1 id FROM price_lists ORDER BY id ASC")
            row = cur.fetchone()
            if not row:
                cur.execute("INSERT INTO price_lists (name, selling) VALUES ('Standard Selling', 1)")
                conn.commit()
                cur.execute("SELECT TOP 1 id FROM price_lists ORDER BY id ASC")
                row = cur.fetchone()
            
            if not row:
                conn.close()
                return
            
            default_pl_id = row[0]

            # 2. Update customers missing a price list
            cur.execute("""
                UPDATE customers 
                SET default_price_list_id = ? 
                WHERE default_price_list_id IS NULL OR default_price_list_id = 0
            """, (default_pl_id,))
            
            if cur.rowcount > 0:
                conn.commit()
                print(f"[Service] Auto-assigned Price List {default_pl_id} to {cur.rowcount} customer(s).")
            
            # 3. Check specific defaults (Walk-in customer and Company Defaults)
            cur.execute("SELECT id, default_price_list_id FROM customers WHERE id = 1")
            cust = cur.fetchone()
            if cust:
                if not cust[1] or cust[1] == 0:
                    print(f"[MainWindow] Assigning Price List ID {default_pl_id} to Walk-in customer...")
                    cur.execute("UPDATE customers SET default_price_list_id = ? WHERE id = 1", (default_pl_id,))
                    conn.commit()
            
            cur.execute("SELECT id, default_price_list_id FROM company_defaults")
            defaults = cur.fetchone()
            if defaults:
                if not defaults[1] or defaults[1] == 0:
                    print(f"[MainWindow] Setting default_price_list_id in company_defaults to {default_pl_id}")
                    cur.execute("UPDATE company_defaults SET default_price_list_id = ?", (default_pl_id,))
                    conn.commit()

            conn.close()
        except Exception as e:
            print(f"[MainWindow] Price List Assignment Error: {e}")
            import traceback
            traceback.print_exc()

    def _print_kot(self, order_id: int, diff_items: list = None, is_modified: bool = False, modify_reason: str = ""):
        """Print KOT production slips for each kitchen station, then one full
        summary receipt to the main invoice printer."""
        try:
            from models.restaurant_order import get_order_items, get_waiter_name
            from database.db import get_connection, fetchone_dict

            # Fetch order meta
            conn = get_connection(); cur = conn.cursor()
            cur.execute("SELECT * FROM restaurant_orders WHERE id = ?", (order_id,))
            order = fetchone_dict(cur)
            conn.close()
            if not order: return

            # Remap DB field names -> print_s field names
            if diff_items is not None:
                items = diff_items
            else:
                raw_items = get_order_items(order_id)
                items = []
                for it in raw_items:
                    items.append({
                        "product_name": it.get("item_name") or it.get("product_name", ""),
                        "qty":          it.get("quantity") or it.get("qty") or 1,
                        "price":        it.get("rate") or it.get("price") or 0,
                        "part_no":      it.get("item_code") or it.get("part_no", ""),
                        "notes":        it.get("item_notes") or it.get("notes", ""),
                        "order_1":      it.get("order_1", 0),
                        "order_2":      it.get("order_2", 0),
                        "order_3":      it.get("order_3", 0),
                        "order_4":      it.get("order_4", 0),
                        "order_5":      it.get("order_5", 0),
                        "order_6":      it.get("order_6", 0),
                    })

            waiter_name = get_waiter_name(order.get("waiter_id"))

            # ── 1. Kitchen station slips (existing behaviour, unchanged) ──────
            sale_stub = {
                "invoice_no":    f"KOT-{order.get('shift_order_number', order_id)}",
                "items":         items,
                "cashier_name":  waiter_name,
                "waiter_name":   waiter_name,
                "table_name":    order.get("table_name", f"Table {order.get('table_id', '')}"),
                "customer_name": order.get("customer_name", ""),
                "bill_notes":    order.get("bill_notes", ""),
                "order_number":  order.get("shift_order_number", order_id),
                "is_modified":   is_modified,
                "modify_reason": modify_reason,
            }
            from models.sale import print_s
            import threading
            threading.Thread(target=print_s, args=(sale_stub,), daemon=True).start()

            # ── 2. Full summary receipt -> main invoice printer ─────────────────
            threading.Thread(
                target=self._print_kot_summary,
                args=(order_id, order, items, waiter_name, is_modified, modify_reason),
                daemon=True,
            ).start()

        except Exception as e:
            print(f"Error in _print_kot: {e}")

    def _print_kot_summary(self, order_id: int, order: dict, items: list, waiter_name: str, is_modified: bool = False, modify_reason: str = ""):
        """Print one full receipt-style summary of the entire KOT to the main printer."""
        try:
            from models.company_defaults import get_defaults
            from models.receipt import ReceiptData, Item
            from database.hardware_settings_db import get_hardware_settings
            from services.printing_service import PrintingService

            co = get_defaults() or {}

            receipt = ReceiptData()
            receipt.companyName        = co.get("company_name", "Havano POS")
            receipt.companyLogoPath    = co.get("logo_path", "")
            receipt.companyAddress     = co.get("address", "")
            receipt.tel                = co.get("phone", "")
            receipt.tin                = co.get("tin", "")
            receipt.vatNo              = co.get("vat_no", "")
            receipt.receiptHeader      = "*** MAIN ORDER ***"
            receipt.invoiceNo          = f"KOT-{order.get('shift_order_number', order_id)}"
            receipt.orderNumber        = order.get("shift_order_number", order_id)
            receipt.cashierName        = waiter_name
            receipt.tableName          = order.get("table_name") or f"Table {order.get('table_id', '')}"
            receipt.customerName       = order.get("customer_name", "")
            receipt.bill_notes         = order.get("bill_notes", "")
            receipt.is_modified        = is_modified
            receipt.modify_reason      = modify_reason

            from datetime import datetime
            receipt.invoiceDate        = datetime.now().strftime("%Y-%m-%d")

            receipt.items = [
                Item(
                    productName = it.get("product_name", ""),
                    productid   = it.get("part_no", ""),
                    qty         = float(it.get("qty") if it.get("qty") is not None else 1),
                    price       = float(it.get("price") or 0),
                    amount      = float(it.get("qty") if it.get("qty") is not None else 1) * float(it.get("price") or 0),
                    item_notes  = it.get("notes", ""),
                    is_cancelled = bool(it.get("is_cancelled", False)),
                    old_qty      = float(it.get("old_qty", 0.0) or 0.0)
                )
                for it in items
            ]
            receipt.grandTotal = sum(i.amount for i in receipt.items)
            receipt.footer     = "- end of kitchen order -"

            hw = get_hardware_settings()
            main_printer = hw.get("main_printer", "") or ""
            if main_printer == "(None)":
                main_printer = ""

            PrintingService().print_master_kot(receipt, printer_name=main_printer or None)
            print(f"[OK] KOT summary printed to {main_printer or 'default'}")
        except Exception as e:
            print(f"Error printing KOT summary: {e}")

    def _print_main_sales_order(self, order_id: int):
        """
        Print the full main SALES ORDER receipt to the invoice printer
        automatically when a restaurant order is saved.
        Runs in a background thread so it never blocks the UI.
        """
        import threading
        threading.Thread(
            target=self.__do_print_main_sales_order,
            args=(order_id,),
            daemon=True,
        ).start()

    def __do_print_main_sales_order(self, order_id: int):
        """Worker - runs off the main thread."""
        try:
            from models.company_defaults import get_defaults
            from models.receipt import ReceiptData, Item
            from models.restaurant_order import get_order_items, get_waiter_name
            from models.advance_settings import AdvanceSettings
            from services.printing_service import PrintingService
            from database.db import get_connection, fetchone_dict
            from datetime import datetime

            # ── Fetch order header ─────────────────────────────────────────
            conn = get_connection()
            cur  = conn.cursor()
            cur.execute(
                "SELECT o.*, t.name AS table_name, t.table_number "
                "FROM restaurant_orders o "
                "LEFT JOIN restaurant_tables t ON o.table_id = t.id "
                "WHERE o.id = ?",
                (order_id,),
            )
            order = fetchone_dict(cur)
            conn.close()
            if not order:
                print(f"[MainSalesOrder] Order {order_id} not found - skipping print.")
                return

            # ── Fetch items ────────────────────────────────────────────────
            raw_items = get_order_items(order_id)
            if not raw_items:
                print(f"[MainSalesOrder] No items for order {order_id} - skipping print.")
                return

            # ── Build ReceiptData ──────────────────────────────────────────
            co = get_defaults() or {}

            receipt = ReceiptData()
            receipt.companyName     = co.get("company_name", "Havano POS")
            receipt.companyLogoPath = co.get("logo_path", "")
            receipt.companyAddress  = co.get("address", "")
            receipt.tel             = co.get("phone", "")
            receipt.tin             = co.get("tin", "")
            receipt.vatNo           = co.get("vat_no", "")

            table_lbl = (
                order.get("table_name")
                or f"Table {order.get('table_number', order.get('table_id', ''))}"
            ).strip()

            receipt.receiptHeader = "*** SALES ORDER ***"
            receipt.invoiceNo     = f"{table_lbl} / KOT-{order.get('shift_order_number', order_id)}"
            receipt.invoiceDate   = datetime.now().strftime("%Y-%m-%d")
            receipt.orderNumber   = order.get("shift_order_number", order_id)
            receipt.customerName  = order.get("customer_name") or "Guest"
            receipt.cashierName   = get_waiter_name(order.get("waiter_id")) or "Waiter"
            receipt.bill_notes    = order.get("bill_notes", "")

            for it in raw_items:
                qty   = float(it.get("quantity") or it.get("qty") or 1)
                price = float(it.get("rate")     or it.get("price") or 0)
                receipt.items.append(Item(
                    productName = it.get("item_name") or it.get("product_name", ""),
                    productid   = str(it.get("product_id") or it.get("item_code") or ""),
                    qty         = qty,
                    price       = price,
                    amount      = qty * price,
                    item_notes  = it.get("item_notes") or it.get("notes", ""),
                ))

            receipt.grandTotal = sum(i.amount for i in receipt.items)
            receipt.footer     = "Thank you! Please pay at the counter."

            # ── Resolve invoice printer ────────────────────────────────────
            settings     = AdvanceSettings.load_from_file()
            printer_name = getattr(settings, "invoicePrinter", None) or None
            if printer_name == "(None)":
                printer_name = None

            # Fallback to hardware main_printer if invoicePrinter not set
            if not printer_name:
                try:
                    from models.hardware_settings import get_hardware_settings
                    hw = get_hardware_settings()
                    printer_name = hw.get("main_printer") or None
                    if printer_name == "(None)":
                        printer_name = None
                except Exception:
                    pass

            ok = PrintingService().print_invoice_receipt(receipt, printer_name=printer_name)
            if ok:
                print(f"[OK] Main sales order printed for ORD-{order_id} -> {printer_name or 'default'}")
            else:
                print(f"[!]  Main sales order print FAILED for ORD-{order_id}")

        except Exception as e:
            import traceback
            print(f"❌ _print_main_sales_order error: {e}\n{traceback.format_exc()}")

    def _toggle_offline(self):
        from models.company_defaults import get_defaults, save_defaults
        defaults = get_defaults() or {}
        current = defaults.get("work_offline") == "1"
        new_val = "0" if current else "1"
        defaults["work_offline"] = new_val
        save_defaults(defaults)
        
        # Update UI
        _off = (new_val == "1")
        self._offline_btn.setText("GO ONLINE" if _off else "GO OFFLINE")
        self._offline_btn.setStyleSheet(f"""
            QPushButton {{
                background-color: {SUCCESS if _off else DANGER};
                color: {WHITE}; border-radius: 4px; font-size: 10px; font-weight: bold;
            }}
            QPushButton:hover {{ background-color: {SUCCESS_H if _off else DANGER_H}; }}
        """)
        
        # Update mode label to show (OFFLINE)
        from services.credentials import get_system_mode
        _sys_mode = get_system_mode().upper()
        display_mode = "OFFLINE" if _off else _sys_mode
        
        if hasattr(self, "_mode_lbl"):
            self._mode_lbl.setText(f"  MODE: {display_mode}  ")
            self._mode_lbl.setStyleSheet(f"color: {WHITE if display_mode in ['ODOO','OFFLINE'] else MID}; font-weight: bold; font-size: 11px;")

        QMessageBox.information(self, "Offline Mode", 
            f"System is now {'OFFLINE' if _off else 'ONLINE'}.\n"
            f"{'Syncing paused.' if _off else 'Syncing resumed.'}")

