    def switch_to_pos(self):
        self._stack.setCurrentWidget(self._pos_view)
        if hasattr(self._pos_view, 'orders_btn'):
            self._pos_view.orders_btn.setChecked(False)
        self._set_status("POS mode  -  ready to sell.")

    def switch_to_orders(self):
        rv = self._ensure_restaurant_view_created()
        if rv:
            rv.refresh()
            self._stack.setCurrentWidget(rv)

    def _on_table_selected_from_restaurant(self, table_data: dict, append_mode: bool = False, force_new: bool = False):
        """Table picked in restaurant view -> Open it in POS cart. No reason prompt."""        # Always clear any stale modify reason - no prompts for adding orders
        if hasattr(self._pos_view, '_last_modify_reason'):
            self._pos_view._last_modify_reason = ""

        self.switch_to_pos()
        self._pos_view._pay_all_mode = False
        self._pos_view.link_to_table(table_data, append_mode=append_mode, force_new=force_new)
        self._set_status(f"Tables linked: {table_data.get('name')}")
        self._stack.setCurrentWidget(self._pos_view)

        # Proactively prompt for a shift right after login if none is running.
        QTimer.singleShot(150, self._pos_view._prompt_open_shift_if_missing)

    def _on_kot_action(self, action: str, order_data: dict):
        """Edit or Pay a specific KOT."""
        if action == "edit":
            from models.restaurant_order import get_cancel_reasons
            predefined_reasons = get_cancel_reasons()
            reason = self._show_cancel_reason_dialog(order_data["id"], predefined_reasons, title="Modify Reason", action_text="Modify KOT", is_danger=False)
            if reason is None or not reason.strip():
                return
            self._pos_view._last_modify_reason = reason.strip()

        self.switch_to_pos()
        td = {
            "id": order_data["table_id"],
            "name": order_data.get("table_name", "Table"),
            "table_number": order_data.get("table_number", ""),
            "capacity": 2, "floor": "Main", "status": "Occupied"
        }
        self._pos_view._pay_all_mode = False
        self._pos_view.link_to_table(td, append_mode=False, order_id=order_data["id"], edit_mode=(action == "edit"))
        self._set_status(f"KOT #{order_data['id']} loaded for {action.upper()}")
        if action == "pay":
            if not self._pos_view._check_permission("allow_pay_kot", "Order Payment"):
                return
            QTimer.singleShot(200, self._pos_view._open_payment)

    def _on_cancel_kot(self, order_id: int):
        """Cancel a specific KOT, optionally requiring a reason."""
        if not self._pos_view._check_permission("allow_cancel_kot", "Order Close"):
            return

        # ── Rich cancel-reason dialog (predefined chips + autocomplete) ──────────
        reason = ""
        try:
            from models.restaurant_order import get_restaurant_settings, get_cancel_reasons
            rs = get_restaurant_settings()
            predefined_reasons = get_cancel_reasons()
            reason = self._show_cancel_reason_dialog(order_id, predefined_reasons)
            if reason is None:
                return  # user dismissed
            reason = reason.strip()
            if rs.get("require_cancel_reason") and not reason:
                QMessageBox.warning(self, "Reason Required",
                                    "You must enter a reason to cancel this KOT.")
                return
        except Exception as _exc:
            print(f"[CancelKOT] reason dialog error: {_exc}")

        # Redundant confirmation removed because they already provided a reason.
        if True:
            from models.restaurant_order import cancel_order
            waiter_id = self.user.get("id") if isinstance(self.user, dict) else None
            if cancel_order(order_id, reason=reason.strip(), waiter_id=waiter_id):
                self._set_status(f"KOT #ORD-{order_id} cancelled.")
                
                # --- NEW: Print cancellation KOT to kitchen ---
                try:
                    from models.restaurant_order import get_order_by_id, get_order_items
                    order = get_order_by_id(order_id)
                    items = get_order_items(order_id)
                    if order and items:
                        # Build a sale-like dict for print_s
                        table_name = "N/A"
                        try:
                            from database.db import get_connection
                            conn = get_connection(); cur = conn.cursor()
                            cur.execute("SELECT name FROM restaurant_tables WHERE id = ?", (order["table_id"],))
                            row = cur.fetchone()
                            if row: table_name = str(row[0])
                            conn.close()
                        except: pass

                        # Map restaurant items to sale items format
                        for it in items:
                            if "item_name" in it and "product_name" not in it:
                                it["product_name"] = it["item_name"]
                            if "item_notes" in it and "notes" not in it:
                                it["notes"] = it["item_notes"]

                        sale_stub = {
                            "invoice_no": f"ORD-{order_id}",
                            "order_number": order_id,
                            "cashier_name": self.user.get("username", "Unknown") if isinstance(self.user, dict) else "Unknown",
                            "items": items,
                            "bill_notes": order.get("bill_notes", ""),
                            "customer_name": f"Table {table_name}",
                            "cancel_reason": reason,   # printed on cancellation KOT
                        }
                        from models.sale import print_s
                        import threading
                        threading.Thread(target=print_s, args=(sale_stub, True), daemon=True).start()
                except Exception as e:
                    print(f"Error printing cancellation: {e}")

                if self._restaurant_view:
                    self._restaurant_view.refresh()
                # Auto-logout if enabled
                self._restaurant_auto_logout()
            else:
                QMessageBox.warning(self, "Error", "Failed to cancel order.")

    def _show_cancel_reason_dialog(self, order_id: int, predefined: list, title: str = "Cancel Reason", action_text: str = "Cancel KOT", is_danger: bool = True):

        """

        Rich cancel-reason dialog matching the bill-notes popup style.

        Returns the entered reason string, or None if dismissed.

        The first predefined reason is pre-filled as the default.

        """

        default_reason = predefined[0] if predefined else ""



        dlg = QDialog(self)

        dlg.setWindowTitle(title)

        dlg.setFixedWidth(1100)

        dlg.setStyleSheet(

            f"QDialog {{ background: {WHITE}; border: 1px solid {NAVY}; border-radius: 12px; }}"

        )

        dlg.setWindowFlags(Qt.Dialog | Qt.FramelessWindowHint)



        root = QVBoxLayout(dlg)

        root.setContentsMargins(15, 12, 15, 12)

        root.setSpacing(8)



        chip_btns = []

        reason_input_ref = [None]  # mutable reference



        if predefined:

            chips_row = QHBoxLayout()

            chips_row.setSpacing(6)



            def _chip_style(active=False):

                if active:

                    return (

                        f"QPushButton {{"

                        f"  background: {ACCENT}; color: {WHITE};"

                        f"  border: 1px solid {ACCENT}; border-radius: 14px;"

                        f"  font-size: 12px; font-weight: 600; padding: 4px 12px;"

                        f"}}"

                    )

                return (

                    f"QPushButton {{"

                    f"  background: {OFF_WHITE}; color: {NAVY};"

                    f"  border: 1px solid {BORDER}; border-radius: 14px;"

                    f"  font-size: 12px; font-weight: 600; padding: 4px 12px;"

                    f"}}"

                    f"QPushButton:hover {{"

                    f"  background: {ACCENT_SOFT}; border-color: {ACCENT}; color: {ACCENT};"

                    f"}}"

                )



            # Show a maximum of 4 quick chips to prevent UI clutter and window stretching
            first_chip = True
            for r_txt in predefined[:4]:
                chip = QPushButton(r_txt)
                chip.setCursor(Qt.PointingHandCursor)
                chip.setCheckable(True)
                
                is_active = (first_chip and r_txt == default_reason)
                chip.setChecked(is_active)
                chip.setStyleSheet(_chip_style(is_active))
                first_chip = False
                
                chips_row.addWidget(chip)
                chip_btns.append((r_txt, chip))



            chips_row.addStretch()

            root.addLayout(chips_row)



        # ── Input row ──────────────────────────────────────────────────────

        inp_row = QHBoxLayout()

        inp_row.setSpacing(10)



        lbl = QLabel("Reason:")

        lbl.setStyleSheet(f"color: {NAVY}; font-size: 13px; font-weight: bold;")

        inp_row.addWidget(lbl)



        reason_input = QLineEdit(default_reason)

        reason_input.setPlaceholderText("Enter Reason…")

        reason_input.setFixedHeight(44)

        reason_input.setStyleSheet(

            f"QLineEdit {{"

            f"  border: 1px solid {BORDER}; border-radius: 8px;"

            f"  padding: 0 15px; font-size: 15px; color: {DARK_TEXT};"

            f"  background: {OFF_WHITE};"

            f"}}"

            f"QLineEdit:focus {{ border-color: {ACCENT}; background: {WHITE}; }}"

        )

        reason_input_ref[0] = reason_input



        if predefined:

            completer = QCompleter(predefined, reason_input)

            completer.setCaseSensitivity(Qt.CaseInsensitive)

            completer.setFilterMode(Qt.MatchContains)

            completer.setCompletionMode(QCompleter.PopupCompletion)

            completer.popup().setStyleSheet(

                f"QListView {{"

                f"  background: {WHITE}; border: 1px solid {BORDER};"

                f"  border-radius: 6px; font-size: 14px; color: {DARK_TEXT}; padding: 4px;"

                f"}}"

                f"QListView::item {{ padding: 8px 12px; }}"

                f"QListView::item:selected {{ background: {ACCENT}; color: {WHITE}; }}"

            )

            reason_input.setCompleter(completer)



            def _on_chip(txt, clicked_chip):

                reason_input.setText(txt)

                for _r, _c in chip_btns:

                    active = _c is clicked_chip

                    _c.setChecked(active)

                    _c.setStyleSheet(_chip_style(active))



            for r_text, c_btn in chip_btns:

                c_btn.clicked.connect(lambda _, t=r_text, b=c_btn: _on_chip(t, b))



            # Pre-select first chip

            if chip_btns:

                chip_btns[0][1].setChecked(True)

                chip_btns[0][1].setStyleSheet(_chip_style(True))



        inp_row.addWidget(reason_input, 1)



        ok_btn = QPushButton(action_text)

        ok_btn.setFixedSize(150, 44)

        ok_btn.setCursor(Qt.PointingHandCursor)

        ok_btn.setStyleSheet(

            f"QPushButton {{"

            f"  background: {DANGER}; color: {WHITE}; border: none;"

            f"  border-radius: 8px; font-size: 14px; font-weight: bold;"

            f"}}"

            f"QPushButton:hover {{ background: {DANGER_H}; }}"

        )

        ok_btn.clicked.connect(dlg.accept)

        inp_row.addWidget(ok_btn)



        dismiss_btn = QPushButton("Clear")

        dismiss_btn.setFixedSize(44, 44)

        dismiss_btn.setCursor(Qt.PointingHandCursor)

        dismiss_btn.setStyleSheet(

            f"QPushButton {{"

            f"  background: {OFF_WHITE}; color: {NAVY};"

            f"  border: 1px solid {BORDER}; border-radius: 8px; font-size: 18px;"

            f"}}"

            f"QPushButton:hover {{"

            f"  background: {WHITE}; border-color: {DANGER}; color: {DANGER};"

            f"}}"

        )

        dismiss_btn.clicked.connect(dlg.reject)

        inp_row.addWidget(dismiss_btn)



        reason_input.returnPressed.connect(dlg.accept)

        reason_input.setFocus()

        reason_input.selectAll()

        root.addLayout(inp_row)



        if dlg.exec() == QDialog.Accepted:

            return reason_input.text()

        return None



    def _restaurant_auto_logout(self):
        """
        Log out after a finalised restaurant transaction if the USER's
        auto_logout flag is enabled.

        NOTE: auto_logout is a PER-USER setting stored on the users table
        and managed via Settings -> Users.  There is no global/system-level
        auto-logout setting - that field has been removed from
        restaurant_settings to prevent duplication and confusion.
        """
        try:
            from models.restaurant_order import get_restaurant_settings
            rs = get_restaurant_settings()
            system_logout = rs.get("auto_logout_on_finalise", False)
            user_logout = self.user.get("auto_logout") if isinstance(self.user, dict) else False

            is_system_logout = str(system_logout).strip().lower() in ("true", "1")
            is_user_logout = str(user_logout).strip().lower() in ("true", "1")

            if is_system_logout or is_user_logout:
                from PySide6.QtCore import QTimer
                QTimer.singleShot(500, self._do_logout)
        except Exception:
            pass

    def _on_pay_all_orders(self, table_data: dict):
        """Load all orders for a table into the cart, pre-filling any collected shares."""
        if not self._pos_view._check_permission("allow_pay_kot", "Table Payment"):
            return
        # Auto-load any previously collected shares for this table
        try:
            from models.restaurant_order import get_bill_splits
            from collections import defaultdict
            splits = get_bill_splits(table_data["id"])
            if splits:
                agg: dict = defaultdict(float)
                for sp in splits:
                    agg[sp["mop_label"]] += float(sp.get("amount_raw", 0))
                self._pos_view._prefill_amounts = dict(agg)
            else:
                self._pos_view._prefill_amounts = None
        except Exception:
            self._pos_view._prefill_amounts = None

        self.switch_to_pos()
        self._pos_view._pay_all_mode = True
        self._pos_view.link_to_table(table_data, append_mode=False)
        self._set_status(f"Combined Payment for Table {table_data.get('table_number')}")
        QTimer.singleShot(200, self._pos_view._open_payment)


